begin;

insert into hadith (id, collection_id, chapter_id, number_in_book, kind, arabic, translation_en, narrator_ar, narrator_en, grade_ar, reference_ar, reference_en, reference_ur, full_ref_ar, explanation_ar, benefits_ar, word_meanings_ar, source, source_ref, daily_ok, review_note, deleted) values
(20481, 2, 201, 481, 'hadith', 'عن أبي عمرو، ويقال: أبو عبد الله: ويقال: أبو ليلى، عثمان ابن عفان، رضي الله عنه أن النبي صلى الله عليه وسلم، قال: « ليس لابن آدم حق في سوى هذه الخصال: بيت يسكنه، وثوب يواري عورته، وجلف الخبز، والماء».', 'The Prophet (ﷺ) said, "There is no right for the son of adam except in these (four) things: A house to live in, a cloth to cover therewith his private parts, bread and water.".', 'أبي عمرو، ويقال: أبو عبد الله: ويقال: أبو ليلى، عثمان ابن عفان رضي الله عنه', '''Uthman bin ''Affan (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 481', 'Riyad as-Salihin 481', 'ریاض الصالحین 481', 'رواه الترمذي وقال: حديث صحيح)) . ((قال الترمذي: سمعت أبا داود سليمان بن سالم البلخى يقول: سمعت النضر بن شميل يقول: الجلف: الخبز ليس معه إدام. قال غيره: هو غليظ الخبز. وقال الهروي: المراد به هنا وعاء الخبز؛ كالجوالق والخرج، والله أعلم', null, null, null, 'sunnah.com', null, false, null, false),
(20482, 2, 201, 482, 'hadith', 'عن عبد الله بن الشخير " بسكر الشين والخاء المشددة المعجمتين" رضي الله عنه، أنه قال: أتيت النبي ، صلى الله عليه وسلم، وهو يقرأ: { ألهاكم التكاثر} قال: " يقول ابن آدم: مالي، وهل لك يا ابن آدم من مالك إلا ما أكلت فأفنيت، أو لبست فأبليت، أو تصدقت فأمضيت؟ !".', 'I came to the Prophet (ﷺ) while he was reciting (Surat At-Takathur 102):"The mutual rivalry (for hoarding worldly things) preoccupy you. Until you visit the graves (i.e., till you die). Nay! You shall come to know! Again nay! You shall come to know! Nay! If you knew with a sure knowledge (the end result of hoarding, you would not have been occupied in worldly things). Verily, you shall see the blazing Fire (Hell)! And again, you shall see it with certainty of sight! Then (on that Day) you shall be asked about the delights (you indulged in, in this world)!" (102:1-8)(After reciting) he (ﷺ) said, "Son of adam says: ''My wealth, my wealth.'' Do you own of your wealth other than what you eat and consume, and what you wear and wear out, or what you give in Sadaqah (charity) (to those who deserve it), and that what you will have in stock for yourself.".', 'عبد الله بن الشخير " بسكر الشين والخاء المشددة المعجمتين" رضي الله عنه', '''Abdullah bin Ash-Shikhkhir (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 482', 'Riyad as-Salihin 482', 'ریاض الصالحین 482', 'رواه مسلم', null, null, null, 'sunnah.com', null, false, null, false),
(20483, 2, 201, 483, 'hadith', 'عن عبد الله بن مغفل، رضي الله عنه، قال: قال رجل للنبي صلى الله عليه وسلم يارسول الله، والله إنى لأحبك، فقال: " انظر ماذ تقول؟" قال: والله إنى لأحبك، ثلاث مرات، فقال: " إن كنت تحبنى فأعد للفقر تجفافاً، فإن الفقر أسرع إلى من يحبنى من السيل إلى منتهاه" ((رواه الترمذي وقال حديث حسن)). ''التجفاف بكسر التاء المثناه فوق وإسكان الجيم وبالفاء المكررة، وهو شىء يلبسة الفرس، ليتقي به الأذى، وقد يلبسة الإنسان.''', 'A man came to the Prophet (ﷺ) and said, "O Messenger of Allah! By Allah, I love you." He (ﷺ) said, "Think about what you are saying." The man repeated thrice, "I swear by Allah that I love you." He (Prophet (ﷺ)) said, "If you love me, you should be ready for acute poverty; because poverty comes to those who love me, faster than a flood flowing towards its destination.".', 'عبد الله بن مغفل رضي الله عنه', '''Abdullah bin Mughaffal (May Allah be pleased with him)', null, 'رياض الصالحين 483', 'Riyad as-Salihin 483', 'ریاض الصالحین 483', null, null, null, null, 'sunnah.com', null, false, null, false),
(20484, 2, 201, 484, 'hadith', 'عن كعب بن مالك، رضي الله عنه قال: قال رسول الله صلى الله عليه وسلم : « ما ذئبان جائعان أرسلا في غنم بأفسد لها من حرص المرء على المال والشرف، لدينه».', 'Messenger of Allah (ﷺ) said, "Two hungry wolves sent in the midst of a flock of sheep are no more destructive to them than a man''s greed for wealth and fame is to his Deen.".', 'كعب بن مالك رضي الله عنه', 'K''ab bin Malik (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 484', 'Riyad as-Salihin 484', 'ریاض الصالحین 484', 'رواه الترمذي وقال: حديث حسن صحيح', null, null, null, 'sunnah.com', null, false, null, false),
(20485, 2, 201, 485, 'hadith', 'عن عبد الله بن مسعود، رضي الله عنه، قال: نام رسول الله صلى الله عليه وسلم، على حصير، فقال وقد أثر في جنبه. قلنا: يا رسول الله لو اتخذنا لك وطاء! فقال: « مالي وللدنيا؟ ما أنا في الدنيا إلا كراكب استظل تحت شجرة ثم راح وتركها».', 'Messenger of Allah (ﷺ) slept on a straw mat and got up with the marks left by it on his body. Ibn Mas''ud (May Allah be pleased with him) said, "O Messenger of Allah! Would that you make us spread out a soft bedding for you." He (ﷺ) replied, "What have I to do with the world? I am like a rider who had sat under a tree for its shade, then went away and left it.".', 'عبد الله بن مسعود رضي الله عنه', '''Abdullah bin Mas''ud (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 485', 'Riyad as-Salihin 485', 'ریاض الصالحین 485', 'رواه الترمذي وقال: حديث حسن صحيح', 'ذكر عبد الله بن مسعود رضي الله عنه أن النبي صلى الله عليه وسلم نام على بِساط صغير مَنْسُوْج من بعض النبات، فقام وقد أثّر الحصير في جلد جنبه، فقلنا: 

يا رسول الله، لو اتخذنا لك فراشًا ليّنًا لكان أحسن من اضطجاعك على هذا الحصير الخشن، فقال صلى الله عليه وسلم: 

ليس لي محبة وأُلْفة مع الدنيا حتى أرغب إليها، فما مثلي والبقاء في الدنيا إلا كراكب استظل تحت شجرة ثم راح وتركها.', 'بيان ما كان عليه النبي صلى الله عليه وسلم من الزهد في الدنيا والإعراض عنها.
ليس في الحديث ترك ما لا بد منه من الدنيا، وإنما الانشغال بها عن الآخرة، فإن الرجل استظل بالشجرة واستفاد منها من أجل وصوله، ولم يركن إليها.
الاعتبار بحال النبي صلى الله عليه وسلم، فإنه الأسوة الحسنة، وأن من اقتفى آثاره اهتدى، وأفلح في الدنيا والآخرة.
حرص الصحابة رضي الله عنهم على رسول الله صلى الله عليه وسلم ومحبتهم له.
مشروعية ضرب الأمثال في الدعوة والتعليم.', null, 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/65814', false),
(20486, 2, 201, 486, 'hadith', 'عن أبي هريرة، رضي الله عنه، قال: قال رسول الله صلى الله عليه وسلم: « يدخل الفقراء الجنة قبل الأغنياء بخمسمائة عام».', 'Messenger of Allah (ﷺ) said, "The poor will enter Jannah five hundred years before the rich.".', 'أبي هريرة رضي الله عنه', 'Abu Hurairah (May Allah be pleased with him)', null, 'رياض الصالحين 486', 'Riyad as-Salihin 486', 'ریاض الصالحین 486', 'رواه الترمذي وقال: جديث صحيح', null, null, null, 'sunnah.com', null, false, null, false),
(20487, 2, 201, 487, 'hadith', 'عن ابن عباس، وعمران بن الحصين، رضي الله عنهم، عن النبي ، صلى الله عليه وسلم " قال " اطلعت في الجنة فرأيت أكثر أهلها الفقراء، واطلعت في النار فرأيت أكثر أهلها النساء".', 'The Prophet (ﷺ) said, "I looked into Jannah and saw that most of its dwellers are the poor; and I looked into Hell and saw that most of its inmates were women.".', 'ابن عباس، وعمران بن الحصين رضي الله عنهم', 'Ibn ''Abbas and ''Imran bin Al-Husain (May Allah be pleased with them)', 'صحيح', 'رياض الصالحين 487', 'Riyad as-Salihin 487', 'ریاض الصالحین 487', 'متفق عليه من رواية ابن عباس)). ((ورواه البخاري أيضاً من رواية عمران بن الحصين', 'يخبر النبي صلى الله عليه وسلم في الحديث أنه اطَّلَع في الجنة فرأى أكثرَ أهلِها الفقراءَ، وذلك لأن الفقراء ليس عندهم ما يطغيهم، فهم متمسكنون خاضعون، ولهذا من تأمل الآيات؛ وجد أن الذين يكذبون الرسل هم الملأ الأشراف والأغنياء، وأن المستضعفين هم الذين يتبعون الرسل، فلهذا كانوا أكثر أهل الجنة.
والحديث لا يوجب فضل كل فقير على كل غني، وإنما معناه الفقراء في الجنة أكثر من الأغنياء فأخبر عن ذلك، وليس الفقر أدخلهم الجنة، وإن كان خفف من حسابهم، إنما دخلوا بصلاحهم معه، فالفقير إذا لم يكن صالحاً لا يفضل.
كما أخبر صلى الله عليه وسلم أنه اطَّلَع في النار فرأى أكثرَ أهلِها النساء؛ وذلك لقيامهن بعادات سيئة تغلب على طباعهن، وتتعلق بهن، من ذلك كُفران العشير وكثرة اللعن.
فالواجب عليهن أن يحافظن على أمر الدين ليسلمن من النار.', 'أن الفقراء في الجنة أكثر من الأغنياء, والفقير لم يدخل الجنة بسبب فقره, وإنما دخلها بعمله الصالح.
التحريض على ترك التوسع في الدنيا والاستزادة من متاعها.
تحريض النساء على المحافظة على أمر الدين ليسلمن من النار, والإخبار بأنهن أكثر أهل النار.
أن الجنة والنار مخلوقتان موجودتان.
أن من أساليب الدعوة: الترهيب.', 'اطّلعت : أشرفت وتأملت.', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/3184', false),
(20488, 2, 201, 488, 'hadith', 'عن أسامة بن زيد، رضي الله عنهما، عن النبي صلى الله عليه وسلم قال: «قمت على باب الجنة، فكان عامة من دخلها المساكين. وأصحاب الجد محبوسون، غير أن أصحاب النار قد أمر بهم إلى النار».', 'The Prophet (ﷺ) said, "I stood at the gate of Jannah and saw that most of those who enter it were poor, whereas the rich were held back; but those who were destined to go to Hell were ordered to be sent there (immediately).".', 'أسامة بن زيد رضي الله عنهما', 'Usamah bin Zaid (May Allah be pleased with them)', 'صحيح', 'رياض الصالحين 488', 'Riyad as-Salihin 488', 'ریاض الصالحین 488', 'متفق عليه)). و(( الجد:الحظ والغنى. وقد سبق بيان هذا الحديث في باب فضل الضعفة', null, null, null, 'sunnah.com', null, false, null, false),
(20489, 2, 201, 489, 'hadith', 'عن أبي هريرة، رضي الله عنه، عن النبي صلى الله عليه وسلم، قال: «أصدق كلمة قالها شاعر كلمة لبيد: ألا كل شئ ما خلا الله باطل».', 'The Prophet (ﷺ) said, "The most truthful statement a poet has ever made is the saying of Labid: Everything besides Allah is vain.".', 'أبي هريرة رضي الله عنه', 'Abu Hurairah (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 489', 'Riyad as-Salihin 489', 'ریاض الصالحین 489', 'متفق عليه', null, null, null, 'sunnah.com', null, false, null, false),
(20490, 2, 201, 490, 'hadith', 'عن عائشة، رضي الله عنها ، قالت: ما شبع آل محمد، صلى الله عليه وسلم ، من خبز شعير يومين متتابعين حتى قبض. ((متفق عليه)). وفي رواية: ما شبع آل محمد، صلى الله عليه وسلم ، منذ قدم المدينة من طعام البر ثلاث ليال تباعاً حتى قبض.', 'The family of Muhammad (ﷺ) never ate to the fill the bread of barley for two successive days until he died..Another narration is: ''Aishah (May Allah be pleased with her) said: Never did the family of Muhammad (ﷺ) eat to the fill, since their arrival to Al-Madinah, the bread of wheat for three successive nights until his death.', 'عائشة رضي الله عنها', '''Aishah (May Allah be pleased with her)', 'صحيح', 'رياض الصالحين 490', 'Riyad as-Salihin 490', 'ریاض الصالحین 490', null, 'تخبر أم المؤمنين عائشة رضي الله عنها أن أهل بيت النبي صلى الله عليه وسلم لم يشبعوا منذ قدموا إلى المدينة من أكل البُرِّ ثلاثة أيام متتابعات حتى توفي صلى الله عليه وسلم.', 'بيان ما كان عليه النبي صلى الله عليه وسلم وأهله من قلة المعيشة، فإن العيش عيش الآخرة.
قال ابن حجر: والذي يظهر أن سبب عدم شبعهم غالبًا كان بسبب قلة الشيء عندهم، على أنهم كانوا قد يجدون ولكن يؤثرون على أنفسهم.', null, 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/65816', false),
(20491, 2, 201, 491, 'hadith', 'عن عروة عن عائشة، رضي الله عنها، أنها كانت تقول: والله يا ابن اختي إن كنا لننظر إلى الهلال، ثم الهلال: ثلاثة أهلة في شهرين، وما أوقد في أبيات رسول صلى الله عليه وسلم ، نار. قلت: يا خالة فما كان يعيشكم؟ قالت: الأسودان: التمر والماء، إلا أنه قد كان لرسول الله صلى الله عليه وسلم جيران من الأنصار، وكانت لهم منائح وكانوا يرسلون إلى رسول الله من ألبانها فيسقينا.', '"O son of my sister, by Allah, I used to see the new moon, then the new moon, then the new moon, i.e., three moons in two months, and a fire was not kindled in the house of Messenger of Allah (ﷺ). "I (''Urwah) said, "O my aunt, what were your means of sustenance?" She said; "Dates and water. But it (so happened) that Messenger of Allah (ﷺ) had some Ansar neighbours who had milch animals. They used to send Messenger of Allah (ﷺ) some milk of their (animals) and he gave that to us to drink.".', 'عروة عن عائشة رضي الله عنها', '''Urwah from ''Aishah (May Allah be pleased with her) reported that she used to say to Urwah (May Allah be pleased with him):', 'صحيح', 'رياض الصالحين 491', 'Riyad as-Salihin 491', 'ریاض الصالحین 491', 'متفق عليه', null, null, null, 'sunnah.com', null, false, null, false),
(20492, 2, 201, 492, 'hadith', 'عن أبي سعيد المقبري عن أبي هريرة رضي الله عنه، أنه مر بقوم بين أيديهم شاة مصلية، فدعوه فأبي أن يأكل، وقال: خرج رسول الله صلى الله عليه وسلم من الدنيا ولم يشبع من خبز الشعير. ((رواه البخاري)). ''مصلية'' بفتح الميم: أي: مشوية.', 'Abu Hurairah (May Allah be pleased with him) said that he happened to pass by some people who had a roast lamb before them. They invited him, but he declined, saying: "The Messenger of Allah (ﷺ) left the world without having eaten his fill with barley bread.".', 'أبي سعيد المقبري عن أبي هريرة رضي الله عنه', 'Abu Sa''id Maqburi', null, 'رياض الصالحين 492', 'Riyad as-Salihin 492', 'ریاض الصالحین 492', null, null, null, null, 'sunnah.com', null, false, null, false),
(20493, 2, 201, 493, 'hadith', 'عن أنس رضي الله عنه، قال: لم يأكل النبي صلى الله عليه وسلم على خوان حتى مات، وما أكل خبزاً مرققاً حتى مات.', 'The Prophet (ﷺ) neither ate on a dining cloth, nor ate soft bread throughout his life..One narration adds: He (ﷺ) never even saw a Samit lamb.Samit is an animal prepared for food by removing its hair by boiling water, and then roasted without being skinned. This type of food is preferred by wealthy people. (Editor''s Note)', 'أنس رضي الله عنه', 'Anas (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 493', 'Riyad as-Salihin 493', 'ریاض الصالحین 493', 'رواه البخاري)). (( وفي روايه له: ولا رأى شاة سميطاً بعينه قط', null, null, null, 'sunnah.com', null, false, null, false),
(20494, 2, 201, 494, 'hadith', 'عن النعمان بن بشير رضي الله عنهما قال: لقد رأيت نبيكم صلى الله عليه وسلم ، وما يجد من الدقل ما يملأ به بطنه.', 'I have seen your Prophet (ﷺ) when he did not find enough of even the inferior quality of dates to eat and fill his belly..', 'النعمان بن بشير رضي الله عنهما', 'An-Nu''man bin Bashir (May Allah be pleased with them)', 'صحيح', 'رياض الصالحين 494', 'Riyad as-Salihin 494', 'ریاض الصالحین 494', 'رواه مسلم)). ((الدقل: تمر رديء', null, null, null, 'sunnah.com', null, false, null, false),
(20495, 2, 201, 495, 'hadith', 'عن سهل بن سعد رضي الله عنه، قال: ما رأى رسول الله صلى الله عليه وسلم النقي من حين ابتعثة الله تعالى حتى قبضه الله تعالى، فقيل له: هل كان لكم في عهد رسول الله صلى الله عليه وسلم مناخل؟ قال: ما رأى رسول الله صلى الله عليه وسلم منخلا من حين ابتعثه الله تعالى حتى قبضه الله تعالى، فقيل له: كيف كنتم تأكلون الشعير غير منخول؟ قال: كنا نطحنه وننفخه، فيطير ما طار، وما بقى ثريناه.', 'Messenger of Allah (ﷺ) had never seen bread made out of fine flour throughout his life, since Allah commissioned him until his death. He was asked, "Did you not have sieves at the time of the Messenger of Allah?" He replied, "Messenger of Allah (ﷺ) never saw a sieve." He was asked, "How did you manage to eat barley bread made of unsieved flour?" He said, "We used to ground it and then blew away the husk, and what remained we kneaded into dough.".', 'سهل بن سعد رضي الله عنه', 'Sahl bin Sa''d (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 495', 'Riyad as-Salihin 495', 'ریاض الصالحین 495', 'رواه البخاري)). ((''قوله: النقي : هو بفتح النون وكسر القاف وتشديد الياء، وهو الخبز الحواري، وهو: الدرمك. قوله: ثريناه هو بثاء مثلثة، ثم راء مشدده، ثم ياء مثناة من تحت ثم نون، أي: بللناه وعجناه.''', null, null, null, 'sunnah.com', null, false, null, false),
(20496, 2, 201, 496, 'hadith', 'عن أبي هريرة رضي الله عنه قال: خرج رسول الله صلى الله عليه وسلم ذات يوم أو ليلة، فإذا هو بأبي بكر وعمر رضي الله عنهما، فقال: " ما أخرجكما من بيوتكما هذه الساعة؟" قالا: الجوع يا رسول الله. قال: " وأنا، والذي نفسي بيده، لأخرجني الذي أخرجكما. قوما" فقاما معه، فأتى رجلا من الأنصار، فإذا هو ليس في بيته، فلما رأته المرأة قالت: مرحباً وأهلا، فقال لها رسول الله صلى الله عليه وسلم "أين فلان؟" قالت ذهب يستعذب لنا الماء، إذ جاء الأنصاري، فنظر إلى رسول الله صلى الله عليه وسلم وصاحبيه، ثم قال: الحمد الله، ما أحد اليوم أكرم أضيافاً مني. فانطلق فجاءهم بعذق فيه بسر وتمر ورطب، فقال: كلوا وأخذ المدية فقال رسول الله صلى الله عليه وسلم " إياك والحلوب" فذبح لهم فأكلوا من الشاة ومن ذلك العذق وشربوا فلما أن شبعوا ورووا قال رسول الله صلى الله عليه وسلم لأبي بكر وعمر رضي الله عنهما: " والذي نفسي بيده، لتسألن عن هذا النعيم يوم القيامة، أخرجكم من بيوتكم الجوع، ثم لم ترجعوا حتى أصابكم هذا النعيم".', 'Messenger of Allah (ﷺ) went out (of his house) one day, or one night, and there he met Abu Bakr and ''Umar (May Allah be pleased with them) also. He (ﷺ) said, "What made you leave your houses at this hour?" They said, "It is hunger, O Messenger of Allah." He said, "By Him in Whose Hands my soul is, what made you leave, made me also leave, so come along!" And he went along with them to a man from the Ansar, but they did not find him in his house. When the wife of that man saw the Prophet, she said, "You are most welcome." Messenger of Allah (ﷺ) said to her, "Where is so-and-so?" She said, "He went to fetch some fresh water for us." In the meantime, the Ansari came back, saw Messenger of Allah (ﷺ) and his two companions and said: "Praise be to Allah, today no one has more honourable guests than I." He then went out and brought them a bunch of date fruit, having dates, some still green, some ripe, and some fully ripe, and requested them to eat from it. He then took his knife (to slaughter a sheep). Messenger of Allah (ﷺ) said to him, "Do not kill a milch sheep." So he slaughtered a sheep for them. After they had eaten and drunk to their fill, Messenger of Allah (ﷺ) said to Abu Bakr and ''Umar (May Allah be pleased with them), "By Him in Whose Hand my soul is, you will certainly be questioned about this treat on the Day of Resurrection. Hunger brought you out of your homes, and you do not return to your homes till you have been blessed with this treat.".', 'أبي هريرة رضي الله عنه', 'Abu Hurairah (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 496', 'Riyad as-Salihin 496', 'ریاض الصالحین 496', 'رواه مسلم)). ((قولها: يستعذب أي: يطلب الماء العذب، وهو الطيب. و العذق بكسر العين وإسكان الذال المعجمة: وهو الكباسة، وهي الغضن. و المدية بضم الميم وكسرها: هي السكين. و الحلوب ذات اللبن. والسؤال عن الأنصاري الذي أتوه هو أبو الهيثم بن التيهان رضي الله عنه، كذا جاء مبيناً في رواية الترمذي وغيره', 'خرج النبي صلى الله عليه وسلم في يوم أو في ليلة، فوجد أبا بكر وعمر رضي الله عنهما خارجين كذلك، فقال: ما الذي أخرجكما من بيوتكما في هذه الساعة؟ قالا: أخرجنا الجوع، يا رسول الله، قال: وأنا والذي نفسي بيده، أخرجني الجوع الذي أخرجكما، قوموا، فقاموا معه، فجاء إلى رجل من الأنصار، فلم يكن في بيته، فلما رأته زوجته قالت: مرحبًا وأهلًا، فقال لها النبي عليه الصلاة والسلام: أين فلان؟ قالت: ذهب ليأتينا بماءٍ عَذْبٍ، فجاء الأنصاري فرأى النبي عليه الصلاة والسلام وأبا بكر وعمر، ثم قال: الحمد لله لا يوجد أحد اليوم له ضيوف كرامٌ أكرم من ضيوفي، فذهب فجاء بغصن من النخل فيه بسر، وهو التمر قبل نضوجِه، وتمر ويكون يابسًا، ورطب وهو التمر الناضج، فقال الأنصاري: كلوا من هذه، وأخذ السكين؛ ليذبح لهم، فقال له النبي عليه الصلاة والسلام: احذر ذبح الناقة ذات اللبن، فذبح لهم، فأكلوا من الشاة ومن التمر، وشربوا من الماء العذب، فلما شبعوا وارتووا، قال النبي صلى الله عليه وسلم لأبي بكر وعمر: والذي نفسي بيده ليسألنكم الله عن هذا النعيم يوم القيامة، أخرجكم من بيوتكم الجوع، ثم لم ترجعوا إليها حتى أصابكم هذا النعيم حيث أكلتم وشربتم، فزال جوعكم.', 'جواز استتباع الإنسان غيره إلى دار من يثق برضاه بذلك، ويتحقق منه الرضا تحقُّقًا تامًّا.

ما كان القوم عليه في أول الإسلام، من ضيق الحال.

جواز ذكر الإنسان ما يناله من ألم ونحوه، لا على سبيل التشكي، وعدم الرضا، بل للتسلية والتصبر؛ ولالتماس دعاء، أو مساعدة على التسبب في إزالة ذلك العارض، فهذا كله ليس بمذموم، إنما يذم ما كان تشكّيًا وتسخّطًا وتجزّعًا.

جواز النزول على الصديق الذي يوثق به بدون موعد والأكل من ماله بطيب نفسٍ منه.

منقبة لهذا الصحابي الجليل رضي الله عنه، وهو أبو الهيثم بن التَّيِّهان؛ إذ جعله النبي صلى الله عليه وسلم أهلًا لضيافته وصاحبيه، وكفى به ذلك شرفًا.

استحباب الاجتماع على الطعام.

مشروعية الضيافة، وبر الضيف بكل ما يمكن.

حُسن إكرام الضيف بقول: "مرحبا، وأهلا"، ونحوه، وإظهار السرور بقدومه.

جواز سماع كلام الأجنبية، ومراجعتها الكلام للحاجة، دون الخضوع بالقول.

جواز إذن المرأة في دخول منزل زوجها لمن علمت علمًا محققًا أنه لا يكرهه، بحيث لا يخلو بها الخلوة المحرمة.

استحباب حمد الله تعالى عند حصول نعمة ظاهرة، وكذا يستحب عند اندفاع نقمة كانت متوقعة، وفي غير ذلك من الأحوال.

إظهار البشر والفرح بالضيف في وجهه، وحمد الله تعالى، وهو يسمع على حصول هذه النعمة، والثناء على ضيفه إن لم يخف عليه فتنة، فإن خاف لم يثن عليه في وجهه، وهذا طريق الجمع بين الأحاديث الواردة بجواز ذلك ومنعه.

تقديم الفاكهة على الخبز واللحم وغيرهما.

استحباب المبادرة إلى الضيف بما تيسر، ثم إكرامه بطعام يصنعه له.

جواز الشبع أحيانا، وأما ما جاء في ذم الشبع فمحمول على المداومة عليه؛ لأنه يقسي القلب، وينسي أمر المحتاجين.

كراهية ذبح ما يجري نفعه كراهية إرشاد لا كراهية تحريم.

مشروعية استعذاب الماء وتخيره، وكان تبريده بالريح وغير ذلك مما في معناه.

الناس سيسألون يوم القيامة عن نعيم الدنيا كلها، من أين حصلوا عليه، وفي أي شيء أنفقوه.

جواز الجمع بين طعامين فأكثر على مائدة واحدة.', 'عذق: مثل العنقود في النخلة.

بسر: ثمرة النخل قبل أن يصبح رطبًا.

الحلوب: الشاة التي فيها حليب.', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/66018', false),
(20497, 2, 201, 497, 'hadith', 'عن خالد بن عمر العدوي قال: خطبنا عتبة بن غزوان، وكان أمير على البصرة، فحمد الله وأثنى عليه، ثم قال: أما بعد؛ فإن الدنيا قد آذنت بصرم، وولت حذاء، ولم يبق منها إلا صبابة كصبابة الإناء يتصابها صاحبها، وإنكم منتقلون منها إلى دار لا زوال لها، فانتقلوا بخير ما بحضرتكم، فإنه قد ذكر لنا أن الحجر يلقى من شفير جنهم فيهوي فيها سبعين عاماً، لا يدرك لها قعراً، والله لتملأن ...أفعجبتم!؟ ولقد ذكر لنا أن ما بين مصراعين من مصاريع الجنة مسيرة أربعين عاماً، وليأتين عليه يوم وهو كظيظ من الزحام، ولقد رأيتني سابع سبعة مع رسول الله، صلى الله عليه وسلم ما لنا طعام إلا ورق الشجر، حتى قرحت أشداقنا، فالتقطت بردة فشققتها بيني وبين سعد بن مالك، فاتزرت بنصفها، واتزر سعد بنصفها، فما أصبح اليوم منا أحد إلا أصبح أميراً على مصر من الأمصار، وإني أعوذ بالله أن أكون في نفسي عظيماً، وعند الله صغيراً. ((رواه مسلم)). قوله: آذنت هو بمد الألف، أي: أعلمت. وقوله: بصرم : هو بضم الصاد، أي بانقطاعها وفنائها. وقوله وولت حذاء هو بحاء مهملة مفتوحة، ثم ذال معجمة مشددة، ثم ألف ممدودة، أي: سريعة. و الصبابة بضم الصاد المهملة: وهي البقية اليسيرة. وقوله: يتصابها هو بتشديد الباء قبل الهاء، أي: يجمعها. و الكظيظ : الكثير الممتليء. وقوله: قرحت هو بفتح القاف وكسر الراء، أي: صارت فيها قروح.', '''Utbah bin Ghazwan, the governor of Basrah, delivered a Khutbah. He praised Allah, glorified Him, then said: "Amma b''adu, verily, the world has been given the news of its end and is running to meet its end swiftly. Nothing is left out of it but a very little amount. Similar to the remainder in a dish whose owner is collecting it to drink; and you are going to move to an abode which knows no end, and you should proceed there with the good before you, for we have been informed (by the Prophet (ﷺ)) that a stone would be thrown at one side of the Hell and it would travel down for seventy years but would not reach its bottom. By Allah, it will be filled (with men and jinn). Do you find it strange? We have been informed (i.e., by the Prophet (ﷺ)) that the distance between two shutters of the gate of Jannah is forty years (distance). And a day would come when it would be fully packed; I was the seventh amongst the seven who had been with Messenger of Allah (ﷺ), and we had nothing to eat but the leaves of the tree until the sides of our mouth were injured. We found a sheet which we tore into two and divided between myself and Sa''d bin Malik. I made the lower garment with half of it and so did Sa''d. Today, there is none amongst us who has not become the governor of a city, and I seek refuge with Allah that I should consider myself great while I am insignificant to Allah.".', null, 'Khalid bin ''Umar Al-''Adawi', null, 'رياض الصالحين 497', 'Riyad as-Salihin 497', 'ریاض الصالحین 497', null, null, null, null, 'sunnah.com', null, false, null, false),
(20498, 2, 201, 498, 'hadith', 'عن أبي موسى الأشعري رضي الله عنه قال: أخرجت لنا عائشة رضي الله عنها كساء وإزاراً غليظاً قالت: قبض رسول الله صلى الله عليه وسلم في هذين.', '''Aishah (May Allah be pleased with her) showed us a sheet and a thick lower garment and said to us Messenger of Allah (ﷺ) was wearing them when he died..', 'أبي موسى الأشعري رضي الله عنه', 'Abu Musa Al-Ash''ari (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 498', 'Riyad as-Salihin 498', 'ریاض الصالحین 498', 'متفق عليه', null, null, null, 'sunnah.com', null, false, null, false),
(20499, 2, 201, 499, 'hadith', 'عن سعيد بن أبي وقاص، رضي الله عنه، قال: إني لأول العرب رمي بسهم في سبيل الله، ولقد كنا نغزو مع رسول الله صلى الله عليه وسلم ما لنا طعام إلا ورق الحلبة، هذا السمر، حتى إن كان أحدنا ليضع كما تضع الشاة ما له خلط. ((متفق عليه)). « الحلبة» بضم الحاء المهملة وإسكان الباء الموحدة: وهي والسمر، نوعان معروفان من شجر البادية.', 'By Allah, I am the first Arab who shot an arrow in the Cause of Allah. We fought along with Messenger of Allah (ﷺ) when our food was only the leaves of Hublah and Samur trees (wild trees) until one of us would defecate like the droppings of sheep..', 'سعيد بن أبي وقاص رضي الله عنه', 'Sa''d bin Abu Waqqas (May Allah be pleased with him)', null, 'رياض الصالحين 499', 'Riyad as-Salihin 499', 'ریاض الصالحین 499', null, null, null, null, 'sunnah.com', null, false, null, false),
(20500, 2, 201, 500, 'hadith', 'عن أبي هريرة، رضي الله عنه، قال: قال رسول الله، صلى الله عليه وسلم : " اللهم اجعل رزق آل محمد قوتاً" ((متفق عليه)). قال أهل اللغة والغريب: معنى " قوتاً" أي: ما يسد الرمق.', 'Messenger of Allah (ﷺ) used to supplicate: "O Allah, make the provisions of family of Muhammad (ﷺ) bare subsistence.".', 'أبي هريرة رضي الله عنه', 'Abu Hurairah (May Allah be pleased with him)', null, 'رياض الصالحين 500', 'Riyad as-Salihin 500', 'ریاض الصالحین 500', null, null, null, null, 'sunnah.com', null, false, null, false),
(20501, 2, 201, 501, 'hadith', 'عن أبي هريرة رضي الله عنه قال: والله الذي لا إله إلا هو، إن كنت لأعتمد بكبدي على الأرض من الجوع، وإن كنت لأشد الحجر على بطني من الجوع. ولقد قعدت يوماً على طريقهم الذي يخرجون منه، فمر بي النبي، صلى الله عليه وسلم ، فتبسم حين رآني، وعرف ما في وجهي وما في نفسي، ثم قال: " أبا هر" قلت لبيك يا رسول الله، قال: " الحق" ومضى فاتبعته، فدخل فاستأذن، فأذن لي فدخلت، فوجد لبنا في قدح فقال: " من أين هذا اللبن؟" قالوا: أهداه لك فلان- أو فلانة- قال:" أبا هر" قلت: لبيك يارسول الله، قال: " الحق إلى أهل الصفة فادعهم لي" قال: وأهل الصفة أضياف الإسلام، لا يأوون على أهل، ولا مال، وإذا أتته هدية أرسل إليهم، وأصاب منها وأشركهم فيها، فساءني ذلك فقلت: وما هذا اللبن في أهل الصفة! كنت أحق أن أصيب من هذا اللبن شربة أتقوى بها، فإذا جأووا وأمرني فكنت أنا أعطيهم؛ وما عسى أن يبلغني من هذا اللبن، ولم يكن من طاعة الله وطاعة رسوله، صلى الله عليه وسلم بد، فأتيتهم فدعوتهم، فأقبلوا واستأذنوا، فأذن لهم وأخذوا مجالسهم من البيت قال:" يا أبا هر" قلت: لبيك يا رسول الله قال: " خذ فأعطهم" قال: فأخذت القدح، فجعلت أعطيه الرجل فيشرب حتى يروى، ثم يرد علي القدح، فأعطيه الآخر فيشرب حتى يروى، ثم يرد علي القدح حتى انتيهت إلى النبي صلى الله عليه وسلم ، وقد روي القوم كلهم، فأخذ القدح فوضعه على يده، فنظر إلي فتبسم، فقال: " أبا هر" قلت: لبيك يا رسول الله، قال: " بقيت أنا وأنت" قلت: صدقت يا رسول الله، قال: " اقعد فاشرب" فقعدت فشربت: فقال: " اشرب" فشربت، فما زال يقول: " اشرب" حتى قلت: لا والذي بعثك بالحق ما أجد له مسلكاً! قال: " فأرني" فأعطيته القدح، فحمد الله تعالى، وسمى وشرب الفضلة".', 'By Allah other than Whom there is none worthy of worship, I used to press my stomach against the earth owing to my hunger; I would tie a stone over it. One day, I was sitting on the way they usually take when the Prophet (ﷺ) passed by me. When he saw me he smiled at me and knew my condition and my feelings. He called me and I replied, "At your service, O Messenger of Allah." He said, "Follow me." So I followed him. Having arrived at home, he sought permission and entered. He allowed me in and I, too, entered. He found milk in a bowl and asked, "Where is this from?" He was told that it was a gift for him from so- and-so. He called me and I responded: "At your service, O Messenger of Allah." He said, "Go to the people of As-Suffah and usher them in." He Abu Hurairah (May Allah be pleased with him) explained: The people of As-Suffah were guests of Islam; they had no family, no property and no relations. When Messenger of Allah (ﷺ) used to receive something in charity, he would send it to them without taking anything from it. When he received a present, he would send for them and share it with them. On this occasion, I disliked to give them anything. I said to myself: "This meagre quantity of milk will not be enough for all the people of As-Suffah! I am more deserving of it than anyone else. By drinking it I may attain some strength. When they come, he will order me to give it to them. I do not expect that anything will be left for me from this milk." As there was no alternative but to obey Allah and His Messenger (ﷺ). I went and called them. They came and sought permission which was granted. They took their seats. The Prophet (ﷺ) called me and I responded, "At your service, O Messenger of Allah." He then said, "Take the milk and give it to them." I took the bowl and gave it to one man who drank his fill and returned it to me, and I gave it to the next and he did the same. I went on doing this till the bowl reached Messenger of Allah (ﷺ). By that time all had taken their fill. He (ﷺ) took the bowl, put it on his hand, looked at me, smiled and said, "Abu Hirr." I said, "At your service, O Messenger of Allah." He said, "Now you and I are left." I said, "That is true, O Messenger of Allah." He said, "Sit down and drink." I drank, but he went on saying, "Drink some more." I said, "By Him Who has sent you with the Truth, I have no room for it." He said, "Then give it to me." So I gave him the bowl. He praised Allah, uttered the Name of Allah and drank the remainder..', 'أبي هريرة رضي الله عنه', 'Abu Hurairah (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 501', 'Riyad as-Salihin 501', 'ریاض الصالحین 501', 'رواه البخاري', 'قال أبو هريرة: والله الذي لا إله إلا هو أني كنتُ أُلْصِقُ بطني بالأرض من شدة الجوع، وكنت أشد الحجر على بطني؛ لتقليل حرارة الجوع، فقعدت يومًا على طريق النبي صلى الله عليه وسلم وبعض أصحابه الذي يخرجون إليه من منازلهم في طريقهم إلى المسجد، فمرَّ أبو بكر رضي الله عنه، فسألتُه عن آية من كتاب الله عز وجل، لم أسأله عنها إلا ليدعوني أن أتبعه ليطعمني، فمر ولم يطلب مني، ثم مر بي عمر رضي الله عنه، فسألته عن آية من كتاب الله عز وجل، وما سألته عنها إلا ليدعوني أن أتبعه ليطعمني، فمرَّ ولم يطلب مني شيئًا، ثم مرّ بي أبو القاسم صلى الله عليه وسلم، فتبسم حين رآني وعرف ما في نفسي من الجوع، وما في وجهي من التغير، واستدل أبو هريرة بتبسمه صلى الله عليه وسلم على أنه عرف ما به؛ لأن التبسم يكون لإيناس من يتبسم إليه، ثم قال صلى الله عليه وسلم: يا أبا هر، قلت: لبيك يا رسول الله، قال: اتبعني، ومضى فتبعته فدخل إلى أهله، فاستأذن فأُذِن لي، فدخلنا، فوجد صلى الله عليه وسلم في منزله لبنًا في كوزٍ، فقال: من أين هذا اللبن؟ قال أهله: أهداه لك فلان أو فلانة، ثم قال عليه الصلاة والسلام: يا أبا هر، قلت: لبيك يا رسول الله، قال: انطلق إلى أهل الصُّفَّة -وهو مكان في المسجد النبوي يأوي إليه من لا منزل له ولا أهل، كما سيأتي- فادعهم لي، قلت: وأهل الصفة أضياف الإسلام وهم أناس فقراء لا منازل لهم ولا أهل، فكانوا ينامون في المسجد لا مأوى لهم غيره، إذا جاءت للنبي صلى الله عليه وسلم صدقة بعث بها إليهم يخصهم بها، ولم يتناول منها شيئًا، وإذا جاءته هدية أرسل إليهم ليحضروا عنده، وأصاب منها وأشركهم فيها؛ لأنه صلى الله عليه وسلم كان يقبل الهدية ولا يقبل الصدقة، قال أبو هريرة في نفسه: فساءني قوله ادعهم لي، وما قَدْرُ هذا اللبن من أهل الصفة على كثرتهم ومعهم رسول الله صلى الله عليه وسلم ومعي؟ أنا كنت أولى أن أشرب من هذا اللبن شربةً أتقوَّى بها، فإذا جاء الناس الذي أمرني عليه الصلاة والسلام بدعوتهم أمرني عليه الصلاة والسلام فكنت أنا أعطيهم اللبن، وما عسى أن يصل إلي بعد أن يكتفوا منه، وهو كوز واحد، وهذا من حديث النفس المعفو عنه، وكان لابد من طاعة الله وطاعة رسوله صلى الله عليه وسلم، فجئتهم فدعوتهم فأقبلوا فاستأذنوا في الدخول، فأذن لهم صلى الله عليه وسلم، وجلسوا، فأمرني عليه الصلاة والسلام أن أعطيهم اللبن، فأخذتُ القَدَح، فكنت أعطيه الرجل فيشرب حتى يَروى، ثم يعطيني القدح، فأعطيه الرجل بعده فيشرب حتى يروى، ثم يعطيني القدح، فأعطيتهم واحدًا بعد واحد وشربوا جميعهم واكتفوا، وكان آخرهم النبي صلى الله عليه وسلم، فأخذ القدح وقد بقيت فيه فضلة لبن فوضعه على يده الكريمة، فنظر إلي فتبسم إشارة إلى أنه لم يفته شيء مما كان يظن فواته من اللبن، فقال: يا أبا هر، قلت: لبيك يا رسول الله، قال: تبقى أنا وأنت، قلت: صدقت يا رسول الله، فأمرني أن أقعد فأشرب، فقعدت فشربت، فقال: اشرب، فشربت فما زال يقول اشرب حتى قلت: لا والذي بعثك بالحق ما أجد له مكانًا، قال: فأعطني فأعطيته القدح فحمد الله عز وجل على البركة حيث روي القوم كلهم وتبقى منه، وسمى الله وشرب الفضلة المتبقية من اللبن.', 'استحباب الشرب من قعود.

ظهور هذه المعجزة العظيمة من علامات النبوة.

جواز الشبع أحيانًا.

كتمان الحاجة أولى من إظهارها.

كرم النبي صلى الله عليه وسلم وإيثاره على نفسه، وتواضعه مع أصحابه، وينبغي أن يكون قدوةً لكل قائد مسلم. 

ساقي القوم آخرهم شربًا.

استحباب الحمد على النعم والتسمية قبل الشرب.', 'أعتمد بكبدي: ألصق بطني بالأرض.

قدح: الإناء الذي يؤكل فيه أو يشرب.', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/66349', false),
(20502, 2, 201, 502, 'hadith', 'عن محمد بن سيرين عن أبي هريرة، رضي الله عنه، قال: لقد رأيتني وإني لأجر فيما بين منبر رسول الله، صلى الله عليه وسلم، إلى حجرة عائشة رضي الله عنها مغشياً علي، فيجيء الجائي، فيضع رجلة على عنقي، ويرى أني مجنون وما بي من جنون، ما بي إلا الجوع.', 'Abu Hurairah (May Allah be pleased with him) said: "I would fall in swoon between the pulpit of (the mosque of) Messenger of Allah (ﷺ) and the chamber of ''Aishah (May Allah be pleased with her) and every passer-by would put his foot on my neck thinking I was insane. I was not insane but I was awfully hungry.".', 'محمد بن سيرين عن أبي هريرة رضي الله عنه', 'Muhammad bin Sirin (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 502', 'Riyad as-Salihin 502', 'ریاض الصالحین 502', 'رواه البخاري', null, null, null, 'sunnah.com', null, false, null, false),
(20503, 2, 201, 503, 'hadith', 'عن عائشة، رضي الله عنها قالت: توفي رسول الله صلى الله عليه وسلم ودرعه مرهونة عند يهودي في ثلاثين صاعاً من شعير.', 'When Messenger of Allah (ﷺ) died, his armour was mortgaged with a Jew for thirty Sa'' (measures) of barley..', 'عائشة رضي الله عنها', '''Aishah (May Allah be pleased with her)', 'صحيح', 'رياض الصالحين 503', 'Riyad as-Salihin 503', 'ریاض الصالحین 503', 'متفق عليه', 'توفي النبي صلى الله عليه وسلم وكانت درعه محبوسة بسبب الدين عند يهودي، بسبب أنه صلى الله عليه وسلم أخذ منه ثلاثين صاعًا من شعير، لينفقها على أهل بيته، وقد يكون هذا اليهودي دخل المدينة لتجارة أو أمر عارض بعد إجلاء عامة اليهود، والحكمة في عدوله صلى الله عليه وسلم عن معاملة مياسير الصحابة إلى معاملة اليهود، إما لبيان الجواز، أو لأنهم لم يكن عندهم إذ ذاك طعام فاضل عن حاجة غيرهم، أو خشي أنهم لا يأخذون منه ثمنًا أو عوضًا، فلم يرد التضييق عليهم؛ فإنه لا يبعد أن يكون فيهم إذ ذاك من يقدر على ذلك، وأكثر منه، فلعله صلى الله عليه وسلم لم يطلعهم على ذلك، وإنما أطلع عليه من لم يكن موسرًا به ممن نقل ذلك، والله تعالى أعلم.', 'جواز الرهن عند الشراء إلى أجل.

جواز رهن آلة الحرب عند أهل الذمة.

جواز الرهن في الحضر.

جواز معاملة الكفار فيما لم يتحقق تحريم عين المتعامل فيه، وعدم الاعتبار بفساد معتقدهم أو معاملاتهم فيما بينهم، لكن لا يجوز للمسلم أن يبيع أهل الحرب سلاحًا وآلة حرب، ولا ما يستعينون به في إقامة دينهم.

جواز معاملة من أكثر ماله حرام.

جواز بيع السلاح ورهنه وإجارته، وغير ذلك من الكافر، ما لم يكن حربيًا.

ثبوت أملاك أهل الذمة في أيديهم.

جواز الشراء بالثمن المؤجل.

جواز اتخاذ الدروع والعدد وغيرها من آلات الحرب، وأنه غير قادح في التوكل.

فضيلة أزواجه صلى الله عليه وسلم لصبرهن معه على ذلك رضي الله تعالى عن جميعهن.

ما كان عليه النبي صلى الله عليه وسلم من التقلل من الدنيا مع قدرته عليها، وإيثار الآخرة، والكرم الذي أفضى به إلى عدم الادخار، حتى احتاج إلى رهن درعه، والصبر على ضيق العيش، والقناعة باليسير.', '-', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/66139', false),
(20504, 2, 201, 504, 'hadith', 'عن أنس رضي الله عنه قال: رهن النبي صلى الله عليه وسلم درعه بشعير، ومشيت إلى النبي صلى الله عليه وسلم بخبز شعير، وإهالة سنخة، ولقد سمعته يقول: « ما أصبح لآل محمد صاع ولا أمسى» وإنهم لتسعة أبيات.', 'The Prophet (ﷺ) mortgaged his armour for a quantity of barley, and I took to him some barley bread and rancid fat. I heard him saying: "The family of Muhammad never possessed a measure of wheat from dawn to dusk although they were nine houses (to feed).".', 'أنس رضي الله عنه', 'Anas (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 504', 'Riyad as-Salihin 504', 'ریاض الصالحین 504', 'رواه البخاري)). (( الإهالة بكسر الهمزة: الشحم الذائب. و السخنة بالنون والخاء المعجمة؛ وهي: المتغيرة', null, null, null, 'sunnah.com', null, false, null, false),
(20505, 2, 201, 505, 'hadith', 'عن أبي هريرة، رضي الله عنه، قال: لقد رأيت سبعين من أهل الصفة، ما منهم رجل عليه رداء، إما إزار وإما كساء، قد ربطوا في أعناقهم منها ما يبلغ نصف الساقين، ومنها ما يبلغ الكعبين، فيجمعه بيده كراهية أن ترى عورته.', 'I saw seventy of the people of As-Suffah and none of them had a cloak. They had either a lower cloth or a blanket which they suspended from their necks. Some reached half way down to the legs and some to the ankles, and one of them would manage to keep it in his hand to avoid exposing his private parts..', 'أبي هريرة رضي الله عنه', 'Abu Hurairah (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 505', 'Riyad as-Salihin 505', 'ریاض الصالحین 505', 'رواه البخاري', 'أهل الصفة هم أصحاب النبي صلى الله عليه وسلم من المهاجرين الفقراء الذين تركوا ديارهم وأموالهم في مكة وهاجروا منها إلى المدينة بعد أن كانت أحب البلاد إليهم.
وكان أهل الصفة أكثر من سبعين رجلاً، والصفة سقيفة مظللة كانت موجودة في آخر مسجد النبي صلى الله عليه وسلم ينام تحتها هؤلاء الفقراء من المهاجرين.
أما ثيابهم التي كانوا يرتدونها في الصيف وفي الشتاء فيخبرنا عنها أبو هريرة رضي الله عنه وقد كان أحد أصحاب الصفة فيقول: (ما منهم رجل عليه رداء إما إزار وإما كساء)، إذ إنه من أجل أن يلبس أحدهم رداء لا بد أن يلبس تحته إزارا فالرداء يقال عنه اليوم البدلة وكانت تسمى أيضا حُلة، وأبو هريرة يذكر أن أحدهم ما كان يلقى هذا الشيء، بل هو ثوب واحد يستر به نفسه من أعلى إلى أسفل يشبه ما يسمى اليوم الملاية القصيرة.
قال أبو هريرة: (قد ربطوا في أعناقهم) أي: يربطها أحدهم في رقبته كما يربط الصبي ثوبه في رقبته؛ لأنه لا يكفيه الثوب الذي عليه أن يفصله ويلبسه، وإنما طرفه في رقبته رضي الله عنهم. 
ثم قال أبو هريرة: (فمنها ما يبلغ نصف الساقين) أي: أن الطول لهذا الثوب من المنكب إلى نصف الساقين، فلا يصل إلى الكعبين.
ثم قال: (ومنها ما يبلغ الكعبين فيجمعه بيده كراهية أن ترى عورته) أي: أنه في أثناء الصلاة يلمه على نفسه حتى لا ترى عورته وهو راكع أو ساجد رضي الله تبارك وتعالى عنهم أجمعين.
وهذا هو حال كثير من الصحابة رضي الله عنهم، فقد عاشوا على الفقر والحاجة ولم يركنوا إلى الدنيا وزينتها، حتى لما فتحت عليهم الدنيا لم ينشغلوا بها ، وظلوا على قناعتهم وزهدهم، حتى توفاهم الله تعالى.', 'جواز لبس الثوب الواحد.
جواز المبيت في المسجد.
زهد أهل الصفة وانقطاعهم للعلم والجهاد في سبيل الله.
فيه دليل على أنه ليس من شرط صحة الصلاة ستر العاتقين.
حرص المؤمن على ستر عورته.
فضيلة الصحابة رضي الله عنهم، وصبرهم على الفقر، وضيق الحال، والاجتزاء من اللباس على ما يستر العورة، وقد أثابهم الله على ذلك فاستخلفهم في الأرض، ومكن لهم دينهم وبدلهم من بعد فقرهم غنى، ومن بعد خوفهم أمنا مع ما أعد الله لهم في الآخرة من الثواب في الجنة.', 'أهل الصفة : زهاد من الصحابة ؛ فقراء غرباء ، كانوا يأوون إلى صفة في آخر مسجد النبي صلى الله عليه وسلم، وهي موضع مظلل كانت تأوي إليه المساكين.
رداء : ما يستر أعالي البدن فقط من ثوب ونحوه.
الإزار : ما يستر أسافل البدن فقط.
الكساء : اللباس.
عورته : العورة: الخلل والعيب في الشيء وكل بيت أو موضع فيه خلل يخشى دخول العدو منه وفي التنزيل العزيز {يقولون إن بيوتنا عورة وما هي بعورة إن يريدون إلا فرارا} وكل ما يستره الإنسان استنكافًا أو حياءً.', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/3645', false),
(20506, 2, 201, 506, 'hadith', 'عن عائشة رضي الله عنها قالت: كان فراش رسول الله صلى الله عليه وسلم من أدم حشوه ليف.', 'The mattress of Messenger of Allah (ﷺ) was a piece of tanned skin stuffed with palm fibres..', 'عائشة رضي الله عنها', '''Aishah (May Allah be pleased with her)', 'صحيح', 'رياض الصالحين 506', 'Riyad as-Salihin 506', 'ریاض الصالحین 506', 'رواه البخاري', null, null, null, 'sunnah.com', null, false, null, false),
(20507, 2, 201, 507, 'hadith', 'عن ابن عمر رضي الله عنهما قال: كنا جلوساً مع رسول الله صلى الله عليه وسلم ، إذ جاء رجل من الأنصار، فسلم عليه، ثم أدبر الأنصاري، فقال رسول الله. صلى الله عليه وسلم : " يا أخا الأنصار؛ كيف أخي سعد بن عبادة؟" فقال: صالح، فقال رسول الله صلى الله عليه وسلم : "من يعوده منكم؟" فقام وقمنا معه، ونحن بضعة عشر، ما علينا نعال، ولا خفاف، ولا قلانس، ولا قمص، نمشي في تلك السباخ، حتى جئناه، فاستأخر قومه من حوله حتى دنا رسول الله صلى الله عليه وسلم وأصحابه الذين معه.', 'We were once sitting in the company of Messenger of Allah (ﷺ) when a man from the Ansar came and greeted. As he was leaving, Messenger of Allah (ﷺ) said to him, "O brother of the Ansar, how is my brother Sa''d bin ''Ubadah?" He replied, "He is well." Messenger of Allah (ﷺ) asked, "Which of you is desirous of visiting him?" Having said this he got up and we followed him. We were ten and odd in number and we had neither shoes nor light boots nor caps nor shirts. We walked on foot through the barren plain till we came to the residence of Sa''d (May Allah be pleased with him). His people made way and Messenger of Allah (ﷺ) along with those who accompanied him went up to him..', 'ابن عمر رضي الله عنهما', 'Ibn ''Umar (May Allah be pleased with them)', 'صحيح', 'رياض الصالحين 507', 'Riyad as-Salihin 507', 'ریاض الصالحین 507', 'رواه مسلم', null, null, null, 'sunnah.com', null, false, null, false),
(20508, 2, 201, 508, 'hadith', 'عن عمران بن الحصين رضي الله عنهما، عن النبي صلى الله عليه وسلم أنه قال: " خيركم قرني، ثم الذين يلونهم، ثم الذين يلونهم" قال عمران: فما أدري قال: النبي صلى الله عليه وسلم مرتين أو ثلاثاً " ثم يكون بعدهم قوم يشهدون ولا يستشهدون، ويخونون ولا يؤتمنون، وينذرون ولا يوفون، ويظهر فيهم السمن".', 'The Prophet (ﷺ) said, "The best of you, are my contemporaries, then those who follow them, then those who will come after them. (''Imran said, I do not know if he said this twice or thrice). Then, they will be followed by those who will testify but will not be called upon to testify; they will betray the trust, and will not be trusted. They will make vows but will not fulfill them, and obesity will prevail among them.".', 'عمران بن الحصين رضي الله عنهما', '''Imran bin Husain (May Allah be pleased with them)', 'صحيح', 'رياض الصالحين 508', 'Riyad as-Salihin 508', 'ریاض الصالحین 508', 'متفق عليه', null, null, null, 'sunnah.com', null, false, null, false),
(20509, 2, 201, 509, 'hadith', 'عن أبي أمامة رضي الله عنه قال: قال رسول الله صلى الله عليه وسلم : « يا ابن آدم: إنك أن تبذل الفضل خير لك، وأن تمسكه شر لك، ولا تلام على كفاف، وابدأ بمن تعول».', 'Messenger of Allah (ﷺ) said, "O son of Adam, if you spend the surplus, it will be better for you; and if you retain it, it will be evil for you. You will not be reprimanded for storing what is enough for your need. First of all spend upon those who are your dependents.".', 'أبي أمامة رضي الله عنه', 'Abu Umamah (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 509', 'Riyad as-Salihin 509', 'ریاض الصالحین 509', 'رواه الترمذي وقال: حديث حسن صحيح', null, null, null, 'sunnah.com', null, false, null, false),
(20510, 2, 201, 510, 'hadith', 'عن عبيد الله بن محصن الأنصاري الخطمي رضي الله عنه قال: قال رسول الله صلى الله عليه وسلم: « من أصبح منكم آمنا في سربه، معافى في جسده، عنده قوت يومه، فكأنما حيزت له الدنيا بحذافيرها».', 'Messenger of Allah (ﷺ) said, "Whosoever begins the day feeling family security and good health; and possessing provision for his day is as though he possesed the whole world.".', 'عبيد الله بن محصن الأنصاري الخطمي رضي الله عنه', '''Ubaidullah bin Mihsan Al-Ansari (May Allah be pleased with him)', 'حسن', 'رياض الصالحين 510', 'Riyad as-Salihin 510', 'ریاض الصالحین 510', 'رواه الترمذي وقال: حديث حسن', null, null, null, 'sunnah.com', null, false, null, false),
(20511, 2, 201, 511, 'hadith', '-وعن عبد الله بن عمرو بن العاص رضي الله عنهما ، أن رسول الله صلى الله عليه وسلم قال : « قد أفلح من أسلم ، وكان رزقه كفافا ، وقنعه الله بما آتاه ».', 'Messenger of Allah (ﷺ) said, "Successful is the one who enters the fold of Islam and is provided with sustenance which is sufficient for his day''s needs, and Allah makes him content with what He has bestowed upon him.".', null, '''Abdullah bin ''Amr bin Al-''as (May Allah be pleased with them)', 'صحيح', 'رياض الصالحين 511', 'Riyad as-Salihin 511', 'ریاض الصالحین 511', 'رواه مسلم', 'بيّن النبيُّ صلى الله عليه وسلم أنه قد فاز وظفر مَن انقاد إلى ربه فَهُدِي ووفق للإسلام، ورزق من الحلال قدْر حاجته من غير زيادة ولا نقص، وجعله الله قانعًا راضيًا بما أعطاه.', 'سعادة المرء في كمال دينه وكفاف عيشه وقناعته بما آتاه الله.
الترغيب في القناعة بما أوتيت من الدنيا مع الإسلام والسنة.', null, 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/5814', false),
(20512, 2, 201, 512, 'hadith', '-وعن أبي محمد فضاله بن عبيد الأنصاري رضي الله عنه ، أنه سمع رسول الله صلى الله عليه وسلم يقول : «طوبى لمن هدي إلى الإسلام ، وكان عيشه كفافا ،وقنع ».', 'I heard Messenger of Allah (ﷺ) say: "Happiness is due to him who is guided to Islam and possesses provision that suffices him for his day and remains content.".', null, 'Fadalah bin ''Ubaid Al-Ansari (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 512', 'Riyad as-Salihin 512', 'ریاض الصالحین 512', 'رواه الترمذي وقال :حديث حسن صحيح', 'بين النبي صلى الله عليه وسلم أنه قد فاز وظفر من هداه الله ووفقه للإسلام، وجعل رزقه بقدر كفايته، وجعله قانعا راضياً بما أعطاه.', 'عظم منزلة الرضا عن الله تعالى، ومنها القناعة بالرزق.', 'كفافًا: بقدر حاجته.

قنع: رضي.', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/66399', false),
(20513, 2, 201, 513, 'hadith', 'عن ابن عباس رضي الله عنهما قال : كان رسول الله صلى الله عليه وسلم يبيت الليالي المتتابعه طاويا، وأهله لايجدون عشاء ، وكان أكثر خبزهم خبز الشعير.', 'The Messenger of Allah (ﷺ) went to bed hungry for several successive nights, nor did his family have a thing for supper for many consecutive nights; and their bread was mostly of barley..', 'ابن عباس رضي الله عنهما', 'Ibn ''Abbas (May Allah be pleased with them)', 'صحيح', 'رياض الصالحين 513', 'Riyad as-Salihin 513', 'ریاض الصالحین 513', 'رواه الترمذي وقال : حديث حسن صحيح', null, null, null, 'sunnah.com', null, false, null, false),
(20514, 2, 201, 514, 'hadith', 'عن فضالة بن عبيد رضي الله عنه، أن رسول الله صلى الله عليه وسلم كان إذا صلى بالناس، يخر رجال من قامتهم في الصلاة من الخصاصة -وهم أصحاب الصفة- حتى يقول الأعراب: هؤلاء مجانين، فإذا صلى رسول الله صلى الله عليه وسلم انصرف إليهم، فقال: "لو تعلمون ما لكم عند الله تعالى، لأحببتم أن تزدادوا فاقة وحاجة" ((رواه الترمذي، وقال: حديث صحيح)). "الخصاصة": الفاقة والجوع الشديد.', 'When Messenger of Allah (ﷺ) led Salat, some people would fall down from their standing posture out of extreme hunger. They were of the people of As-Suffah. The nomad Arabs would say that they were insane. After concluding Salat, Messenger of Allah (ﷺ) would turn to them and say, "If you were to know what is in store for you with Allah, the Exalted, you would wish to augment your starvation and lack of provisions.".', 'فضالة بن عبيد رضي الله عنه', 'Fadalah bin ''Ubaid (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 514', 'Riyad as-Salihin 514', 'ریاض الصالحین 514', null, 'في الحديث أنه كان رجال يسقطون من قيامهم في الصلاة من الجوع والضعف، وهم من أهل الصُفَّة زهاد من الصحابة فقراء وغرباء وكانوا سبعين ويقلون حيناً ويكثرون حيناً يسكنون صفة المسجد لا مسكن لهم ولا مال ولا ولد، حتى يظن ناس من البادية أنهم مجانين بسبب سقوطهم فقال النبي صلى الله عليه وسلم لهم: لو تعلمون مالكم عند الله من الخير لأحببتم أن تزداد فاقتكم أي فقركم وحاجتكم.', 'ينبغي على المرء عند الفقر النظر إلى ما ادخر له من الأجر دون التلهف على ما فاته.
بيان لمعيشة أصحاب النبي -صلى الله عليه وسلم- وما كانوا عليه من الزهد وخشونة العيش مع الصبر وعدم الشكوى.
حرص رسول الله -صلى الله عليه وسلم- على تطييب قلوب أصحابه وأتباعه لما يسمعونه من الكلام الذي يسيء إليهم.', 'يَخِرُّ رجال : يسقط.
من قامتهم : من قيامهم.
الخَصَاصَة : الفاقة والجوع الشديد.
الصُّفة : مكان في مؤخر مسجد النبي -صلى الله عليه وسلم- ينزلها من لا مأوى له.
الأعراب : سكان البادية.', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/5825', false),
(20515, 2, 201, 515, 'hadith', 'عن أبي كريمة المقدام بن معديكرب رضي الله عنه قال: سمعت رسول الله صلى الله عليه وسلم يقول "ما ملأ آدمي وعاء شراً من بطن، بحسب ابن آدم أكلات يقمن صلبه، فإن كان لا محالة؛ فتلث لطعامه وثلث لشرابه، وثلث لنفسه". ((رواه الترمذي وقال: حديث حسن)). "أكلات" أي: لقم.', 'I heard Messenger of Allah (ﷺ) say: "No man fills a container worse than his stomach. A few morsels that keep his back upright are sufficient for him. If he has to, then he should keep one-third for food, one-third for drink and one-third for his breathing.".', 'أبي كريمة المقدام بن معديكرب رضي الله عنه', 'Miqdam bin Ma''dikarib (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 515', 'Riyad as-Salihin 515', 'ریاض الصالحین 515', null, 'يرشدنا النبي الكريم صلى الله عليه وسلم إلى أصل من أصول الطب، وهي الوقاية التي يقي بها الإنسان صحته، وهي التقليل من الأكل، بل يأكل بقدر ما يسد رمقه ويقويه على أعماله اللازمة، وإن شر وعاء مُلئ هو البطن لما ينتج عن الشبع من الأمراض الفتاكة التي لا تحصى عاجلًا أو آجلًا باطنًا أو ظاهرًا.

ثم إن الرسول صلى الله عليه وسلم قال: إذا كان الإنسان لابد له من الشبع، فليجعل الأكل بمقدار الثلث، والثلث الآخر للشرب، والثلث للنفس حتى لا يحصل عليه ضيق وضرر، وكسل عن تأدية ما أوجب الله عليه في أمر دينه أو دنياه.', 'عدم التوسع في الأكل والشرب، وهذا أصل جامع لأصول الطب كلها، لما في كثرة الشبع من الأمراض والأسقام.
الغاية من الأكل، هي حفظ الصحة والقوة وبهما سلامة الحياة.
لملء البطن من الطعام أضرار بدنية ودينية، قال عمر رضي الله عنه: «إياكم والبطنة، فإنها مفسدة للجسم ومكسلة عن الصلاة».
الأكل من حيث الحكم على أقسام: واجب، وهو ما به تُحفظ الحياة ويؤدي تركه إلى ضرر. جائز، وهو ما زاد على القدر الواجب ولا يُخشى ضرره. مكروه، وهو ما يُخشى ضرره. محرم، وهو ما يُعلم ضرره. ومستحب، وهو ما يُستعان به على عبادة الله وطاعته، وقد أجمل ذلك في الحديث في ثلاث مراتب: أولها: ملء البطن. ثانيها: أكلات أو لقيمات يقمن صلبه. ثالثها: قوله: «ثلث لطعامه وثلث لشرابه وثلث لنفسه» وهذا كله إذا كان جنس المأكول حلالًا.
الحديث قاعدة من قواعد الطب، وحيث إن علم الطب مداره على ثلاثة أصول: حفظ القوة والحمية والاستفراغ، فقد اشتمل الحديث على الأولين منها، كما في قوله تعالى : (وَكُلُوا وَاشْرَبُوا وَلَا تُسْرِفُوا إِنَّهُ لَا يُحِبُّ الْمُسْرِفِينَ) [الأعراف: 31].
كمال هذه الشريعة حيث اشتملت على مصالح الإنسان في دينه ودنياه.
من علوم الشريعة أصولُ الطب وأنواع منه، كما جاء في العسل والحبة السوداء.
اشتمال أحكام الشريعة على الحكمة، وأنها مبنية على درء المفاسد وجلب المصالح.', null, 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/4723', false),
(20516, 2, 201, 516, 'hadith', 'عن أبي أمامة إياس بن ثعلبة الأنصاري الحارثي رضي الله عنه قال: ذكر أصحاب رسول الله صلى الله عليه وسلم يوماً عنده الدنيا، فقال رسول الله صلى الله عليه وسلم : "ألا تسمعون؟ ألا تسمعون؟ إن البذاذة من الإيمان، إن البذاذة من الإيمان" يعني: التقحل. ((رواه أبو داود)). "البذاذة" بالباء الموحدة والذالين المعجمتين، وهي رثاثة الهيئة، وترك فاخر اللباس. وأما "التقحل" فبالقاف والحاء، قال أهل اللغة: المتقحل: هو الرجل اليابس الجلد من خشونة العيش، وترك الترفة.', 'The Companions of Messenger of Allah (ﷺ) mentioned the life of the world before him. He (ﷺ) said, "Do you not hear? Do you not hear? Simplicity (in life) is part of Faith, simplicity is part of Faith.".', 'أبي أمامة إياس بن ثعلبة الأنصاري الحارثي رضي الله عنه', 'Abu Umamah bin Tha''labah (May Allah be pleased with him)', 'حسن لغيره', 'رياض الصالحين 516', 'Riyad as-Salihin 516', 'ریاض الصالحین 516', null, 'تكلم نفر من أصحاب النبي صلى الله عليه وسلم في الدنيا فقال لهم النبي صلى الله عليه وسلم : (ألا تسمعون) أي: اسمعوا وكرر للتأكيد، إن التواضع في اللباس والزينة من أخلاق أهل الإيمان، والإيمان هو الباعث عليه.', 'استحباب تحويل حديث المجلس إذا كان الكلام مثقلًا بمتاع الدنيا وشهواتها وزخرفها ويصد القلوب عن ذكر الله.
الحث على التواضع والتقليل من الدنيا لأن ذلك يبعث الهمم على العبادة والطاعة.
لا يفهم من الحديث ترك النظافة،فإنَّ الإسلام حث عليها وهي من دواعي الإيمان فالطهور شطر الإيمان.', 'البذاذة : هي رثاثة الهيئة وترك فاخر اللباس.', 'sunnah.com', null, false, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/5793', false),
(20517, 2, 201, 517, 'hadith', 'عن أبي عبد الله جابر بن عبد الله رضي الله عنهما قال: بعثنا رسول الله صلى الله عليه وسلم وأمر علينا أبا عبيدة رضي الله عنه، نتلقى عيرا لقريش، وزودنا جراباً من تمر لم يجد لنا غيره، فكان أبوعبيدة يعطينا تمرة تمرة، فقيل كيف كنتم تصنعون بها؟ قال: نمصها كما يمص الصبي، ثم نشرب عليها من الماء، فتكفينا يومنا إلى الليل، وكنا نضرب بعصينا الخبط، ثم نبله بالماء فنأكله. قال: وانطلقنا على ساحل البحر، فرفع لنا على ساحل البحر كهيئة الكثيب الضخم، فأتيناه فإذا هي دابة تدعى العنبر، فقال أبو عبيدة: ميتة، ثم قال: لا، بل نحن رسل رسول الله صلى الله عليه وسلم وفي سبيل الله وقد اضطررتم فكلوا، فأقمنا عليه شهرا، ونحن ثلاثمائة، حتى سمنا، ولقد رأيتنا نغترف من وقب عينه بالقلال الدهن ونقطع منه الفدر كالثور أو كقدر الثور، ولقد أخذ منا أبوعبيدة ثلاثة عشر رجلا فأقعدهم في وقب عينه وأخذ ضلعا من أضلاعه فأقامها ثم رحل أعظم بعير معنا فمر من تحتها وتزودنا من لحمه وشائق، فلما قدمنا المدينة أتينا رسول الله صلى الله عليه وسلم فذكرنا ذلك له، فقال: "هو رزق أخرجه الله لكم، فهل معكم من لحمه شئ فتطعمونا؟" فأرسلنا إلى رسول الله صلى الله عليه وسلم منه فأكله. ((رواه مسلم)). "الجراب": وعاء من جلد معروف، وهو بكسر الجيم وفتحها، والكسر أفصح. قوله: نمصها" بفتح الميم. "والخبط" ورق شجر معروف تأكله الإبل. "والكثيب": التل من الرمل. "والوقب" بفتح الواو وإسكان القاف وبعدها باء موحدة، وهو نقرة العين. "بتخفيف الحاء: أي جعل عليه الرحل. "الشائق" بالشين المعجمة والقاف: اللحم الذي اقتطع ليقدد منه، والله اعلم.', 'Messenger of Allah (ﷺ) sent us in an expedition under the command of Abu ''Ubaidah (May Allah be pleased with him) to intercept a caravan of the Quraish. He provided us with a bag of dates, apart from which he found nothing for us. Abu ''Ubaidah (May Allah be pleased with him) gave each of us one date (every day). He (the narrator) was asked: "What did you do with that?" He said: We sucked that just like a baby and then drank water over that, and it was sufficient for us for the day until night. We beat off leaves with the help of our sticks, then drenched them with water and ate them. We then went to the seaside, when there appeared before us something like a big mound. We came near it and we found that it was a beast called Al-Anbar. Abu ''Ubaidah (May Allah be pleased with him) said: "It is dead (so it useless for us)." He then said: "No (but it does not matter), we have been sent by Messenger of Allah (ﷺ) in the way of Allah and you are hard-pressed (on account of the scarcity of food), so you can eat that." We, three hundred in number, stayed there for a month until we fattened up (having plenty to eat of that fish). He (Jabir) said: I saw how we extracted pitcher after pitcher full of fat from the cavity of its eye, and sliced from it compact piece of meat equal to a bull or almost like a bull. Abu ''Ubaidah (May Allah be pleased with him) called thirteen men from us and he made them sit in the cavity of its eye, and he held one of its ribs and raised it erect and then saddled the biggest of the camels we had with us and it passed through it (the arched rib), and we carried large pieces of meat for use in our journey. When we came back to Al-Madinah we went to Messenger of Allah (ﷺ) and told him about that, whereupon he said, "That was a sustenance Allah had brought forth for you. Do you have any piece of meat left with you, for us to eat." Jabir (May Allah be pleased with him) said: We sent to Messenger of Allah (ﷺ) some of that (meat) and he ate it..', 'أبي عبد الله جابر بن عبد الله رضي الله عنهما', 'Jabir bin ''Abdullah (May Allah be pleased with them)', 'صحيح', 'رياض الصالحين 517', 'Riyad as-Salihin 517', 'ریاض الصالحین 517', null, 'بعث النبي صلى الله عليه وسلم سرية وأمَّر عليهم أبا عبيدة أي: جعله عليهم أميراً لأخذ قافلة تحمل البر والطعام لقريش وأعطاهم وعاء من جلد فيه تمر فكان أميرهم يعطي لكل واحد منهم تمرة لقلة الزاد الذي معهم فكانوا يمصونها ويشربون عليها الماء وكانوا يضربون بعصيهم ورق الشجر الذي تأكله الإبل ثم يبلونه بالماء لإذهاب خشونته فلما وصلوا شاطئ البحر رأوا مثل التل من الرمل فأتوه فإذا هي سمكة كبيرة تسمى العنبر فنهاهم أميرهم أبوعبيدة أن يأكلوا منها لأنها ميتة والميتة محرمة بنص الكتاب ثم تغير اجتهاده وأجاز لهم أن يأكلوا منها وذلك أن الميتة يجوز الأكل منها حال الضرورة ولا سيما أنهم في سفر طاعة لله سبحانه، وخفي عليهم أن ميتة البحر حلال، ثم احتجوا بالاضطرار فأكلوا منه وحملوا معهم فلما قدموا المدينة أخبروا رسول الله صلى الله عليه وسلم فأقرهم على فعلهم وأكل منه.', 'بيان لما كان عليه الصحابة رضي الله عنهم من الزهد في الدنيا والتقلل منها والصبر على الجوع وخشونة العيش.
تحمل الصحابة المشاق من أجل نشر الإسلام والجهاد في سبيل الله لرفع رايته.
جواز الاجتهاد ثم جواز تغييره فقد نهاهم أبو عبيدة عن أكل السمكة ثم غير اجتهاده.
عناية الله سبحانه ورعايته لصحابة رسول الله صلى الله عليه وسلم وإكرامه لهم حيث ساق لهم رزقاً حسناً لما علم حاجتهم وإخلاصهم.
ميتة البحر حلال حيث أكل منها رسول الله صلى الله عليه وسلم.
ما كان عليه النبي -صلى الله عليه وسلم- من تطييب نفوس أصحابه، ومن ذلك طلبه اللحم وأكله منه.
مشروعية المواساة عند وقوع المجاعة.
أن الاجتماع على الطعام يستدعي البركة فيه.', 'جراباً من تمر : الجراب هو وعاء من جلد معروف.
الخبط : ورق شجر معروف تأكله الإبل.
الكثيب : التل من الرمل.
وقب عينه : هو نقرة العين.
القلال : الجرار.
الفدر : القطع.
رحل البعير : أي جعل عليه الرحل.
الوشائق : اللحم الذي اقتطع ليقدد منه.
العنبر : سمكة بحرية كبيرة.', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/5856', false),
(20518, 2, 201, 518, 'hadith', 'عن أسماء بنت يزيد رضي الله عنها قالت: كان كم قميص رسول الله صلى الله عليه وسلم إلى الرصغ، ((رواه أبو داود، والترمذي، وقال: حديث حسن)). "الرصغ: بالصاد والرسغ بالسين أيضاً: هو المفصل بين الكف والساعد.', 'The sleeves of the shirt of Messenger of Allah (ﷺ) reached his wrists..', 'أسماء بنت يزيد رضي الله عنها', 'Asma'' bint Yazid (May Allah be pleased with them)', null, 'رياض الصالحين 518', 'Riyad as-Salihin 518', 'ریاض الصالحین 518', null, null, null, null, 'sunnah.com', null, false, null, false),
(20519, 2, 201, 519, 'hadith', 'عن جابر رضي الله عنه قال: إنا كنا يوم الخندق نحفر، فعرضت كدية شديدة، فجاؤوا إلى النبي صلى الله عليه وسلم فقالوا: هذه كدية عرضت في الخندق. فقال: "أنا نازل" ثم قام، وبطنه معصوب بحجر، ولبثنا ثلاثة أيام لا نذوق ذوقاً فأخذ النبي صلى الله عليه وسلم المعول، فضرب، فعاد كثيباً أهيل، أو أهيم، فقلت: يا رسول الله ائذن لي إلى البيت، فقلت لامرأتي: رأيت بالنبي صلى الله عليه وسلم شيئاً ما في ذلك صبر فعندك شيء؟ فقالت: عندي شعير وعناق، فذبحت العناق وطحنت الشعير حتى جعلنا اللحم في البرمة، ثم جئت النبي صلى الله عليه وسلم والعجين قد انكسر، والبرمة بين الأثاقي قد كادت تنضج، فقلت: طعيم لي، فقم أنت يا رسول الله ورجل أو رجلان، قال: "كم هو؟" فذكرت له فقال: "كثير طيب، قل لها لا تنزع البرمة، ولا الخبز من التنور حتى آتي" فقال: "قوموا" فقام المهاجرون والأنصار، فدخلت عليها فقلت: ويحك جاء النبي صلى الله عليه وسلم والمهاجرون والأنصار ومن معهم! قالت: هل سألك؟ قلت: نعم، قال: "ادخلوا ولا تضاغطوا فجعل يكسر الخبز، ويجعل عليه اللحم، ويخمر البرمة والتنور إذا أخذ منه، ويقرب إلى أصحابه ثم ينزع، فلم يزل يكسر ويغرف حتى شبعوا، وبقي منه، فقال: كلي هذا وأهدي، فإن الناس أصابتهم مجاعة" ((متفق عليه)). وفي رواية: قال جابر: لما حفر الخندق رأيت النبي صلى الله عليه وسلم خمصاً، فانكفأت إلى امراتى فقلت: هل عندك شيء؛ فإني رأيت برسول الله صلى الله عليه وسلم خمصاً شديداً فأخرجت إلي جرابا فيه صاع من شعير، ولنا بهيمة داجن فذبحتها، وطحنت الشعير، ففرغت إلى فراغى، وقطعتها في برمتها، ثم وليت إلى رسول الله صلى الله عليه وسلم فقالت: لا تفضحني برسول الله صلى الله عليه وسلم ومن معه، فجئته وساررته فقلت: يا رسول الله، ذبحنا بهيمة لنا، وطحنت صاعا من شعير، فتعال أنت ونفر معك، فصاح رسول الله صلى الله عليه وسلم فقال: يا أهل الخندق إن جابراً قد صنع سؤراً فحيهلا بكم" فقال النبي صلى الله عليه وسلم : "لا تنزلن برمتكم ولا تخبزن عجينكم حتى أجيء" فجئت، وجاء النبي صلى الله عليه وسلم يقدم الناس، حتى جئت امرأتي فقالت: بك وبك! فقلت: قد فعلت الذي قلت. فأخرجت عجيناً، فبسق فيه وبارك، ثم عمد إلى برمتنا فبصق وبارك، ثم قال: "ادعي خابزة فلتخبز معك، واقدحي من برمتكم ولا تنزلوها"وهم ألف، فأقسم بالله لأكلوا حتى تركوه وانحرفوا، وإن برمتنا لتغط كما هي، وإن عجيننا ليخبز كما هو. قوله: "عرضت كدية" : بضم الكاف وإسكان الدال وبالياء المثناة تحت؛ وهي قطعة غليظة صلبة من الأرض لا يعمل فيها الفأس. "والكثيب" أصله تل الرمل، والمراد هنا: صارت تراباً ناعماً، وهو معنى "أهيل". "الأثافي" : الأحجار التى يكون عليها القدر. و"تضاغطوا" : تزاحموا. و"المجاعة" :الجوع، وهو بفتح الميم. و"الخمص" بفتح الخاء المعجمة والميم: الجوع. و"انكفأت" : انقلبت ورجعت. "البهيمة" بضم الباء: تصغير بهمة، وهي العناق -بفتح العين-. و"الداجن": هي التي ألفت البيت. و"السؤر" :الطعام الذي يدعى الناس إليه، وهو بالفارسية. و"حيهلا" أي: تعالوا. وقولها: "بك وبك" أي: خاصمته وسبته، لأنها اعتقدت أن الذي عندها لا يكفيهم، فاستحيت وخفي عليها ما أكرم الله سبحانه وتعالى به نبيه صلى الله عليه وسلم من هذه المعجزة الظاهرة والآية اباهرة. "بسق" أي :بصق؛ ويقال أيضاً: بزق -ثلاث لغات- و"عمد" بفتح الميم: أي قصد. و"اقدحي" أي اغرفي؛ والمقدحة: المغرفة. و"تغط" أي: لغليانها صوت، والله اعلم.', 'On the day of the battle of Al-Khandaq (the Trench), we were digging the trench when a very hard boulder came in our way. The Companions went to Messenger of Allah (ﷺ) and told him about it. He said, "I will go down the trench to see it." He stood up and it was noticed that he had tied a stone over his stomach due to intense hunger. We had not tasted anything for three days. He took up a spade and struck the hard rock with it and it turned into sand. I sought his permission to go home, (after reaching home I) said to my wife, "I have seen the Prophet (ﷺ) in a state that I am unable to endure. Have you got anything in the house?" She said, "I have a small quantity of barley and a lamb." I slaughtered the lamb, ground the barley and put the meat in the cooking pot. Then I went to the Prophet (ﷺ). In the meantime the flour had been kneaded and the meat in the pot was nearly cooked. I said to him, "O Messenger of Allah, I have some food, will you come along with one or two Companions?" He asked, "How many men should go there?" I told him the number. He said, "It will be better if they are more in number. Tell your wife not to remove the pot from the hearth nor the bread from the oven till I arrive." Then he said to the Muhajirun and the Ansar: "Let us go (to eat)." They all rose (and went with him). I went to my wife and said, "Bless you, the Prophet (ﷺ), the Muhajirun, the Ansar and the whole company are coming." She said, "Did he (ﷺ) ask you?" I replied in the affirmative. (When they arrived) Messenger of Allah (ﷺ) said to his Companions, "Enter, but do not crowd in." Then he started breaking up the bread and putting meat on it. He would take from the pot and the oven then would cover them up, approach his Companions and hand it over to them. He would then go back and uncover the pot and the oven. He continued to break up the bread and put meat on it till all had eaten to their fill and still some of the food remained. Then he said to my wife, "Eat from it, and send it as a present, for the people have been afflicted with severe hunger.".Another narration is: Jabir said: When the trench was being dug, I noticed the signs of hunger on the face of the Prophet (ﷺ). I returned to my wife and said to her, "Have you got anything in the house? I have seen the signs of severe hunger on the face of Messenger of Allah (ﷺ)." She brought out a bag which contained a Sa'' (a measure that equals approximately 3kg.) of barley. We had a lamb which was reared in the home. I slaughtered the lamb and she ground the flour for baking bread. I then cut the meat and put it in the cooking pot. When I was returning to Messenger of Allah (ﷺ), my wife said to me, "Do not embarass me before Messenger of Allah (ﷺ) and his Companions." (She said this because she thought that the food would not be enough for everyone, for how can very little food cater for a thousand people?) When I came to him, I said to him in a low tone, "O Messenger of Allah (ﷺ), we have slaughtered a small lamb and have ground a Sa'' of barley. Please accompany me with a few of your Companions." Thereupon he (ﷺ) announced in a loud voice, "O people of the Trench, Jabir has arranged a feast for you, so all of you are welcome." And addressing me he said, "Do not take the pot off the fire, nor bake the kneaded flour till I arrive." So I came home and he came ahead of the people. My wife said, "It will be a matter of disgrace for you (because there is not enough food)." I said, "I did only what you told me." She brought out the kneaded flour and Messenger of Allah (ﷺ) spat into it, and invoked the blessing of Allah on it, and then he spat into the cooking pot and invoked the blessing of Allah on it. Then he said, "Call another woman to help bake bread and let her take out from the cooking pot, but do not take it off the fire." There were about a thousand guests. All of them ate till they left the food and went off. Our pot still bubbled as before and the dough was being baked as before.', 'جابر رضي الله عنه', 'Jabir (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 519', 'Riyad as-Salihin 519', 'ریاض الصالحین 519', null, 'حكى جابر رضي الله عنه أنهم كانوا يوم الخندق يحفرون حول المدينة خندقا يحول بينهم وبين الأعداء، فظهرت قطعة شديدة صلبة في عرض الأرض، لا يعمل فيها الفأس، فشكوا لرسول الله صلى الله عليه وسلم صعوبتها، فنزل رسول الله صلى الله عليه وسلم الخندق وبطنه مربوط بحجر من شدة الجوع، فأخذ المعول وهو قطعة من حديد ينقر بها الجبال فضربه بها فانقلب الحجر وصار رملًا ناعمًا. 
قال جابر: فذهبت إلى بيتي فقلت لزوجي هل عندنا شيء من الطعام؟ وأخبرها بحال رسول الله صلى الله عليه وسلم التي كان عليها من أثر الجوع، فأخرجت زوجه وعاء من جلد فيه شعير، وكانت لهم عناق -وهي ولد المعز أول ما تضعه أمه- قد ألفت البيت، فذبحتها وطحنت الشعير وجعلت اللحم في القدر الذي من الحجر، وذهب جابر إلى النبي صلى الله عليه وسلم فأخبره سراً بأنه قد صنع له طعاماً يسيرًا لا يكفي كل من معه، وطلب منه أن يأتيه هو وبعض أصحابه، فنادى رسول الله صلى الله عليه وسلم : يا أهل الخندق إن جابراً صنع طعاماً فأسرعوا إليه. ثم ذهب رسول الله إلى بيت جابر وطلب العجين فبصق فيه، وكذلك بصق في القدر، ودعا بالبركة فيهما، وهذا من خصائصه وبركته صلى الله عليه وسلم ، وطلب منهم أن يدعو من يساعد زوج جابر في صنع الطعام، وجاء القوم فأكلوا ثم انصرفوا والطعام باق على ما هو عليه، القدر يغلي والعجين يخبز كأنه لم ينقص منه شيء.', 'الحث على التعاون في العمل الذي يعود بالنفع على المسلمين.
حب الصحابة -رضي الله عنهم- لرسول الله -صلى الله عليه وسلم-.
حرص رسول الله -صلى الله عليه وسلم- أن يعم الخير جميع أصحابه، وهذا ينمي روح الجماعة والوحدة.
لا ينبغي للمقاتل أن يغادر مكانه وموقعه إلا بإذن من الأمير.
معجزة تكثير الطعام لرسول الله -صلى الله عليه وسلم-.
استحباب الهدية وبخاصة أيام الحاجة والمجاعة.', 'كدية : قطعة غليظة صلبة من الأرض لا يعمل فيها الفأس.
معصوب بحجر : يربط على بطنه بحجر من شدة الجوع.
المعول : المسحاة.
كثيبا أهيل أو أهيم : أصله تل الرمل الناعم.
عناق : الأنثى من المعز.
البرمة : القدر مطلقاً وفي الأصل القدر المتخذ من الحجر.
الأثافي : الأحجار التي يكون عليها القدر.
التنور : هو الذي يخبز فيه.
ولا تضاغطوا : لا تزاحموا.
يخمر : يغطي.
خمصا : الخمص الجوع.
فانكفأت : انقلبت ورجعت.
جرابا : هو وعاء من جلد.
بهيمة داجن : هي ولد المعز التي ألفت البيت.
صاعا من شعير : إناء يكال به وهو أربعة أمداد من مد النبي -صلى الله عليه وسلم-.
سؤرا : الطعام الذي يدعى الناس إليه.
فبسق : بصق ويقال: بزق.
عمد : قصد.
انحرفوا : انصرفوا.
اقدحي : اغرفي.
تغط : يُسمع لغليانها صوت.
حيهلا : تعالوا.
بك وبك : أي: خاصمته وسبته لأن الطعام لا يكفيهم.', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/5818', false),
(20520, 2, 201, 520, 'hadith', 'عن أنس رضي الله عنه قال: قال أبو طلحة لأم سليم: قد سمعت صوت رسول الله صلى الله عليه وسلم ضعيفاً أعرف فيه الجوع، فهل عندك من شيء؟ فقالت: نعم، فأخرجت أقراصاً من شعير، ثم أخذت خماراً لها، فلفت الخبز ببعضه، ثم دسته تحت ثوبي وردتني ببعضه، ثم أرسلتني إلى رسول الله صلى الله عليه وسلم فذهبت به، فوجدت رسول الله صلى الله عليه وسلم جالساً في المسجد، ومعه الناس، فقمت عليهم، فقال لي رسول الله صلى الله عليه وسلم "أرسلك أبو طلحة؟" فقلت: نعم، فقال: "ألطعام" فقلت: نعم، فقال رسول الله صلى الله عليه وسلم: "قوموا" فانطلقوا بين أيديهم حتى جئت أبا طلحة فأخبرته، فقال أبو طلحة: يا أم سليم: قد جاء رسول الله بالناس وليس عندنا ما نطعمهم؟ فقالت: الله ورسوله أعلم. فانطلق أبو طلحة حتى لقي رسول الله صلى الله عليه وسلم فأقبل رسول الله صلى الله عليه وسلم معه حتى دخلا، فقال رسول الله صلى الله عليه وسلم: "هلمى ما عندك يا أم سليم" فأتت بذلك الخبز، فأمر به رسول الله صلى الله عليه وسلم ففت وعصرت عليه أم سليم عكة فآدمته، ثم قال فيه رسول الله صلى الله عليه وسلم ما شاء الله أن يقول، ثم قال: "ائذن لعشرة" فأذن لهم، فأكلوا حتى شبعوا ثم خرجوا، ثم قال: "ائذن لعشرة" فأذن لهم، فأكلوا حتى شبعوا، ثم خرجوا، ثم قال: "ائذن لعشرة" فأذن لهم حتى أكل القوم كلهم وشبعوا، والقوم سبعون رجلاً أو ثمانون. ((متفق عليه)). وفي رواية: فما زال يدخل عشرة ويخرج عشرة، حتى لم يبق منهم أحد إلا دخل، فأكل حتى شبع، ثم هيأها فإذا هي مثلها حين اكلوا منها. وفي رواية: فأكلوا عشرة عشرة، حتى فعل ذلك بثمانين رجلا، ثم أكل النبي صلى الله عليه وسلم بعد ذلك وأهل البيت، وتركوا سؤراً. وفي رواية: ثم أفضلوا ما بلغوا جيرانهم. وفي رواية عن أنس قال: جئت رسول الله صلى الله عليه وسلم يوماً، فوجدته جالساً مع أصحابه، وقد عصب بطنه بعصابة، فقلت لبعض أصحابه: لم عصب رسول الله صلى الله عليه وسلم بطنه؟ فقالوا: من الجوع، فذهبت إلى أبي طلحة، وهو زوج أم سليم بنت ملحان، فقلت: يا أبتاه، قد رأيت رسول الله صلى الله عليه وسلم عصب بطنه بعصابة، فسألت بعض أصحابه، فقالوا: من الجوع. فدخل أبو طلحة على أمي فقال: هل من شيء ؟ قالت: نعم عندي كسر من خبز وتمرات، فإن جاءنا رسول الله صلى الله عليه وسلم وحده أشبعناه وإن جاء آخر معه قل عنهم، وذكر تمام الحديث.', 'Abu Talhah (May Allah be pleased with him) said to (to his wife) Umm Sulaim(May Allah be pleased with her), "I noticed some weakness in the voice of Messenger of Allah (ﷺ) and I feel it was due to hunger. Have you got any food?" She said, "Yes." So she brought out barley loaves, took off her head covering, in a part of which she wrapped these loaves and then put them beneath my mantle and covered me with a part of it. She then sent me to Messenger of Allah (ﷺ). I set forth and found Messenger of Allah (ﷺ) sitting in the mosque in the company of some people. I stood near them whereupon Messenger of Allah (ﷺ) asked, "Has Abu Talhah sent you?" I said, "Yes." Thereupon he said to those who were with him to get up (and follow him). He went forth and so did I, ahead of them until I came to Abu Talhah and informed him. Abu Talhah said, "O Umm Sulaim, here comes Messenger of Allah (ﷺ) along with the people and we do not have enough (food) to feed them." She said, "Allah and His Messenger know better." Abu Talhah went out (to receive him) until he met Messenger of Allah (ﷺ), and he came forward along with him until they both (Messenger of Allah (ﷺ) and Abu Talhah (May Allah be pleased with him) came in. Then Messenger of Allah (ﷺ) said, "O Umm Sulaim, bring forth what you have with you." So she brought the bread. Messenger of Allah (ﷺ) commanded that the bread be broken into small pieces and after Umm Sulaim (May Allah be pleased with her) had squeezed clarified butter out of a butter container and made it just like soup. Messenger of Allah (ﷺ) recited over it what Allah wished him to recite. He then said, "Allow ten guests to come in." They ate until they had their fill. They then went out. He (Messenger of Allah (ﷺ)) again said, "Allow ten (more to come in)", and he (the host) ushered them in. They ate to their fill. Then they went out. He (ﷺ) again said, "Allow ten (more)," until all the people ate to their fill. They were seventy or eighty persons..Another narration is: Anas said: When all had eaten, the remaining food was collected. It was as much as there was in the beginning.Yet another narration is: Anas said: The groups of ten people ate by turn. After eighty persons had eaten, Messenger of Allah (ﷺ) and the family of that house ate, and there was still a quantity left over.Another narration is: Anas (May Allah be pleased with him) said: I visited Messenger of Allah (ﷺ) one day, and found him sitting in the company of his Companions, with a belt tied over his waist. I asked, "Why has Messenger of Allah (ﷺ) tied the belt on his waist?" I was told, "Due to hunger." I went to Abu Talhah (May Allah be pleased with him) the husband of Umm Sulaim (May Allah be pleased with her) and said, "O father, I have seen Messenger of Allah (ﷺ) with a belt tied over his waist. I asked one of his Companions about the reason of it and he said that it was on account of severe hunger." Abu Talhah (May Allah be pleased with him) went to my mother and asked, "Have you got anything?" She said, "Yes. I have a piece of bread and some dry dates. Were Messenger of Allah (ﷺ) to come alone, we could feed him his fill, but if he comes along with others, there would not be enough food." Anas then narrated the Hadith in full.', 'أنس رضي الله عنه', 'Anas (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 520', 'Riyad as-Salihin 520', 'ریاض الصالحین 520', null, 'معنى هذا الحديث: أنه عليه الصلاة والسلام قد اشتد به الجوع، فَعَلِم أبو طلحة رضي الله عنه بحال النبي صلى الله عليه وسلم من خلال ضعف صوته فأخبر زوجته أم سليم رضي الله عنها، بحال النبي صلى الله عليه وسلم وسألها: هل عندكم شيء؟ فقالت : نعم، أي عندنا ما نَسُدُّ به جوع النبي صلى الله عليه وسلم فأخرجت أقْرَاصًا من شعِير، ثم أخذت خِمَارا لها فَلَفَت الخبز ببعضه، وجعلته تحت ثوب أنس رضي الله عنه وأخذت باقي الخِمار وجعلته رداء عليه لتستره. فلما قدم أنس على النبي صلى الله عليه وسلم وجده بين أصحابه ، فقام عليهم، فقال لي رسول الله صلى الله عليه وسلم: "أرسلك أبو طلحة؟" فقلت: نعم، فقال: "ألِطعام؟" أي: هل أرسلك لأجل طعام تدعونا له؟ فقلت: نعم. لم يستطع أنس رضي الله عنه أن يَدفع الطعام إلى النبي صلى الله عليه وسلم؛ لكثرة من عنده من الصحابة ولعلمه أن النبي صلى الله عليه وسلم من عادته ألا يُؤثِر نفسه على أصحابه، فما كان منه إلا أن قال له: نعم. فأظهر له الدعوة ليقوم معه وحده إلى بيت أبي طلحة، فيحصل المقصود من إطعامه. فعند ذلك: قال النبي صلى الله عليه وسلم لأصحابه: "قوموا". فانْطَلَقُوا قال أنس: فانْطَلَقْتُ بين أيديهم، وفي رواية: وأنا حَزِين لكثرة من جاء معه. قال: حتى جئتُ أبا طلحة وأخبرته، فقال أبو طلحة: يا أم سليم، قد جاء رسول الله صلى الله عليه وسلم بالناس وليس عندنا ما نُطعِمُهُم؟ فقالت: الله ورسوله أعلم. فأم سليم رضي الله عنها أرجَعت الأمر إلى الله وإلى رسوله، كأنها عرفت أنه عليه الصلاة والسلام فعل ذلك عمداً لتظهر له الكرامة في تكثير الطعام وهذا من فطنتها ورجحان عقلها، فانطلق أبو طلحة حتى لقي رسول الله صلى الله عليه وسلم فأقبل رسول الله صلى الله عليه وسلم معه حتى دخلا فقال رسول الله صلى الله عليه وسلم: "هَلُمِّي"
وفي رواية: فاستقبله أبو طلحة فقال يا رسول الله ما عندنا إلا قُرْصٌ عملته أم سليم .وفي رواية: فقال أبو طلحة: إنما هو قُرْصٌ فقال: "إن الله سَيُبَارك فيه" وفي رواية فقال أبو طلحة: يا رسول الله إنما أرسلت أنسا يدعوك وحدك ولم يكن عندنا ما يُشْبِعُ من أرى فقال: "ادخل فإن الله سَيُبَارك فيما عندك" 
فلما دخل رسول الله صلى الله عليه وسلم بيت أبي طلحة قال: "هَلُمِّي ما عندك يا أم سليم" فأتت بذلك الخبز، فأمر به رسول الله صلى الله عليه وسلم فَفُتَّ، وَعَصَرَتْ عليه أم سليم ما خرج من العُكَّة من سَمْنٍ إدَامَا للمَفْتُوت، ثم قال فيه رسول الله صلى الله عليه وسلم ما شاء الله أن يقول يعني : دعا بأن الله تعالى يبارك في هذا الطعام القليل، وفي رواية: " فجئت بها ففتح رِبَاطَها ثم قال: "بسم الله اللهم أعْظِمْ فيها البركة" ثم قال: "ائْذَنْ لعشرة" فأذن لهم فأكلوا حتى شَبِعُوا ثم خرجوا، ثم قال: "ائْذَن لعشرة" فأذن لهم حتى أكل القوم كلُّهم وشَبِعُوا والقوم سبعون رجلا أو ثمانون. متفق عليه.
وفي رواية: فما زال يَدخُل عشرة، ويخرج عشرة حتى لم يبق منهم أحد إلا دخل، فأكل حتى شَبِع، ثم هَيَّأهَا فإذا هي مِثْلَهَا حين أكلوا منها. وفي رواية: فأكلوا عشرة عشرة، حتى فعل ذلك بثمانين رجلا، ثم أكل النبي صلى الله عليه وسلم بعد ذلك وأهل البيت، وتركوا سُؤْرَاً. وفي رواية: ثم أفْضَلُوا ما بَلَغُوا جيرانهم.', 'تأييد الله لنبيه بالآيات والمعجزات.
جواز العمل بالفِرَاسَة والقَرائن حيث استدل أبو طلحة من ضعف صوته صلى الله عليه وسلم على شِدِّة الجوع.
جواز الدعوة إلى الطعام في المسجد، وكذلك الإجابة منه.
جلوس العالم لأصحابه في المسجد لإفادتهم.
جواز الدعوة إلى الطعام وإن لم يكن وليمة.
جواز استدعاء العدد الكثير إلى الطعام القليل.
إذا علم المدعو أن الداعي لا يكره أن يحضر معه غيره فلا بأس بإحضاره معه.
اعتناء الصحابة بأحوال رسول الله صلى الله عليه وسلم.
جواز الأكل حتى الشَبع، ففي الحديث: (فأكلوا حتى شَبِعُوا).
جواز إدخال الضيوف عشرة عشرة إذا احتيج إلى ذلك لضيق الطعام أو مكان الجلوس عليهم.
صبر النبي صلى الله عليه وسلم؛ فإنه كان يجوع حتى يَربِط على بَطْنِه ولا يسأل أحدا.
ما كان عليه النبي صلى الله عليه وسلم وأصحابه من الفَقْر والشدِّة.
جواز الأكل من سُؤْر الأخرين.', 'أقراصًا : جمع قرص، قطع من العجين أو الخبز.
خِمَار : ثوب تغطي به المرأة رأسها.
دَسَّتْهُ : أخْفَته.
ورَدَّتني ببعضه : لفَّت الخبز ببعض الخِمار ولفَّت أنسًا بباقيه.
هَلُمِّي : أحْضِري ما عندك.
العُكَّة : إناء من جلد مستدير يُجعل فيه السمن غالبا والعسل.
فآدمَتْه : جعلت فيه إدَاما.
هَيَّأهَا : جمعها بعد الأكل.
مِثْلُها : على حالتها قبل أن يأكلوا منها.
تركوا سُؤرَاً : بقية
أَفْضَلُوا : أبقوا، وفي رواية لمسلم: فبقيت فضلة فأهديناها لجيراننا.
ما بَلَغُوا جيرانهم : أوصَلَوه هدية إليهم.
عَصَبَ بَطْنَه : شدَّ على بطنه.
العُصَابة : الخِرْقَة التي توضع على البَطن من الجوع.
كِسَر : قِطَع، جمع كسرة.
البركة : النماء والزيادة والسعادة.', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/6613', false)
