insert into hadith (id, collection_id, chapter_id, number_in_book, kind, arabic, translation_en, narrator_ar, narrator_en, grade_ar, reference_ar, reference_en, reference_ur, full_ref_ar, explanation_ar, benefits_ar, word_meanings_ar, source, source_ref, daily_ok, review_note, deleted) values
(20561, 2, 201, 561, 'hadith', 'وعنه عن النبي صلى الله عليه وسلم قال: "بينما رجل يمشى بفلاة من الأرض، فسمع صوتاً فى سحابة: إسق حديقة فلان، فتنحى ذلك السحاب فأفرغ ماءه فى حرة، فإذا شرجة من تلك الشراح قد استوعبت ذلك الماء كله، فتتبع الماء، فإذا رجل قائم فى حديقته يحول الماء بمسحاته، فقال له: يا عبد الله ما اسمك ، قال: فلان للاسم الذى سمع فى السحابة، فقال له: يا عبد الله لم تسألني عن اسمي ؟ فقال: إنى سمعت صوتاً فى السحاب الذى هذا ماؤه يقول: اسق حديقة فلان لإسمك، فما تصنع فيها؟ فقال: أما إذا قلت هذا فإنى أنظر إلى ما يخرج منها، فأتصدق بثلثه، وآكل أنا وعيالى ثلثاً، وأرد فيها ثلثه ((رواه مسلم)). "الحرة" الأرض الملبسة حجارة سوداء. "والشرجة" بفتح الشين المعجمة وإسكان الراء وبالجيم: هى مسيل الماء.', 'The Prophet (ﷺ) said, "While a man was walking through a barren land, he heard a voice coming out of a cloud saying: ''Irrigate the garden of so-and- so.'' Thereupon the cloud drifted in a certain direction and discharged its water over a rocky plain. The streamlets flowed into a channel. This man followed the channel until it reached a garden and he saw the owner of the garden standing in its center, working with his spade spreading the water (changing the course of the water). He asked him: "O slave of Allah, what is your name?" He told his name, which was the same that he heard from the cloud. The owner of the garden then asked him: "O slave of Allah, why did you ask my name?" He replied: "I heard a voice from a cloud which poured down this water saying: ''Irrigate the garden of so-and-so.'' I would like to know what do you do with it." He said: "Now that you asked me, I will tell you. I estimate the produce of the garden and distribute one-third of it in charity, I spend one-third on myself and my family and invest one-third back into the garden.".', null, 'Abu Hurairah (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 561', 'Riyad as-Salihin 561', 'ریاض الصالحین 561', null, 'بينا رجل بصحراء واسعة من الأرض، فسمع صوتًا في سحابة يقول: اسق بستان فلان، فابتعد ذلك السحاب عن مقصده، فأفرغ ماءه في أرض ذات حجارة سود، فإذا مسيل من تلك المسايل قد استوعب الماء كله، فتتبع الرجل الماء، فوجد رجلا قائما في حديقته يحول الماء من مكان إلى مكان من حديقته بمسحاته، فقال له: يا عبد الله ما اسمك؟ قال: فلان - للاسم الذي سمع في السحابة - فقال له: يا عبد الله لم تسألني عن اسمي؟ فقال: إني سمعت صوتا في السحاب الذي هذا ماؤه يقول: اسق حديقة فلان، لاسمك، فما تصنع في حديقتك من الخير حتى تستحق هذه الكرامة-، قال: أما إذ قلت هذا فإني أنظر إلى ما يخرج منها من زرع الحديقة وثمرها، فأتصدق بثلثه، وآكل أنا وعيالي ثلثًا، وأصرف في الحديقة للزراعة والعمارة ثلثه.', 'فضل الصدقة والإحسان إلى المساكين وأبناء السبيل.
الصدقة تنتج بالبركة والمعونة من الله -تعالى-.
فضل أكل الإنسان من كسبه والإنفاق على العيال.
من الملائكة من هو موكل بالأرزاق أو السحاب.
إثبات كرامات الأولياء.', 'فلاة : الأرض التي لا ماء فيها.
حديقة : القطعة من النخيل، ويطلق على الأرض ذات الشجر، وهي: البستان.
حرة : أرض ملبَّسة حجارة سوداء.
شرجة : مَسِيل الماء من الحَرَّة إلى السَّهل.
بمسحاته : المسحاة المجرفة من الحديد.', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/5776', false),
(20562, 2, 201, 562, 'hadith', 'عن جابر رضي الله عنه أن رسول الله صلى الله عليه وسلم قال: اتقوا الظلم فإن الظلم ظلمات يوم القيامة واتقوا الشح فإن الشح أهلك من كان قبلكم حملهم على أن سفكوا دماءهم واستحلوا محارمهم".', 'Messenger of Allah (ﷺ) said, "Beware of oppression, for oppression will be darkness on the Day of Resurrection; and beware of stinginess because it destroyed those who were before you. It incited them to shed their blood and deem unlawful as lawful.".', 'جابر رضي الله عنه', 'Jabir bin ''Abdullah (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 562', 'Riyad as-Salihin 562', 'ریاض الصالحین 562', 'رواه مسلم', 'حَذَّرَ النبيُّ صلى الله عليه وسلم من الظلم، ومنه: ظلم الناس وظلم النفس والظلم في حق الله تعالى، 
وهو تَرْكُ إعطاءِ كلِّ ذِي حقٍّ حقَّه، وأنَّ الظلم ظلمات على أصحابِه يوم القيامة من حصول الشدائد والأهوال، 
ونهى عن الشح الذي هو شدة البخل مع الحرص، ومنه التقصير في أداء الحقوق المالية وشدة الحرص على الدنيا، 
وهذا النوع من الظلم أَهْلَكَ من كان قبلنا من الأمم، حيث حَمَلَهم على قتل بعضهم، وإباحة ما حرم الله من المحرمات.', 'بذل المال ومواساة الإخوان من أسباب التَّحَابِّ والتواصل.
البخل والشح يَجُرُّ إلى المعاصي والفواحش والآثام.
الاعتبار بأحوال الأمم السابقة.', null, 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/5787', false),
(20563, 2, 201, 563, 'hadith', 'عن أبي هريرة رضي الله عنه قال: جاء رجل إلى النبي صلى الله عليه وسلم فقال: إنى مجهود، فأرسل إلى بعض نسائه، فقالت: والذى بعثك بالحق ما عندى إلا ماء، ثم أرسل إلى أخرى، فقالت مثل ذلك، حتى قلن كلهن مثل ذلك: لا والذى بعثك بالحق ما عندى إلا ماء. فقال النبي صلى الله عليه وسلم " من يضيفه هذا الليلة؟" فقال رجل من الأنصار: أنا يا رسول الله، فانطلق به إلى رحله ، فقال لامرأته: أكرمي ضيف رسول الله صلى الله عليه وسلم وفى رواية قال لامرأته : هل عندك شئ؟ قالت: لا، إلا قوت صبيانى. قال: فعلليهن بشئ.وإذا أرادوا العشاء فنوميهم. وإذا دخل ضيفنا فأطفئ السراج وأريه أنا نأكل، فقعدوا وأكل الضيف وبات طاويين، فلما أصبح ، غدا على النبي صلى الله عليه وسلم فقال: "لقد عجب الله من صنيعكما بضيفكما الليلة".', 'A man came to the Prophet (ﷺ) and said; "I am hard pressed by hunger." He (ﷺ) sent a word to one of his wives who replied: "By Him Who has sent you with the Truth, I have nothing except water." Then he sent the same message to another (wife) and received the same reply. He sent this message to all of them (i.e., his wives) and received the same reply. Then he (ﷺ) said, "Who will entertain this (man) as guest?" One of the Ansar said: "O Messenger of Allah, I will." So he took him home and said to his wife: "Serve the guest of Messenger of Allah (ﷺ)."Another narration is: The Ansari asked his wife: "Have you got anything?" She answered: "Nothing, except a little food for the children." He said: "Keep them busy with something, and when they ask for food put them to sleep. When the guest enters, extinguish the light and give him the impression that we are also eating." So they sat down and the guest ate and they passed the night hungry. When he came to the Prophet (ﷺ) in the morning, he said to him, "Allah admired what you did with your guest last night.".', 'أبي هريرة رضي الله عنه', 'Abu Hurairah (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 563', 'Riyad as-Salihin 563', 'ریاض الصالحین 563', 'متفق عليه', 'جاء رجل إلى النبي صلى الله عليه وسلم ، فقال: إني أجد مشقة وجوعا، فأرسل النبي صلى الله عليه وسلم إلى بعض أزواجه فقالت: والله ليس عندي إلا ماء، فأرسل إلى أخرى فقالت مثلها، وفعل ذلك مع أزواجه كلهن فقلن كما قالت، فقال النبي صلى الله عليه وسلم : من يضيف هذا الرجل الليلة؟ فقال رجل من الأنصار: أنا أضيفه يا رسول الله، ثم انطلق به إلى منزله، وقال لامرأته: هل عندك شيء نقدمه للضيف، فقالت: لا إلا طعام الصبيان، فقال: اشغليهم بشيء، وإذا أرادوا العشاء فنوميهم، وأمرها بإطفاء المصباح، وظن الضيف أنهما يأكلان، فشبع الضيف وباتا غير متعشيين إكرامًا لضيف رسول الله صلى الله عليه وسلم ، فلما أصبح وغدا إلى النبي صلى الله عليه وسلم ، أخبره الرسول صلى الله عليه وسلم أن الله قد عجب من صنيعهما تلك الليلة، والعجب على ظاهره لأنه فعل غريب يتعجب منه، وهو من الصفات الفعلية التي يثبتها أهل السنة والجماعة من غير تشبيهٍ ولا تمثيلٍ، وهو عجب استحسان لا استنكار، استحسن عز وجل صنيعهما تلك الليلة.', 'بيان حال رسول الله -صلى الله عليه وسلم- وما كان عليه من شدة العيش وضيقه، وقلة ذات اليد.
فضيلة إكرام الضيف وإيثاره.
الحض على الإيثار.
جواز تحويل الضيف إلى من يكون قادرًا على الإنفاق عليه وسد حاجته.
منقبة لهذا الأنصاري وامرأته -رضي الله عنهما-.
استحباب بيان الإعجاب ممن فعل حسنا.', 'مجهودٌ : أصابني الجهد، وهو: المشقة والحاجة وسوء العيش والجوع.
رحله : منزله.
فعلليهم بشيء : اشغليهم بشيء.
السراج : المصباح.
وأريه أنا نأكل : أظهري له بتحريك الأيدي على الطعام، وتحريك الفم والمضغ.
طاويين : جائعين.', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/5911', false),
(20564, 2, 201, 564, 'hadith', 'وعنه قال: قال رسول الله صلى الله عليه وسلم « طعام الاثنين كافي الثلاثة، وطعام الثلاثة كافي الأربعة» ((متفق عليه)) . وفى رواية لمسلم عن جابر رضي الله عنه ، عن النبي صلى الله عليه وسلم قال: طعام الواحد يكفي الاثنين وطعام الاثنين يكفي الأربعة، وطعام الأربعة يكفي الثمانية.', 'Messenger of Allah (ﷺ) said, "The food for two suffices for three; and the food for three suffices for four persons.".In Muslim, Jabir (May Allah be pleased with him) reported: The Prophet (ﷺ) said, "The food for one person suffices for two; the food for two suffices for four, and the food for four suffices for eight persons."', null, 'Abu Hurairah (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 564', 'Riyad as-Salihin 564', 'ریاض الصالحین 564', null, 'في الحديث الحث على المواساة في الطعام، وأنه وإن كان قليلاً حصلت منه الكفاية المقصودة، ووقعت فيه بركة تعم الحاضرين عليه، وهو حث منه عليه الصلاة والسلام على الإيثار يعني أنك لو أتيت بطعامك الذي قدرت أنه يكفيك، وجاء رجل آخر فلا تبخل عليه، وتقول هذا طعامي وحدي؛ بل أعطه منه حتى يكون كافياً للاثنين.', 'استحباب الاجتماع على الطعام، وألا يأكل المرء وحده.
البركة تتضاعف مع الكثرة والاجتماع على الطعام.
الحض على المكارم والقناعة بالكفاية.
الترغيب في إطعام الطعام ولو كان قليلاً.', '- : -', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/6057', false),
(20565, 2, 201, 565, 'hadith', 'عن أبي سعيد الخدرى قال: بينما نحن فى سفر مع النبي صلى الله عليه وسلم إذ جاء رجل على راحلة له ، فجعل يصرف بصره يمينا وشمالاً فقال رسول الله صلى الله عليه وسلم :« من كان معه فضل ظهر فليعد به على من لا ظهر له، ومن كان له فضل من زاد فليعد به على من لا زاد له» فذكر من أصناف المال ما ذكر حتى رأينا أنه لا حق لأحد منا فى فضل.', 'Once we were on a journey with Messenger of Allah (ﷺ) when a rider came and began looking right and left. Messenger of Allah (ﷺ) said, "Whoever has an extra mount should offer it to him who is without it, and whoever has surplus food should give it to him who has nothing;" and he continued mentioning other properties until we thought that none of us had any right to surplus of his own property..', null, 'Abu Sa''id Al-Khudri (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 565', 'Riyad as-Salihin 565', 'ریاض الصالحین 565', 'رواه مسلم', 'ذكر أبو سعيد الخدري رضي الله عنه أنهم كانوا في سفر مع النبي صلى الله عليه وسلم ، فجاء رجل على ناقة ينظر يمينا وشمالا ليجد شيئا يدفع به حاجته، فقال النبي صلى الله عليه وسلم : من كان معه زيادة في المركوب فليتصدق به على من ليس معه، ومن كان معه زيادة في الطعام فليتصدق به على من ليس معه.
يقول الراوي: حتى ظننا أنه لا حق لأحدنا فيما هو زائد عن حاجته.', 'الحض على التعاون والتكافل في الأزمات.
الأمر بالمواساة من الفاضل.
الإمام يرعى رعيته ويرشدها إلى أرشد أمرها.', 'راحلة : المركب من الإبل.
يصرف : يجول.
فضل ظهر : مركوب فاضل وزائد عن حاجته.
زاد : طعام.
فليعد به : فليتصدق به.', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/5906', false),
(20566, 2, 201, 566, 'hadith', 'عن سهل بن سعد رضي الله عنه، أن امرأة جاءت إلى رسول الله صلى الله عليه وسلم ببردة منسوجة فقالت: نسجتها لأكسوكها، فأخذها النبي صلى الله عليه وسلم محتاجاً إليها ، فخرج إلينا وإنها إزاره، فقال فلان، اكسونيها ما أحسنها! فقال:« نعم» فجلس النبي صلى الله عليه وسلم فى المجلس ثم رجع فطواها ثم أرسل به إليه: فقال له القوم: ما أحسنت! لبسها النبي صلى الله عليه وسلم محتاجاً إليها ثم سألته وعلمت أنه لا يرد سائلاً ، فقال: إنى والله ما سألته لألبسها وإنما سألته لتكون كفني، قال سهل: فكانت كفنه.', 'A woman brought a woven piece of cloth to Messenger of Allah (ﷺ) and said to him: "I have woven this sheet with my own hands for you to wear." He accepted it as he was in need of it. He later came out wearing it as a lower garment. Someone said: "How nice it is! Kindly give it to me." Messenger of Allah (ﷺ) said, "Very well." He remained in our company for some time, then he went back, folded it and sent it to the man. The people said (to that man): "You did not do well. Messenger of Allah (ﷺ) wore it and he was in need of it, and you asked him for it when you are well aware that he (ﷺ) never refuses a request." He said: "I swear by Allah that I did not ask it for wearing. I asked him for it so that it might be my shroud after my death." Sahl (the narrator of this Hadith) said: And in fact it was used as his shroud..', 'سهل بن سعد رضي الله عنه', 'Sahl bin Sa''d (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 566', 'Riyad as-Salihin 566', 'ریاض الصالحین 566', 'رواه البخاري', 'في الحديث إيثار النبي صلى الله عليه وسلم على نفسه؛ لأنه آثر هذا الرجل بهذه البردة التي كان محتاجاً إليها؛ لأنه لبسها بالفعل مما يدل على شدة احتياجه إليها، فإن امرأة جاءت وأهدت إلى النبي صلى الله عليه وسلم بردة، فتقدم رجل إليه فقال: ما أحسن هذه؟، وطلبها من النبي صلى الله عليه وسلم ، ففعل الرسول عليه الصلاة والسلام خلعها وطواها وأعطاه إياها.
ذكر بعض الشرّاح أن من فوائد هذا الحديث التبرك بآثار الصالحين، وليس كذلك إنما هو التبرك بذاته –صلى الله عليه وسلم- ولا يقاس غيره به في الفضل والصلاح، وأيضاً الصحابة لم يكونوا يفعلون ذلك مع غيره لا في حياته ولا بعد موته، ولو كان خيراً لسبقونا إليه.', 'حسن خلق النبي –صلى الله عليه وسلم - وكرمه وسعة جوده، وأنه لا يرد سائلاً.
استحباب المبادرة لأخذ الهدية؛ لجبر خاطر مهديها، وأنها وقعت منه موقعاً.
مشروعية الإنكار عند مخالفة الأدب ظاهراً، وإن لم يبلغ المنكر درجة التحريم.
جواز استحسان الإنسان ما يراه على غيره من الملابس وغيرها؛ إما ليعرفه قدرها، وإما ليعرض له بطلبه منه حيث يسوغ له ذلك.
جواز إعداد الشيء قبل الحاجة إليه.', 'البردة : كساء مخطط يلتحف به.
إزاره : لفها على جسمه من أسفل، والإزار ما يلبس أسفل البدن لستر العورة.
فطواها : ضم بعضها على بعض.', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/5648', false),
(20567, 2, 201, 567, 'hadith', 'عن أبي موسى رضي الله عنه قال رسول الله صلى الله عليه وسلم : إن الأشعريين إذا أرملوا فى الغزو، أو قل طعام عيالهم بالمدينة جمعوا ما كان عندهم فى ثوب واحد، اقتسموه بينهم فى إناء واحد بالسوية فهم منى وأنا منهم" ((متفق عليه)) . "أرملوا" فرغ زادهم أو قارب الفراغ.', 'Messenger of Allah (ﷺ) said, "When the Ash''ariyun run short of food in the Jihad or when they are at home in Al-Madinah, they collect all the provisions they have in a sheet and then divide it equally among themselves. They are of me and I am of them.".', 'أبي موسى رضي الله عنه', 'Abu Musa (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 567', 'Riyad as-Salihin 567', 'ریاض الصالحین 567', null, 'إن الأشعريين وهم قوم أبي موسى رضي الله عنه إذا قل طعامهم أو كانوا في الغزو للجهاد في سبيل الله جمعوا طعامهم واقتسموه بينهم بالمساواة، فلذلك استحقوا أن ينسبوا إلى رسول الله صلى الله عليه وسلم نسبة شرف ومحبة، وهو كذلك منهم عليه السلام على طريقتهم في هذا الخلق العظيم من الإيثار ولزوم الطاعة.', 'بيان فضيلة الأشعريين.
جواز تحديث الرجل بمناقب قومه.
فضيلة الإيثار والمواساة.
استحباب خلط الزاد في السفر والحضر أيضاً.
جواز التأمين التعاوني، وهو أن يدفع أفراد أموالًا تعطى للمحتاج منهم، ويكون الفائض لصالح الجميع.', 'الأشعريون : هم قبيلة باليمن، منهم أبو موسى الأشعري رضي الله عنه.
أرملوا : فرغ زادُهم، أو قارب الفراغ.
في الغزو : الخروج لقتال العدو.
بالسوية : بالعدل و النصيفة.
فهم مني : قريبون خلقاً وهدياً.', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/5543', false),
(20568, 2, 201, 568, 'hadith', 'عن سهل بن سعد رضي الله عنه أن رسول الله صلى الله عليه وسلم أتي بشراب، فشرب منه وعن يمينه غلام، وعن يساره الأشياخ، فقال للغلام:" أتأذن لى أن أعطي هؤلاء؟" فقال الغلام لا والله يا رسول الله، لا أؤثر منك أحداً، فتله رسول الله صلى الله عليه وسلم فى يده . ((متفق عليه)) . "تله" بالتاء المثناه، فوق ، أى وضعه، وهذا الغلام هو ابن عباس رضي الله عنهما.', 'A drink was brought to the Messenger of Allah (ﷺ) and he drank some of it. On his right was a boy and on his left were elderly people. He said to the boy, "Would you permit me to give the rest of this drink to these on my left?" The boy said, "O Messenger of Allah, I would certainly not give preference to anyone in anything that might come to me from you." So he handed over the rest of the drink to him..', 'سهل بن سعد رضي الله عنه', 'Sahl bin Sa''d (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 568', 'Riyad as-Salihin 568', 'ریاض الصالحین 568', null, 'في الحديث استأذن النبي –صلى الله عليه وسلم- الغلام في إعطاء الشراب الأشياخ قبله، وإنما فعل ذلك تألفاً لقلوب الأشياخ، وإعلاماً بودهم، وإيثار كرامتهم، إذا لم تمنع منها سنة، وتضمن ذلك بيان هذه السنة وهي أن الأيمن أحق، ولا يدفع إلى غيره إلا بإذنه، وأنه لا بأس باستئذانه، وأنه لا يلزمه الإذن، وينبغي له أيضاً أن لا يأذن إن كان فيه تفويت فضيلة أخروية ومصلحة دينية، وهذا الغلام هو ابن عباس رضي الله عنهما .', 'سنة الشرب العامة تقديم الأيمن في كل موطن.
من استحق شيئاً لم يُدفع عنه إلا بإذنه.
استحباب توقير الكبار، وإنزال الناس منازلهم في الفضل والكرامة.
حرص الصحابة -رضي الله عنهم- على ما ينفعهم.
البدء بالضيافة بأفضل من في المجلس، ثم من على يمينه.
من يسبق إلى مجالسة الإمام والعالم أنه لا يقام لمن هو أسن منه.', 'الأشياخ : جمع شيخ، وهو من طعن في السن.
لا أُوثر : لا أُفضل أحداً على نفسي، فأعطيه نصيبي من الشراب.
بنصيبي منك : بحقي في الشراب من أثر بركتك وفضلك.
تَلَّه : وضعه.', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/5651', false),
(20569, 2, 201, 569, 'hadith', 'عن أبي هريرة رضي الله عنه ، عن النبي صلى الله عليه وسلم قال: "بينما أيوب عليه السلام يغتسل عريانا، فخر عليه جراد من ذهب، فجعل أيوب يحثي فى ثوبه فناداه ربه عز وجل يا أيوب ألم أكن أغنيتك عما ترى؟! قال:بلى وعزتك، ولكن لا غنى بى عن بركتك.', 'The Prophet (ﷺ) said, "While Ayyub (ﷺ) the Prophet was taking a bath, naked, a large number of gold locusts fell on him. He tried to collect them in a piece of cloth, when he heard his Rubb (Allah) calling him: ''O Ayyub ! Have I not sufficed you to care for what you see (the worldly possessions)?'' Ayyub (ﷺ) said: ''Indeed by Your Power, but I can never do away with Your Blessings."''.', 'أبي هريرة رضي الله عنه', 'Abu Hurairah (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 569', 'Riyad as-Salihin 569', 'ریاض الصالحین 569', 'رواه البخاري', 'كان أيوب -عليه السلام- يغتسل عريانًا، فسقط عليه ذهب كثير على هيئة الجراد، فجعل أيوب -عليه السلام- يأخذه ويرميه في ثوبه، فناداه ربه عز وجل : ألم أكن أغنيتك عن هذا؟ فقال: بلى وعزتك، ولكني لم آخذه شرهًا وحرصًا على الدنيا، إنما لكونه بركةً منك.', 'جواز الحرص والاستكثار من الحلال في حق من وثق من نفسه بالشكر.
جواز الاغتسال عرياناً إذا كان وحده في خلوة، وإن تستر فالستر أولى، وهو مذهب الجمهور.
الحث على التماس ما يزداد الإنسان به بركةً وفضلًا.', 'فخرَّ : سقط.
جراد من ذهب : قطع ذهب تشبه الجراد، من حيث الشكل والكثرة.
يحثي : يأخذ ذلك ويرميه في ثوبه.
وعزتك : العزة: المنعة والغلبة.', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/5774', false),
(20570, 2, 201, 570, 'hadith', 'عن عبد الله بن مسعود رضي الله عنه قال: قال رسول الله صلى الله عليه وسلم : « لا حسد إلا فى اثنتين : رجل آتاه الله مالاً ، فسلطه على هلكته فى الحق، ورجل آتاه الله حكمة فهو يقضي بها ويعلمها».', 'Messenger of Allah (ﷺ) said, "Envy is permitted only in two cases: A man whom Allah gives wealth, and he disposes of it rightfully, and a man to whom Allah gives knowledge which he applies and teaches it.".', 'عبد الله بن مسعود رضي الله عنه', 'Ibn Mas''ud (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 570', 'Riyad as-Salihin 570', 'ریاض الصالحین 570', 'متفق عليه وتقدم شرحه قريباً', 'يُشير النبي صلى الله عليه وسلم هنا إلى أن الحَسَدَ أنواع مختلفة فمنه حسد مَذْمُوم محرم شرعًا، وهو أن يتمنى المرء زوال النعمة عن أخيه، وحسد مباح وهو أن يرى نعمة دنيوية عند غيره فيتمنى لنفسه مثلها، وحسد محمود مستحب شرعًا، وهو أن يرى نعمة دينية عند غيره فيتمناها لنفسه. وهو ما عناه النبي صلى الله عليه وسلم بقوله: "لا حَسَدَ إلا في اثنتين" أي أن الحسد تختلف أنواعه وأحكامه حسب اختلاف أنواعه ولا يكون محمودًا مستحبًا شرعيًا إلا في أمرين: 
الأمر الأول: أن يكون هناك رجل غني تقي، أعطاه الله مالا حلالا، فينفقه في سبيل الله تعالى، فيتمنى أن يكون مثله، ويَغْبِطَه على هذه النعمة. 
الأمر الثاني: أن يكون هناك رجل عالم، أعطاه الله علما نافعا يعمل به، ويعلمه لغيره، ويحكم به بين الناس، فيتمنى أن يكون مثله.', 'الحَسَدُ داء خطير يجب الابتعاد عنه والحذر منه.
حسد الغِبْطَة محمود إذا كان في وجوه الخير.
فضل الغني الذي لا يبخل بما آتاه الله .
الواجب شكر المُنْعِم على ما أنعم به على العبد وذلك بأن يضعها العبد في موضعها.
استحباب الإنفاق وبذل المال والخروج عنه بالكلية في وجوه الخير ما لم يؤد إلى حرمان الورثة أو سؤال الناس ونحو ذلك مما حَرَّمَه الشرع.
فضل العلم بأحكام الدين وتعليم الناس ودعوتهم إلى التفقه في الدين.', 'الحسد : الغبطة ، وهي: أن يتمنى مثله.
سلطه : مكنه الله من إنفاقه في وجوه الخير.
هلكته : وجوه إنفاقه ومجالات صرفه.
في الحق : في أنواع البر ونواحي الخير.
حكمة : وضع كل شيء في موضعه.
يقضي بها : يحكم ويفتي بين الناس بمقتضاها.
آناء : الآناء: الساعات', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/3772', false),
(20571, 2, 201, 571, 'hadith', 'عن ابن عمر رضي الله عنهما: عن النبي صلى الله عليه وسلم قال :" لا حسد إلى فى اثنتين: رجل آتاه الله القرآن، فهو يقوم به آناء الليل وآناء النهار، ورجل آتاه الله مالاً فهو ينفقه آناء الليل وآناء النهار" ((متفق عليه)) "الآناء":الساعات .', 'Messenger of Allah (ﷺ) said: "Envy is justified in regard to two types of persons only: a man whom Allah has given knowledge of the Qur''an, and so he recites it during the night and during the day; and a man whom Allah has given wealth and so he spends from it during the night and during the day.".', 'ابن عمر رضي الله عنهما', 'Ibn ''Umar (May Allah be pleased with him)', null, 'رياض الصالحين 571', 'Riyad as-Salihin 571', 'ریاض الصالحین 571', null, null, null, null, 'sunnah.com', null, false, null, false),
(20572, 2, 201, 572, 'hadith', 'عن أبي هريرة رضي الله عنه أن فقراء المهاجرين أتوا رسول الله صلى الله عليه وسلم فقالوا: "ذهب أهل الدثور بالدرجات العلى والنعيم المقيم، فقال: "وما ذاك؟" فقالو":يصلون كما نصلى، ويصومون كما نصوم ويتصدقون ولانتصدق، ويعتقون ولا نعتق فقال: رسول الله صلى الله عليه وسلم :" أفلا أعلمكم شيئا تدركون به من سبقكم، وتسبقون به من بعدكم ، ولا يكون أحد أفضل منكم إلا من صنع مثل ما صنعتم؟" قالوا: بلى يا رسول الله ، قال: تسبحون ، وتكبرون، وتحمدون ، دبر كل صلاة ثلاثاً وثلاثين مرة" فرجع فقراء المهاجرين إلى رسول الله صلى الله عليه وسلم ، فقالو: سمع إخواننا أهل الأموال بما فعلنا، ففعلوا مثله؟ فقال رسول الله صلى الله عليه وسلم "ذلك فضل الله يؤتيه من يشاء" ((متفق عليه)) ، وهذا لفظ رواية مسلم.', 'Some of the poor Emigrants came to Messenger of Allah (ﷺ) and said to him, "The wealthy have obtained all high ranks and everlasting bliss." He asked, "How is that?" They replied: "They offer Salaah as we do, and observe Saum (fasting) as we do, but they give in Sadaqah (charity) and we do not, and they emancipate slaves and we cannot." He (ﷺ) said, "Shall I not teach you something whereby you will catch up with those who have preceded you and will get ahead of those who follow you, and no one will surpass you unless he does the same as you do?" They said, "Surely, O Messenger of Allah." He said, "Say: Subhan Allah, and Allahu Akbar, and praise Him (by saying Al-hamdu lillah) thirty-three times at the end of every Salaah." They returned to him and said: "Our brothers, the possessors of wealth, having heard what we are doing, have started doing the same." Messenger of Allah (ﷺ) said, "This is Grace of Allah which He gives to whom He wishes.".', 'أبي هريرة رضي الله عنه', 'Abu Hurairah (May Allah be pleased with him)', null, 'رياض الصالحين 572', 'Riyad as-Salihin 572', 'ریاض الصالحین 572', null, null, null, null, 'sunnah.com', null, false, null, false),
(20573, 2, 201, 573, 'hadith', 'عن ابن عمر رضي الله عنهما قال: أخذ رسول الله صلى الله عليه وسلم بمنكبي فقال: "كن فى الدنيا كأنك غريب أو عابر سبيل". وكان ابن عمر رضي الله عنهما يقول: إذا أمسيت، فلا تنتظر الصباح، وإذا أصبحت، فلا تنتظر المساء، وخذ من صحتك لمرضك، ومن حياتك لموتك ".', 'Messenger of Allah (ﷺ) took hold of my shoulders and said, "Be in the world like a stranger or a wayfarer." Ibn ''Umar (May Allah be pleased with them) used to say: When you survive till the evening do not expect to live until the morning; and when you survive till the morning do not expect to live until the evening. While in good health (do good deeds) before you fall sick; and while you are alive (do good deeds) before death strikes..', 'ابن عمر رضي الله عنهما', '''Abdullah bin ''Umar (May Allah be pleased with them)', 'صحيح', 'رياض الصالحين 573', 'Riyad as-Salihin 573', 'ریاض الصالحین 573', 'رواه البخاري', 'ذَكَرَ ابنُ عُمر رضي الله عنهما بأن النبي صلى الله عليه وسلم أخذ بمنكبه -وهو مَجْمَع العَضُد والكَتِف- وقال له: كن في الدنيا كأنك غريب، قَدِمَ بلدًا لا مَسْكن لَهُ فيه يؤويه، ولا ساكن يسليه، خالٍ عن الأهل والعيال والعلائق، التي هي سبب الاشتغال عن الخالق، بل كن أشدَّ من الغريب وهو عابر السبيل المار على الطريق طالبًا وطنه؛ لأن الغريب قد يسكن في بلاد الغُرْبة ويُقيم فيها، بخلاف عابر السبيل القاصد للبلد، فإن من شأنه التخفف وعدم التوقف، والحرص على وصول بلده، فكما أن المسافر لا يحتاج إلى أكثر مما يبلغه إلى غاية سفره، فكذلك لا يحتاج المؤمن في الدنيا إلى أكثر مما يبلغه المَحل. 

فعمل ابن عمر بهذه النصيحة وكان يقول: إذا أصبحتَ فلا تنتظر المساء، وإذا أمسيتَ فلا تنتظر الصباح، وعُدَّ نفسك في أهل القبور، ولأن العمرَ لا يخلو عن صحة ومرض؛ 
فبادر أيام صحتك بالطاعة لمرضك؛ واغتنم الأعمال الصالحة في الصحة قبل أن يحول بينك وبينها المرض، واغتنم حياتك في الدنيا، فاجمع فيها ما ينفعك بعد موتك.', 'وضع المُعلّم كفَّه على كتف المتعلم عند التعليم للتأنيس والتنبيه.
الابتداء بالنصيحة والإرشاد لمن لم يطلب ذلك.
حسن تعليم النبي صلى الله عليه وسلم بضرب الأمثال المُقْنِعَة، بقوله: "كُنْ فِي الدُّنْيَا كَأَنَّكَ غَريْبٌ أَوْ عَابِرُ سَبِيْلٍ".
اختلاف الناس في سيْرهم إلى الآخرة؛ فعابر السبيل، منزلة أعلى في الزهد من منزلة الغريب.
 بيان قِصَر الأمل، والاستعداد للموت.
 الحديث لا يدل على ترك الرزق وتحريم ملذات الدنيا؛ ولكن يدل على الترغيب في الزهد فيها، والتَّقَلُّل منها.
المسارعة إلى الأعمال الصالحة قبل أن لا يقدر عليها، ويحول مرض أو موت.
فضيلة عبد الله بن عمر رضي الله عنهما حيث تأثّر بهذه الموعظة من رسول الله صلى الله عليه وسلم.
وطن المؤمنين هي الجنة فهو غريب على الدنيا، وهو مسافر للدار الآخرة، فلا يُعلِّق قلبه بشيء من بلد الغربة، بل قلبه متعلق بوطنه الذي يرجع إليه، وإقامته في الدنيا ليقضي حاجته وجهازه للرجوع إلى وطنه.', null, 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/4704', false),
(20574, 2, 201, 574, 'hadith', 'وعنه أن رسول الله صلى الله عليه وسلم قال: " ما حق امرئ مسلم ، له شئ يوصي فيه ، يبيت ليلتين إلا ووصيته مكتوبة عنده" ((متفق عليه)) هذا لفظ البخاري. وفى رواية لمسلم" يبيت ثلاث ليال: قال ابن عمر: ما مرت على ليلة منذ سمعت رسول الله صلى الله عليه وسلم قال ذلك إلا وعندي وصيتي.', 'Messenger of Allah (ﷺ) said, "It is the duty of a Muslim who has something which is to be given as a bequest not to have it for two nights without executing a written will.".In the narration of Muslim it is narrated as ''three nights''. Ibn ''Umar (May Allah be pleased with them) said: Since I heard the Messenger of Allah say this, I have never spent a night without having my will with me.', null, '''Abdullah bin ''Umar (May Allah be pleased with them)', null, 'رياض الصالحين 574', 'Riyad as-Salihin 574', 'ریاض الصالحین 574', null, null, null, null, 'sunnah.com', null, false, null, false),
(20575, 2, 201, 575, 'hadith', 'عن أنس رضي الله عنه قال: خط النبي صلى الله عليه وسلم خطوطا فقال: «هذا الإنسان، وهذا أجله، فبينما هو كذلك إذ جاء الخط الأقرب».', 'The Prophet (ﷺ) drew a few lines and said, "One of them represents man and another indicates death; and a man continues like this until the nearest line (i.e., death) overtakes him.".', 'أنس رضي الله عنه', 'Anas (May Allah be pleased with him)', 'صحيحان', 'رياض الصالحين 575', 'Riyad as-Salihin 575', 'ریاض الصالحین 575', 'رواه البخاري', 'في الحديثين مثال أمل الإنسان وأجله والأعراض التي تعرض عليه، وموته عند واحد منها، فإن سلم منها فيأتيه الموت عند انقضاء أجله، وهذه الخطوط الآفات العارضة له فإن سلم من هذا لم يسلم من هذا، وإن سلم من الجميع ولم تصبه آفة من مرض أو فقد مال أو غير ذلك بغته الأجل، والحاصل إن من لم يمت بالسبب مات بالأجل، فبينما الإنسان كذلك في هذه الآفات "إذ جاءه الخط الأقرب" وهو الأجل.
وفيه إشارة إلى الحض على قصر الأمل والاستعداد لبغتة الأجل، وعبر بالنهش وهو لدغ ذات السم مبالغة في الإصابة والإهلاك.', 'تحذير الإنسان من فجأة الموت وهو على غير استعداد له بالعمل الصالح.
على المؤمن المسارعة للتوبة والعمل الصالح، ولا يغتر بطول الأمل.
جواز ضرب المثل واتخاذ وسائل الإيضاح عند التعليم، ليكون أبلغ في التصور عند التلقي.', 'محيطاً به : حافاً به.
الأعراض : جمع عرض، وهو ما ينتفع به في الدنيا في الخير وفي الشر.
نهشه : أصابه وأهلكه.', 'sunnah.com', null, false, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/6821', false),
(20576, 2, 201, 576, 'hadith', 'عن ابن مسعود رضي الله عنه قال: خط النبي صلى الله عليه وسلم خطا مربعا، وخط خطاً فى الوسط خارجاً منه، وخط خططاً صغاراً إلى هذا الذى فى الوسط من جانبه الذى فى الوسط، فقال: «هذا الإنسان، وهذا أجله محيطا به -أو قد أحاط به- وهذا الذى هو خارج أمله، وهذه الخطط الصغار الأعراض فإن أخطأه هذا ، نهشه هذا، وإن أخطأه هذا نهشه هذا».', 'The Prophet (ﷺ) drew up a square and in the middle of it he drew a line, the end of which jutted out beyond the square. Further across the middle line, he drew a number of smaller lines. Then he (ﷺ) said, "The figure represents man and the encircling square is the death which is encompassing him. The middle line represents his desires and the smaller lines are vicissitudes of life. If one of those misses him, another distresses him, and if that one misses him, he falls victim to another.".', 'ابن مسعود رضي الله عنه', 'Ibn Mas''ud (May Allah be pleased with him)', 'صحيحان', 'رياض الصالحين 576', 'Riyad as-Salihin 576', 'ریاض الصالحین 576', 'رواه البخاري', 'في الحديثين مثال أمل الإنسان وأجله والأعراض التي تعرض عليه، وموته عند واحد منها، فإن سلم منها فيأتيه الموت عند انقضاء أجله، وهذه الخطوط الآفات العارضة له فإن سلم من هذا لم يسلم من هذا، وإن سلم من الجميع ولم تصبه آفة من مرض أو فقد مال أو غير ذلك بغته الأجل، والحاصل إن من لم يمت بالسبب مات بالأجل، فبينما الإنسان كذلك في هذه الآفات "إذ جاءه الخط الأقرب" وهو الأجل.
وفيه إشارة إلى الحض على قصر الأمل والاستعداد لبغتة الأجل، وعبر بالنهش وهو لدغ ذات السم مبالغة في الإصابة والإهلاك.', 'تحذير الإنسان من فجأة الموت وهو على غير استعداد له بالعمل الصالح.
على المؤمن المسارعة للتوبة والعمل الصالح، ولا يغتر بطول الأمل.
جواز ضرب المثل واتخاذ وسائل الإيضاح عند التعليم، ليكون أبلغ في التصور عند التلقي.', 'محيطاً به : حافاً به.
الأعراض : جمع عرض، وهو ما ينتفع به في الدنيا في الخير وفي الشر.
نهشه : أصابه وأهلكه.', 'sunnah.com', null, false, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/6821', false),
(20577, 2, 201, 577, 'hadith', 'عن أبي هريرة رضي الله عنه أن رسول الله صلى الله عليه وسلم: قال: «بادروا بالأعمال سبعاً، هل تنتظرون إلا فقراً منسياً، أو غنى مطغياً، أو مرضاً مفسداً، أو هرماً مفنداً، أو موتاً مجهزاً، أو الدجال، فشر غائب ينتظر، أو الساعة، فالساعة أدهى وأمر؟!».', 'Messenger of Allah (ﷺ) said, "Hasten to do good deeds before you are overtaken by one of the seven afflictions." Then (giving a warning) he said, "Are you waiting for poverty which will make you unmindful of devotion, or prosperity which will make you corrupt, or a disease which will disable you, or senility which will make you mentally unstable, or sudden death which will take you all of a sudden, or Ad-Dajjal who is the worst expected, or the Hour; and the Hour will be most grievous and most bitter.".', 'أبي هريرة رضي الله عنه', 'Abu Hurairah (May Allah be pleased with him)', 'حسن', 'رياض الصالحين 577', 'Riyad as-Salihin 577', 'ریاض الصالحین 577', 'رواه الترمذى وقال: حديث حسن', null, null, null, 'sunnah.com', null, false, null, false),
(20578, 2, 201, 578, 'hadith', 'وعنه قال: قال رسول الله صلى الله عليه وسلم: «أكثروا ذكر هاذم اللذات».', 'Messenger of Allah (ﷺ) said, "Remember more often the destroyer of pleasures - death.".', null, 'Abu Hurairah (May Allah be pleased with him)', 'حسن', 'رياض الصالحين 578', 'Riyad as-Salihin 578', 'ریاض الصالحین 578', 'يعنى الموت)) ((رواه الترمذى وقال: حدث حسن', null, null, null, 'sunnah.com', null, false, null, false),
(20579, 2, 201, 579, 'hadith', 'عن أبي بن كعب رضي الله عنه: كان رسول الله صلى الله عليه وسلم: إذا ذهب ثلث الليل، قام فقال: "يا أيها الناس اذكروا الله، جاءت الراجفة، تتبعها الرادفة، جاء الموت بما فيه، جاء الموت بما فيه" قلت: يا رسول الله إنى أكثر الصلاة عليك، فكم أجعل لك من صلاتى؟ قال: "ما شئت" قلت: الربع؟ قال: "ما شئت، فإن زذت فهو لك" قلت: فالنصف؟ قال: ما شئت فإن زذت فهو لك قلت " فالثلثين؟ قال: ما شئت فإن زدت فهو خير لك" قلت: أجعل لك صلاتى كلها؟ قال: "إذا تكفى همك، ويغفر لك ذنبك".', 'When one- third of the night would pass, Messenger of Allah (ﷺ) would get up and call out, "O people, remember Allah. The Rajifah (i.e., the first Blowing of the Trumpet which will shake the whole universe and thus cause all life to cease) has come, followed by Ar-Radifah (i.e., the second Blowing of the Trumpet which will restore life and thus mark the Resurrection Day). Death has approached with all that it comprises. Death has approached with all that it comprises." I said: "O Messenger of Allah (ﷺ), I frequently invoke Allah to elevate your rank. How much of my supplications should I devote to you?" He said, "You may devote as much as you wish." When I suggested a quarter, he said, "Do whatever you wish, but it will be better for you if you increase it." I suggested half, and he said, "Do whatever you wish, but it will be better for you if you increase." I suggested two- thirds, and he said, "Do whatever you wish but it will be better for you if you increase it." I said, "Shall I devote all my supplications invoking Allah to elevate your rank?" He said, "Then you will be freed from your worries and your sins will be forgiven.".', 'أبي بن كعب رضي الله عنه', 'Ubayy bin Ka''b (May Allah be pleased with him)', 'حسن', 'رياض الصالحين 579', 'Riyad as-Salihin 579', 'ریاض الصالحین 579', 'رواه الترمذى وقال: حديث حسن', 'ذكر في أول الحديث أن النبي –صلى الله عليه وسلم- كان إذا قام من ثلث الليل، قال منبهاً لأمته من الغفلة، محرضاً لها على ما يوصلها لمرضاة الله سبحانه من كمال رحمته "يا أيها الناس اذكروا اللّه"، أي: باللسان والجنان ليَحمِل ما يحصل من ثمرة الذكر على الإكثار من عمل البرّ وترك غيره.
وفي الحديث أيضاً أن السائل قد يكون له دعاء يدعو به لنفسه، فيمكن أن يجعل ثُلثَه دعاءً للنبي -صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ- ، ويمكن أن يجعل له شَطْرَه، ويمكن أن يكون جميعُ دعائِه دعاءً للنبي، مثل أن يُصلِّي عليه بدلَ دعائه. وقد ثبتَ أنه: "من صلَّى عليه مرة صلَّى الله عليه عشراً" أخرجه مسلم من حديث أبي هريرة، فيكون أجر صلاته كافياً له، ولهذا قال: "يَكفِيْ همَّك ويَغفِر ذنبَك"، أي: إنك إنما تطلب زوالَ سبب الضرر الذي يُعقِب الهمَّ ويُوجب الذنب، فإذا صليتَ علي بدل دعائك حصل مقصودك، ويحتمل هذا الحديث أن المراد أن يشركه معه في الدعاء، فكأنه قال: كلما دعوت لنفسي صليت عليك، ولا يدل على الاكتفاء بالصلاة عن الدعاء، بل يجمع بينهما عملًا بجميع النصوص.', 'أفضل القيام ما كان في ثلث الليل الأخير.
فضل الصلاة على النبي –صلى الله عليه وسلم-.
جواز ذكر الإنسان صالح عمله إذا أمن من العُجب؛ لغرض كالاستفتاء.
قرب الموت من العباد، ولكن أكثر الناس غافلون عنه.', 'الراجفة : النفخة الأولى.
الرادفة : النفخة الثانية.
من صلاتي : من دعائي.
تكفى همك : المتعلق بالدارين.', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/6181', false),
(20580, 2, 201, 580, 'hadith', 'عن بريدة رضي الله عنه قال قال رسول الله صلى الله عليه وسلم "كنت نهيتكم عن زيارة القبور فزوروها" ((رواه مسلم)). وفي رواية "فمن أراد أن يزور القبور فليزر؛ فإنها تذكرنا الآخرة "', 'Messenger of Allah (ﷺ) said, "(In the past) I forbade you from visiting graves, but visit them now."

In another narration Messenger of Allah (ﷺ) said, "Whoever wants to visit a graveyard, let him do so, because it reminds us of the Hereafter."', 'بريدة رضي الله عنه', 'Buraidah (May Allah be pleased with him)', null, 'رياض الصالحين 580', 'Riyad as-Salihin 580', 'ریاض الصالحین 580', null, null, null, null, 'sunnah.com', null, false, null, false),
(20581, 2, 201, 581, 'hadith', 'عن عائشة رضي الله عنها قالت: كان رسول الله صلى الله عليه وسلم كلما كان ليلتها من رسول الله صلى الله عليه وسلم يخرج من آخر الليل إلى البقيع، فيقول: السلام عليكم دار قوم مؤمنين، وأتاكم ما توعدون، غداً مؤجلون وإنا إن شاء الله بكم لاحقون، اللهم اغفر لأهل بقيع الغرقد".', 'reported Whenever it was her turn to spend with Messenger of Allah (ﷺ), he used to go to the Baqi'' (graveyard in Al-Madinah) at the last part of night and say, "May you be safe, O abode of the believing people. What you have been promised has come to you. You are tarried till tomorrow and certainly we shall follow you if Allah wills. O Allah, forgive the inmates of the Baqi''-al-Gharqad.".', 'عائشة رضي الله عنها', '''Aishah (May Allah be pleased with her):', 'صحيح', 'رياض الصالحين 581', 'Riyad as-Salihin 581', 'ریاض الصالحین 581', 'رواه مسلم', null, null, null, 'sunnah.com', null, false, null, false),
(20582, 2, 201, 582, 'hadith', 'عن بريدة رضي الله عنه قال: كان النبي صلى الله عليه وسلم يعلمهم إذا خرجوا إلى المقابر أن يقول قائلهم: «السلام عليكم أهل الديار من المؤمنين والمسلمين وإنا إن شاء الله بكم للاحقون، أسأل الله لنا ولكم العافية».', 'The Prophet (ﷺ) used to teach them (i.e., the Companions) whenever they came out to visit the graveyard to say: "As-salamu ''alaikum ahlad-diyyari minal- Mu''minina wal-Muslimina, wa inna in sha'' Allahu bikum lahiqun. As ''alul-laha lana wa-lakumul- ''afiyyah (May you be safe, O inmates of the abodes of the believers and the Muslims, and if Allah pleases, we shall follow you, we pray to Allah for well-being for ourselves and for you).".', 'بريدة رضي الله عنه', 'Buraidah (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 582', 'Riyad as-Salihin 582', 'ریاض الصالحین 582', 'رواه مسلم', null, null, null, 'sunnah.com', null, false, null, false),
(20583, 2, 201, 583, 'hadith', 'عن ابن عباس رضي الله عنهما، قال مر رسول الله صلى الله عليه وسلم بقبور بالمدينة فأقبل عليهم بوجهه فقال: «السلام عليكم يا أهل القبور، يغفر الله لنا ولكم أنتم سلفنا ونحن بالأثر».', 'Messenger of Allah (ﷺ) passed by the graves at Al-Madinah. He turned his face towards them and said, "May you be granted safety, O inmates of the graves. May Allah forgive us and you. You have preceded us, and we are to follow.".', 'ابن عباس رضي الله عنهما', 'Ibn ''Abbas (May Allah be pleased with them)', 'حسن', 'رياض الصالحين 583', 'Riyad as-Salihin 583', 'ریاض الصالحین 583', 'رواه الترمذي وقال: حديث حسن', null, null, null, 'sunnah.com', null, false, null, false),
(20584, 2, 201, 584, 'hadith', 'عن أبي هريرة رضي الله عنه أن رسول الله صلى الله عليه وسلم قال: "لا يتمن أحدكم الموت إما محسناً فلعله يزداد، وإما مسيئاً فلعله يستعتب" ((متفق عليه)) .وهذا لفظ البخاري وفى رواية لمسلم عن أبي هريرة رضي الله عنه عن رسول الله صلى الله عليه وسلم قال: "لا يتمن أحدكم الموت، ولا يدع به من قبل أن يأتيه، إنه إذا مات انقطع عمله، وإنه لا يزيد المؤمن عمره إلا خيراً".', 'Messenger of Allah (ﷺ) said, "None of you should wish for death. If he is righteous, perhaps he may add to (his) good works, and if he is a sinner, possibly he may repent (in case he is given a longer life)."

.

In Muslim, Abu Hurairah (May Allah be pleased with him) reported : Messenger of Allah (ﷺ) said, "Let none of you wish for death, nor he ask for it before it comes to him, because when he dies, his actions will be terminated; certainly the age of a (true) believer does not add but good."', 'أبي هريرة رضي الله عنه', 'Abu Hurairah (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 584', 'Riyad as-Salihin 584', 'ریاض الصالحین 584', null, 'قوله عليه الصلاة والسلام: "لا يتمن أحدكم الموت"، والنهي هنا للتحريم؛ لأن تمني الموت فيه شيء من عدم الرضا بقضاء الله، والمؤمن يجب عليه الصبر إذا أصابته الضراء، فإذا صبر على الضراء نال شيئين مهمين: الأول: تكفير الخطايا فإن الإنسان لا يصيبه هم ولا غم ولا أذى ولا شيء إلا كفر الله به عنه حتى الشوكة يشاكها فإنه يكفر بها عنه. الثاني: إذا وفق لاحتساب الأجر من الله وصبر يبتغي بذلك وجه الله فإنه يثاب، أما كونه يتمنى الموت فهذا يدل على أنه غير صابر على ما قضى الله عز وجل ولا راض به، وبين الرسول عليه الصلاة والسلام أنه إما أن يكون من المحسنين فيزداد في بقاء حياته عملاً صالحاً، فالمؤمن إذا بقي ولو على أذى ولو على ضرر فإنه ربما تزداد حسناته.
وإما مسيئاً قد عمل سيئاً فلعله يستعتب أي يطلب من الله العتبى أي الرضا والعذر، فيموت وقد تاب من سيئاته فلا تتمن الموت؛ لأن الأمر كله مقضي، فيصبر ويحتسب، فإن دوام الحال من المحال. 
وفيه إشارة إلى أن المعنى في النهي عن تمني الموت والدعاء به هو انقطاع العمل بالموت، فإن الحياة يتسبب منها العمل، والعمل يحصل زيادة الثواب ولو لم يكن إلا استمرار التوحيد فهو أفضل الأعمال، ولا يرد على هذا أنه يجوز أن يقع الارتداد والعياذ بالله تعالى عن الإيمان؛ لأن ذلك نادر، والإيمان بعد أن تخالط بشاشته القلوب لا يسخطه أحد، وعلى تقدير وقوع ذلك وقد وقع لكن نادراً، فمن سبق له في علم الله خاتمة السوء، فلا بد من وقوعها طال عمره أو قصر، فتعجيله بطلب الموت لا خير له فيه.
وفي الحديث إشارة إلى تغبيط المحسن بإحسانه، وتحذير المسيء من إساءته، فكأنه يقول من كان محسناً فليترك تمني الموت وليستمر على إحسانه، والازدياد منه، ومن كان مسيئاً فليترك تمني الموت وليقلع عن الإساءة لئلا يموت على إساءته، فيكون على خطر.', 'بعد الموت ينقطع العمل، ويبدأ الإنسان جني ثمار عمله وتحصيله في الدنيا.
ينبغي على المرء أن يستغل جميع حياته في طاعة الله والازدياد منها، ومراجعة نفسه والتوبة مما بدر منه من المعاصي والآثام.
النهي عن تمني الموت لضر أصابه من مرض أو فقر أو نحو ذلك.', 'لا يتمن : النهي عن تمني الموت.
محسناً : مطيعاً لله.
يستعتب : يرجع إلى الله تعالى بالتوبة ورد المظالم، وطلب عتبى الله أي: رضاه.', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/5652', false),
(20585, 2, 201, 585, 'hadith', 'عن أنس رضي الله عنه قال: قال رسول الله صلى الله عليه وسلم: «لا يتمنين أحدكم الموت لضر أصابه فإن كان لابد فاعلاً، فليقل: اللهم أحينى ما كانت الحياة خيراً لى، وتوفنى إذا كانت الوفاة خيراً لى».', 'Messenger of Allah (ﷺ) said, "Let none of you wish for death on account of an affliction that befalls him. If he has no alternative, let him pray: ''Allahumma ahyine ma kanatil-hayatu khairan li, wa tawaffani idha kanatil-wafatu khairan li (O Allah! Give my life so long as the life is good for me, and take away my life if death is good for me)''.".', 'أنس رضي الله عنه', 'Anas bin Malik (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 585', 'Riyad as-Salihin 585', 'ریاض الصالحین 585', 'متفق عليه', null, null, null, 'sunnah.com', null, false, null, false),
(20586, 2, 201, 586, 'hadith', 'عن قيس بن أبي حازم قال: دخلنا على خباب بن الأرت رضي الله عنه نعوده وقد اكتوى سبع كيات فقال: إن أصحابنا الذين سلفوا مضوا، ولم تنقصهم الدنيا، وإنا أصبنا ما لا نجد له موضعاً إلا التراب ولولا أن النبي صلى الله عليه وسلم نهاناً أن ندعوا بالموت لدعوت به، ثم أتيناه مرة أخرى وهو يبنى حائطاً له فقال: إن المسلم ليؤجر فى كل شئ ينفقه إلا فى شئ يجعله فى هذا التراب.', 'I went to visit Khabbab bin Aratt (May Allah be pleased with him) during his illness. He had been cauterized in seven places. He said: "Our companions who have died have left (this world) without having enjoyed the pleasures of the world (in order to get a great full reward in the Hereafter) while we have amassed wealth exceeding our needs for which there is no place to keep except in the earth. Had Messenger of Allah (ﷺ) not prohibited us from longing for death, I would have prayed for it." Then we visited him again and he was building a wall. He said: "There is a reward in store for a Muslim in respect of everything on which he spends except for something he places in the earth (i.e., something exceeding our needs or essentials).".', 'قيس بن أبي حازم قال: دخلنا على خباب بن الأرت رضي الله عنه', 'Qais bin Abu Hazim (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 586', 'Riyad as-Salihin 586', 'ریاض الصالحین 586', 'متفق عليه وهذا لفظ رواية البخاري', 'في الحديث أن خباب بن الأرت رضي الله عنه كُوِي سبع كيات ثم جاءه أصحابه يعودونه فأخبرهم أن الصحابة الذين سبقوا ماتوا ولم يتمتعوا بشيء من ملذات الدنيا، فيكون ذلك منقصاً لهم مما أُعدَ لهم في الآخرة. وإنه أصاب مالاً كثيرا ًلا يجد له مكانًا يحفظه فيه إلا أن يبني به، وقال: ولولا أن رسول الله نهانا أن ندعو بالموت لدعوت به، إلا عند الفتن في الدين فيدعو بما ورد. ثم قال: إن الإنسان يؤجر على كل شيء أنفقه إلا في شيء يجعله في التراب يعني: في البناء؛ لأن البناء إذا اقتصر الإنسان على ما يكفيه، فإنه لا يحتاج إلى كبير نفقة، ، فهذا المال الذي يجعل في البناء الزائد عن الحاجة لا يؤجر الإنسان عليه، اللهم إلا بناء يجعله للفقراء يسكنونه أو يجعل غلته في سبيل الله أو ما أشبه ذلك، فهذا يؤجر عليه، لكن بناء يسكنه، هذا ليس فيه أجر.
والنهي الذي جاء عن الكي هو لمن يعتقد أن الشفاء من الكي، أما من اعتقد أن الله عز وجل هو الشافي فلا بأس به، أو ذلك للقادر على مداواة أخرى وقد استعجل ولم يجعله آخر الدواء.', 'فضل خباب بن الأرت، ومزيد عرفانه بمولاه، وشدة اتهامه لنفسه، ومحاسبته لها حتى في المباحات.
النهي عن تمني الموت.
كراهية الزيادة في البناء من غير حاجة.
الحث على عيادة المريض.
جواز الاكتواء عند الحاجة، هذا ما دل عليه الحديث، ولكن ذلك مع الكراهة وألا يبدأ به بدلالة النصوص الأخرى.', 'سلفوا : تقدموا وسبقوا.
مضوا : ماتوا.
ولم تنقصهم الدنيا : لم يتمتعوا بشيء من ملذات الدنيا، فيكون ذلك منقصاً لهم مما أُعدَ لهم في الآخرة.
لا نجد له موضعاً إلا التراب : أي جمعنا مالاً زائداً عن الحاجة لا نجد له مكاناً نحفظه فيه إلا التراب ندفنه مخافة السرقة، أو أنه أراد البناء الزائد عن الحاجة.
اكتوى : استعمل الكَيّ في بدنه. والكي: معروف إحراق مواضع من البدن بحديدة ونحوها للعلاج.', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/6011', false),
(20587, 2, 201, 587, 'hadith', 'عن النعمان بن بشير رضي الله عنهما قال: سمعت رسول الله صلى الله عليه وسلم يقول: «إن الحلال بين، وإن الحرام بين، وبينهما مشتبهات لا يعلمهن كثير من الناس، فمن اتقى الشبهات، استبرأ لدينه وعرضه، ومن وقع فى الشبهات، وقع فى الحرام، كالراعى يرعى حول الحمى يوشك أن يرتع فيه ألا وإن لكل ملك حمى، ألا وإن حمى الله محارمه، ألا وإن فى الجسد مضغة إذا صلحت صلح الجسد كله، وإذا فسدت فسد الجسد كله: ألا وهى القلب».', 'Messenger of Allah (ﷺ) said, "What is lawful is clear and what is unlawful is clear, but between them are certain doubtful things which many people do not know. So he who guards against doubtful things keeps his religion and his honour blameless. But he who falls into doubtful things falls into that which is unlawful, just as a shepherd who grazes his cattle in the vicinity of a pasture declared prohibited (by the king); he is likely to stray into the pasture. Mind you, every king has a protected pasture and Allah''s involved limits is that which He has declared unlawful. Verily, there is a piece of flesh in the body, if it is healthy, the whole body is healthy, and if it is corrupt, the whole body is corrupt. Verily, it is the heart.".', 'النعمان بن بشير رضي الله عنهما', 'An-Nu''man bin Bashir (May Allah be pleased with them)', 'صحيح', 'رياض الصالحين 587', 'Riyad as-Salihin 587', 'ریاض الصالحین 587', 'متفق عليه. وروياه من طرق بألفاظ متقاربة', 'يُبَيِّنُ النبيُّ صلى الله عليه وسلم قاعدةً عامةً في الأشياء، وأنها تنقسم في الشريعة إلى ثلاثة أقسام: حَلال بَيِّن، وحرام بَيِّن، وأمور مشتبهات غير واضحة الحكم من حيث الحِلِّ والحُرْمة، لا يعلم حُكمَها كثير من الناس.
فمَن ترك تلك الأشياء المشتبهة عليه سَلِم دينُه بالبُعد عن الوقوع في الحرام، وسَلِم له عِرضُه من كلام الناس بما يَعيبون عليه بسبب ارتكابه هذا المشتبه. ومَن لم يجتنب المشتبهات فقد عَرَّض نفسَه إما بالوقوع في الحرام، أو نيل الناس من عرضه. وضرب الرسول صلى الله عليه وسلم مثلًا ليُبيِّن حال من يرتكب الشبهات وأنه كالراعي يرعى ماشيتَه قُرْبَ أرضٍ قد حماها صاحبها، فتوشك ماشيةُ الراعي أن ترعى في هذا الحمى لقربها منه، فكذلك من يفعل ما فيه شبهة، فإنه بذلك يقترب من الحرام فيوشك أن يقع فيه. وبعدها أخبر النبي صلى الله عليه وسلم أن في الجسد مضغة (وهي القلب) يصلح الجسد بصلاحها، ويفسد بفسادها.', 'الحديث قاعدة في اتقاء الشبهات.
الترغيب في ترك المشتبِه، الذي لم يَتبيّن حكمُه.', null, 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/66515', false),
(20588, 2, 201, 588, 'hadith', 'عن أنس رضي الله عنه أن النبي صلى الله عليه وسلم، وجد تمرة فىالطريق فقال: «لولا أنى أخاف أن تكون من الصدقة لأكلتها».', 'The Prophet (ﷺ) found a dry date-fruit lying in the way and said, "Had it not been for fear of being from charity I would have eaten it.".', 'أنس رضي الله عنه', 'Anas bin Malik (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 588', 'Riyad as-Salihin 588', 'ریاض الصالحین 588', 'متفق عليه', null, null, null, 'sunnah.com', null, false, null, false),
(20589, 2, 201, 589, 'hadith', 'عن النواس بن سمعان رضي الله عنه عن النبي صلى الله عليه وسلم قال: البر حسن الخلق، والإثم ما حاك فى نفسك، وكرهت أن يطلع عليه الناس".', 'The Prophet (ﷺ) said, "Piety is good manner, and sin is that which creates doubt and you do not like people to know of it.".', 'النواس بن سمعان رضي الله عنه', 'An-Nawwas bin Sam''an (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 589', 'Riyad as-Salihin 589', 'ریاض الصالحین 589', 'رواه مسلم', 'أخبر النبي صلى الله عليه وسلم عن البر والإثم، فقال: إن أعظم خصال البر حسن الخُلُق مع الله بالتقوى، ومع الخَلْق باحتمال الأذى، وقلة الغضب، وبسط الوجه، وطيب الكلام، والصلة والطاعة واللطف والمبرة وحسن العشرة والصحبة. وأن البر ما سكن إليه القلب والنفس.
وأما الإثم فما تحرك في النفس من المشتبهات وتردد دون أن ينشرح الصدر له، وحصل في القلب منه الشك، والخوف من كونه ذنبًا، ولم تُرد أن تظهره لكونه قبيحًا لأعيان وأماثل الناس وكُمَّلِهم، وذلك لأن النفس بطبعها تحب اطلاع الناس على خيرها، فإذا كَرِهَت الاطلاع على بعض أفعالها فهو إثم لا خير فيه؛ وإن أفتاك الناس فلا تأخذ بفتواهم ما دامت علامة الشبهة تتردد في نفسك  فإن الفتوى لا تزيل الشبهة ما دامت الشبهة صحيحة وكان المفتي يفتي بغير علم؛ أما إذا كانت الفتوى بناء على دليل شرعي فالواجب على المستفتي الرُّجوعُ إليه، وإنْ لم ينشرح له صدرُه.', 'الحثُّ على مكارم الأخلاق؛ لأنّ حسن الخلق من أعظم خصال البر.
الحق والباطل لا يلتبس أمرُهما على المؤمن، بل يعرف الحق بالنور الذي في قلبه، وينفر عن الباطل فينكره.
من علامات الإثم قلق القلب واضطرابه، وكراهة اطلاع الناس عليه.
قال السندي: هذا في المشتبهات من الأمور التي لا يعلم الناس فيها بتعيين أحد الطرفين؛ وإلا فالمأمور به في الشرع من غير ظهور دليل فيه على خلاف ذلك من البر، والمنهي عنه كذلك من الإثم، ولا حاجة فيهما إلى استفتاء القلب وطمأنينته.
المخاطَب في الحديث أصحاب الفطرة السليمة، لا أصحاب القلوب المنكوسة التي لا تعرف معروفًا ولا تنكر منكرًا إلا ما أُشرِبتْ من هواها.
قال الطيبي: قيل فُسِّرَ البر في الحديث بمعان شتى، ففسَّره في موضع بما اطمأنت إليه النفس واطمأن إليه القلب، وفسره في موضع بالإيمان، وفي موضع بما يقربك إلى الله، وهنا بحسن الخلق، وفسر حسن الخلق: باحتمال الأذى وقلة الغضب وبسط الوجه وطيب الكلام، وكلها متقاربة في المعنى.', null, 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/66540', false),
(20590, 2, 201, 590, 'hadith', 'عن وابصة بن معبد رضي الله عنه قال: أتيت رسول الله صلى الله عليه وسلم فقال: "جئت تسأل عن البر؟" قلت نعم، فقال: "استفت قلبك البر ما اطمأنت إليه النفس، واطمأن إليه القلب، والإثم ما حاك فى النفس وتردد فىالصدر، وإن أفتاك الناس وأفتوك".', 'I went to Messenger of Allah (ﷺ) and he asked me, "Have you come to inquire about piety?" I replied in the affirmative. Then he said, "Ask your heart regarding it. Piety is that which contents the soul and comforts the heart, and sin is that which causes doubts and perturbs the heart, even if people pronounce it lawful and give you verdicts on such matters again and again.".', 'وابصة بن معبد رضي الله عنه', 'Wabisah bin Ma''bad (May Allah be pleased with him)', 'حسن', 'رياض الصالحين 590', 'Riyad as-Salihin 590', 'ریاض الصالحین 590', 'حديث حسن، رواه أحمد والدارمي فى مسنديهما', null, null, null, 'sunnah.com', null, false, null, false),
(20591, 2, 201, 591, 'hadith', 'عن أبي سروعة -كسر السين المهملة ونصبها- عقبة بن الحارث رضي الله عنه أنه تزوج ابنة لأبي إهاب بن عزيز، فأتته امرأة فقالت: إنى قد أرضعت عقبة والتى قد تزوج بها، فقال لها عقبة: ما أعلم أنك أرضعتني ولا أخبرتني فركب إلى رسول الله صلى الله عليه وسلم بالمدينة فسأله فقال رسول الله صلى الله عليه وسلم: "كيف، وقد قيل؟!" ففارقها عقبة ونكحت زوجاً غيره".', '"I am not aware that you suckled me, and you did not inform me." So he (''Uqbah) rode to Messenger of Allah (ﷺ) in Al-Madinah and put the matter before him. The Messenger of Allah (ﷺ) said, "How can you continue (to be her husband) after what you have been told?" ''Uqbah (May Allah be pleased with him) therefore divorced her and she married another man..', 'أبي سروعة -كسر السين المهملة ونصبها- عقبة بن الحارث رضي الله عنه', '''Uqbah bin Al-Harith (May Allah be pleased with him) reported that he had married a daughter of Abu Ihab bin ''Aziz and a woman came to him and said she had suckled both ''Uqbah and the woman whom he had married, to which he replied:', 'صحيح', 'رياض الصالحين 591', 'Riyad as-Salihin 591', 'ریاض الصالحین 591', 'رواه البخاري', null, null, null, 'sunnah.com', null, false, null, false),
(20592, 2, 201, 592, 'hadith', 'عن الحسن بن على رضي الله عنهما، قال: حفظت من رسول الله صلى الله عليه وسلم: «دع ما يريبك إلى ما لا يريبك».', 'I have retained these words of Messenger of Allah (ﷺ), "Leave what causes you doubt and turn to what does not cause you doubt.".', 'الحسن بن على رضي الله عنهما', 'Hasan bin ''Ali (May Allah be pleased with them)', 'صحيح', 'رياض الصالحين 592', 'Riyad as-Salihin 592', 'ریاض الصالحین 592', 'رواه الترمذى وقال: حديث حسن صحيح', null, null, null, 'sunnah.com', null, false, null, false),
(20593, 2, 201, 593, 'hadith', 'عن عائشة رضي الله عنها، قالت: كان لأبي بكر الصديق رضي الله عنه غلام يخرج له الخراج وكان أبو بكر يأكل من خراجه فجاء يوماً بشئ، فأكل منه أبو بكر، فقال له الغلام: تدرى ما هذا؟ فقال أبو بكر: ما هو؟ قال: كنت تكهنت لإنسان فى الجاهلية وما أحسن الكهانة إلا أني خدعته فلقيني، فأعطاني بذلك هذا الذى أكلت منه، فأدخل أبو بكر يده فقاء كل شئ فى بطنه".', 'Abu Bakr (May Allah be pleased with him) had a slave who brought him his earnings and Abu Bakr (May Allah be pleased with him) would eat from it. One day he brought him something and when Abu Bakr (May Allah be pleased with him) had eaten some of it, the slave asked him whether he knew where he had got that (food) from, Abu Bakr (May Allah be pleased with him) asked what it was, and he replied: I acted as a soothsayer for a man in the pre-Islamic period, and not being good at it, I deceived him; today he met me and he rewarded me for that soothsaying what you have eaten. Abu Bakr (May Allah be pleased with him) put his hand in his mouth and vomited up all that he had eaten..', 'عائشة رضي الله عنها', '''Aishah (May Allah be pleased with her)', 'صحيح', 'رياض الصالحين 593', 'Riyad as-Salihin 593', 'ریاض الصالحین 593', 'رواه البخاري', 'هذا الغلام لأبي بكر قد خارجه على شيء معين يأتي به إليه كل يوم، وفي يوم من الأيام قدم هذا الغلام طعاماً لأبي بكر فأكله فقال: أتدري ما هذا ؟ قال: وما هو ؟ قال: هذا عوض عن أجرة كهانة تكهنت بها في الجاهلية وأنا لا أحسن الكهانة، لكني خدعت الرجل فلقيني فأعطاني إياها، وعوض الكهانة حرام، سواء كان الكاهن يحسن صنعة الكهانة أو لا يحسن لأن النبي -عليه الصلاة والسلام-: نهى عن حلوان الكاهن، أخرجه البخاري ومسلم.
فلما قال لأبي بكر هذه المقالة أدخل أبو بكر يده في فمه فقاء كل ما أكل وأخرجه من بطنه لئلا يتغذى بطنه بحرام وهذا مال حرام لأنه عوض عن حرام، فالأجرة على فعل الحرام حرام.', 'ورع أبي بكر الصديق –رضي الله عنه- وحرصه عدم دخول جوفه شيئاً محرماً، ولو لم يستفرغه لكان معذوراً لأن الإثم على الغلام ولأنه لم يكن يعلم.
جواز الأكل من خراج الغلام.
أبو بكر الصديق –رضي الله عنه- أول من قاء من الشبهات تحرجاً.', 'يخرج له : يأتيه بما يكسبه من الخراج، والخراج: هو شيء يجعله السيد على عبده يؤديه كل يوم، وباقي كسبه يكون للعبد.
تكهنت : أخبرت بالغيب؛ ادعاء معرفته.
فقاء : أي استفرغ كل ما أكل منه.', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/6187', false),
(20594, 2, 201, 594, 'hadith', 'عن نافع أن عمر بن الخطاب رضي الله عنه كان فرض للمهاجرين الأولين أربعة آلاف وفرض لابنه ثلاثة آلاف وخمسمائة، فقيل له: هو من المهاجرين فلم نقصته؟ فقال: إنما هاجر به أبوه، يقول: ليس هو كمن هاجر بنفسه".', '''Umar bin Al-Khattab (May Allah be pleased with him) fixed the payment amounting to four thousand dirhams for each of the early Emigrants, but for his son, he fixed only three thousand five hundred. He was asked: "He is also an (early) Emigrant, why have you fixed a lesser sum for him?" He said: "It was his father who took him along with him. He is not like one who emigrated by himself.".', 'نافع أن عمر بن الخطاب رضي الله عنه', 'Nafi'' (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 594', 'Riyad as-Salihin 594', 'ریاض الصالحین 594', 'رواه البخاري', 'أعطى عمر للمهاجرين 4000، وابنه من المهاجرين لكنه أعطاه 3500، لأنه هاجر به أبوه وهو غير محتلم فلم ير إلحاقه بالبالغين، فلذا أنقص من عطائه عمن هاجر بنفسه من المهاجرين، فإن الدنيا لم تعرف بعد النبي –صلى الله عليه وسلم- وأبي بكر الصديق حاكماً زاهداً ورعاً في مال الأمة مثله –رضي الله عنه-، وهكذا يجب على من تولى شيئا من أمور المسلمين ألا يحابي قريبا لقرابته، ولا غنيا لغناه ولا فقيرا لفقره بل ينزل كل أحد منزلته، فهذا من الورع والعدل.', 'شدة ورع عمر بن الخطاب –رضي الله عنه-.
فضل المهاجرين الأولين الذين خرجوا بأنفسهم فراراً بدينهم يريدون وجه الله.
للإمام أن يفرض لبعض أهل الإيمان فرضاً ليعينهم على الحياة، من التفرغ للدعوة والعلم ونحو ذلك.', 'فرض : أوجب وقطع من العطاء.
المهاجرون الأولون : هم الذين صلوا للقبلتين أو شهدوا بدراً.', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/5654', false),
(20595, 2, 201, 595, 'hadith', 'عن عطية بن عروة السعدى الصحابي رضي الله عنه قال: قال رسول الله صلى الله عليه وسلم: «لا يبلغ العبد أن يكون من المتقين حتى يدع مالا بأس به حذرا لما به بأس».', 'Messenger of Allah (ﷺ) said, "No one will attain complete righteousness until he abandons (certain) unobjectionable (but doubtful) things so as to remain on his guard against something objectionable.".', 'عطية بن عروة السعدى الصحابي رضي الله عنه', '''Atiyyah bin ''Urwah As-Sa''di (May Allah be pleased with him)', 'حسن', 'رياض الصالحين 595', 'Riyad as-Salihin 595', 'ریاض الصالحین 595', 'رواه الترمذى وقال: حديث حسن', null, null, null, 'sunnah.com', null, false, null, false),
(20596, 2, 201, 596, 'hadith', 'عن سعد بن أبي وقاص رضي الله عنه قال: سمعت رسول الله صلى الله عليه وسلم: يقول: "إن الله يحب العبد التقي الغني الخفي" ((رواه مسلم)). والمراد: بـ "الغني" غني النفس، كما سبق فى الحديث الصحيح.', 'Messenger of Allah (ﷺ) said, "Allah loves a slave who is pious, free of all wants and the unnoticed.".', 'سعد بن أبي وقاص رضي الله عنه', 'Sa''d bin Abu Waqqas (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 596', 'Riyad as-Salihin 596', 'ریاض الصالحین 596', null, 'بَيَّنَ النبيُّ صلى الله عليه وسلم أنَّ الله عزَّ وجلَّ يُحِبُّ بعضَ عباده، 

ومنهم التقي: المُمْتَثِل لأوامر الله، المجتنب لنواهِيهِ.

ويُحِبُّ الغنيَّ: الذي استغنى عن الناسِ بالله عز وجل لا يَلْتَفِتُ إلى غيره.

ويُحبُّ الخفيَّ: المُتَواضِع، المُتَعَبِّد لربِّه، المُشتغل بما ينفعه، الذي لا يَهْتَمُّ أنْ يَعْرِفَه أحدٌ أو يَتَحَدَّث عنه بمدحٍ وثَنَاءٍ.', 'بيان بعض الصفات المُقْتَضِيَة لمحبةِ الله لعباده، وهي التقوى والتواضع والرضى بما قَسَمَ الله.', null, 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/5545', false),
(20597, 2, 201, 597, 'hadith', 'عن أبي سعيد الخدرى رضي الله عنه قال: قال رجل: أى الناس أفضل يا رسول الله؟ قال: "مؤمن مجاهد بنفسه وماله فى سبيل الله" قال: ثم من؟ قال: " رجل معتزل فى شعب من الشعاب يعبد ربه" وفى رواية: "يتقي الله، ويدع الناس من شره".', 'Someone asked Messenger of Allah (ﷺ): "Who is the best man?" He (ﷺ) answered, "A believer who strives in the Cause of Allah with his life and his wealth." The man asked: "Who is the next?" He said, "One who retires into a narrow valley and worships his Rubb."Another narration is: Messenger of Allah (ﷺ) said, "One who fears Allah and safeguards people against his own mischief.".', 'أبي سعيد الخدرى رضي الله عنه', 'Abu Sa''id Al-Khudri (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 597', 'Riyad as-Salihin 597', 'ریاض الصالحین 597', 'متفق عليه', 'سئل النبي صلى الله عليه وسلم أي الرجال خير؟ فبين أنه الرجل الذي يجاهد في سبيل الله بماله ونفسه، قيل: ثم أي؟ قال: ورجل مؤمن في شعب من الشعاب يعبد الله ويدع الناس من شره. يعني: أنه قائم بعبادة الله كاف عن الناس ولا يريد أن ينال الناس منه شر.', 'استحباب السؤال عما يحتاج إليه الإنسان من أمور الدين.
مخالطة الناس عند فسادهم مدعاة لارتكاب الآثام.
بيان فضل الجهاد في سبيل الله بالنفس والمال.
فضل العزلة عند خوف الفتنة.', 'شِعْب : الطريق في الجبل، وما انفرج بين الجبلين.', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/5773', false),
(20598, 2, 201, 598, 'hadith', 'وعنه قال: قال رسول الله صلى الله عليه وسلم: «يوشك أن يكون خير مال المسلم غنم يتتبع بها شعف الجبال، ومواقع القطر، يفر بدينه من الفتن» ((رواه البخاري)). وشعف الجبال :أعلاها', 'Messenger of Allah (ﷺ) said, "The best possession of a Muslim will be a herd of sheep with which he retires to the top of a mountain or places where rain is expected to fall (pastures) so as to safeguard with his faith from tribulation.".', null, 'Abu Sa''id Al-Khudri (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 598', 'Riyad as-Salihin 598', 'ریاض الصالحین 598', null, 'في الحديث فضل العزلة في أيام الفتن إلا أن يكون الإنسان ممن له قدرة على إزالة الفتنة، فإنه يجب عليه السعي في إزالتها إما فرض عين وإما فرض كفاية بحسب الحال والإمكان، وأما في غير أيام الفتنة فاختلف العلماء في العزلة والاختلاط أيهما أفضل؟، والمختار: تفضيل الخلطة لمن لا يغلب على ظنه الوقوع في المعاصي.
"يفر بدينه من الفتن" يعني: يهرب خشية على دينه من الوقوع في الفتن، ولهذا أمر الإنسان أن يهاجر من بلد الشرك إلى بلد الإسلام، ومن بلد الفسوق إلى بلد الاستقامة، فكذلك إذا تغير الناس والزمان.', 'فضيلة العزلة لمن خاف على دينه.
الحديث من دلائل النبوة، فقد وقع ما أخبر به النبي –صلى الله عليه وسلم-، فلا يكاد المسلم ينجو بنفسه في الليل أو النهار.
الفرار من الفتن سبيل المؤمنين الخُلّص؛ لأنه صيانة للدين.
من خير مال المسلم غنم يرعاها في العشب المباح، حيث يكسب منها قوتاً طيباً.', 'يوشك : يقرب.
شعف الجبال : أعلاها.
مواقع القطر : مواضع العشب التي ينزل فيها المطر.
الفتن : ما ينال الإنسان من البلاء والاختبار.', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/6829', false),
(20599, 2, 201, 599, 'hadith', 'عن أبي هريرة رضي الله عنه عن النبي صلى الله عليه وسلم قال: "ما بعث الله نبياً إلا رعى الغنم" فقال أصحابه: أنت؟ قال: كنت أرعاها على قراريط لأهل مكة".', 'Messenger of Allah (ﷺ) said, "Every Prophet has tended sheep". He was asked: "And did you?" He replied, "Yes, I tended them for a few carats for the Makkans.".', 'أبي هريرة رضي الله عنه', 'Abu Hurairah (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 599', 'Riyad as-Salihin 599', 'ریاض الصالحین 599', 'رواه البخاري', 'كل الأنبياء رعوا الغنم في حياتهم، وظاهر الحديث أن ذلك قبل النبوة، لذلك قال العلماء: الحكمة من ذلك أن يتمرن الإنسان على رعاية الخلق وتوجيههم إلى ما فيه الصلاح؛ لأن الراعي للغنم تارة يوجهها للمرعى وتارة يبقيها واقفة وتارة يردها إلى المراح، فالنبي -عليه الصلاة والسلام- سيرعى الأمة ويوجهها إلى الخير عن علم وهدى وبصيرة كالراعي الذي عنده علم بالمراعي الحسنة، وعنده نصح وتوجيه للغنم إلى ما فيه خيرها، وما فيه غذاؤها وسقاؤها.
واختيرت الغنم لأن صاحب الغنم متصف بالسكينة والهدوء والاطمئنان بخلاف الإبل، فإن أصحابها في الغالب عندهم شدة وغلظة، لأن الإبل كذلك فيها الشدة والغلظة، فلهذا اختار الله سبحانه وتعالى لرسله أن يرعوا الغنم حتى يتعودوا ويتمرنوا على رعاية الخلق.', 'تواضع الأنبياء -عليهم الصلاة والسلام- باشتغالهم بأبسط الحِرَف.
يستحب للعبد أن يتكسب ويطلب الرزق وإن قل، ففيه البركة لمن قنع، ويجب أن يتحرى في ذلك أن يكون حلالًا.
الحكمة من رعي الأنبياء الغنم؛ ليتمرنوا بذلك على سياسة الأمم.', 'قراريط : جمع قيراط، وهو جزء من الدينار أو الدرهم.', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/6219', false),
(20600, 2, 201, 600, 'hadith', 'وعنه عن رسول الله صلى الله عليه وسلم أنه قال: «من خير معاش الناس رجل ممسك عنان فرسه فى سبيل الله، يطير على متنه، كلما سمع هيعه أو فزعة، طار عليه يبتغى القتل، أو الموت مظانه، أو رجل فى غنيمة فى رأس شعفة من هذه الشعف، أو بطن واد من هذه الأودية يقيم الصلاة، ويؤتى الزكاة، ويعبد ربه حتى يأتيه اليقين، ليس من الناس إلا فى خير».', 'Messenger of Allah (ﷺ) said, "The best of people is a man who is holding his horse''s rein in the way of Allah (in Jihad) and is galloping towards the place wherever he hears a call for war or detects a note of danger; he goes on proceeding, seeking martyrdom or death wherever it is expected. And a man who retires with some sheep in a mountainside or a valley. He performs Salat regularly and pays the Zakat, continues worshipping his Rubb, till death overtakes him. He does not interfere in the affairs of the people except for betterment.".', null, 'Abu Hurairah (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 600', 'Riyad as-Salihin 600', 'ریاض الصالحین 600', 'رواه مسلم', 'في الحديث بيان أن من خير أحوال عيش الناس رجل ممسك عنان فرسه، وقوله -صلى الله عليه و سلم-: "يطير على متنه كلما سمع هيعة أو فزعة طار على متنه يبتغي القتل والموت مظانه"، معناه :يسارع على ظهره وهو متنه، كلما سمع هيعة وهى الصوت عند حضور العدو، والفزعة وهي النهوض إلى العدو، يبتغي القتل مظانه يطلبه في مواطنه التي يرجى فيها؛ لشدة رغبته في الشهادة.
وفيه أيضاً دليل على أن العزلة خير ومن كان في مكان من الأودية والشعاب منعزلاً عن الناس، يعبد الله عز وجل ليس من الناس إلا في خير فهذا فيه خير.', 'فضل الجهاد والاستعداد له وترقبه، وتحديث النفس به طلباً للشهادة في سبيل الله -تعالى-.
فضيلة اعتزال الناس عند وقوع الفتنة.
من خالط الناس ينبغي أن يسلم المسلمون من لسانه ويده.
جواز التكسب الحلال برعي الأغنام بعيداً عن الناس.
العزلة بسبب الفتن، ينبغي أن لا تحول بين العبد والقيام بالأحكام الشرعية على وجهها.', 'عنان : سير اللجام الذي تمسك به الدابة.
يبتغي القتل : يطلبه من الكفار في الجهاد.
يطير : يسرع.
متنه : ظهره.
هيعة أو فزعة : الهيعة الصوت للحرب، والفزعة نحوه.
مظانه : المواضع التي يظن وجوده فيها.
غُنَيمة : تصغير الغنم، الشاة والماعز.
الشَّعَف : بفتح الشين والعين: أعلى الجبل.
ليس من الناس إلا في خير : لا يخالط الناس إلا في خير.
اليقين : الموت.', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/6266', false)
