insert into hadith (id, collection_id, chapter_id, number_in_book, kind, arabic, translation_en, narrator_ar, narrator_en, grade_ar, reference_ar, reference_en, reference_ur, full_ref_ar, explanation_ar, benefits_ar, word_meanings_ar, source, source_ref, daily_ok, review_note, deleted) values
(20601, 2, 201, 601, 'hadith', 'عن عياض بن حمار رضي الله عنه قال: قال رسول الله صلى الله عليه وسلم: «إن الله أوحى إلي أن تواضعوا حتى لا يفخر أحد على أحد، ولا يبغي أحد على أحد».', 'Messenger of Allah (ﷺ) said, "Allah has revealed to me that you should humble yourselves to one another. One should neither hold himself above another nor transgress against another.".', 'عياض بن حمار رضي الله عنه', '''Iyad bin Himar (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 601', 'Riyad as-Salihin 601', 'ریاض الصالحین 601', 'رواه مسلم', 'قام النبي صلى الله عليه وسلم في أصحابه خطيبًا، وكان مما قال: 

إن الله أوحى إليه أنه يجب على الناس أن يتواضعوا فيما بينهم، وذلك بخفض الجناح للخلق ولين الجانب، حتى لا يفخر بادعاء العظمة والكبرياء والشرف أحدٌ بنسبه أو ماله أو غير ذلك على أحد، ولا يظلم ولا يعتدي أحدٌ على أحد.', 'في الحديث الحث على التواضع وعدم الكبر والترفع على الناس.
النهي عن البغي والفخر.
التواضع لله له معنيان: المعنى الأول: أن تتواضع لدِينِ الله، فلا تترفع عن الدِّين، ولا تستكبر عنه وعن أداء أحكامه، والثاني: أن تتواضع لعباد الله من أجل الله، لا خوفًا منهم، ولا رجاءً لما عندهم، ولكن لله عزَّ وجلَّ.', null, 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/5497', false),
(20602, 2, 201, 602, 'hadith', 'عن أبي هريرة رضي الله عنه أن رسول الله صلى الله عليه وسلم قال: «ما نقصت صدقة من مال، و ما زادالله عبداً بعفو إلا عزاً، وما تواضع أحد لله إلا رفعه الله».', 'Messenger of Allah (ﷺ) said, "Wealth does not diminish by giving Sadaqah (charity). Allah augments the honour of one who forgives; and one who serves another seeking the pleasure of Allah, Allah will exalt him in ranks.".', 'أبي هريرة رضي الله عنه', 'Abu Hurairah (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 602', 'Riyad as-Salihin 602', 'ریاض الصالحین 602', 'رواه مسلم', 'يُبَيِّنُ النبيُّ صلى الله عليه وسلم أنَّ الصدقةَ لا تُنقِصُ المالَ، بل تَدْفَعُ عنه الآفات، ويُعَوِّض اللهُ صاحبَها الخيرَ العظيم، فتكون زيادةً لا نقصًا.

وما زاد العفوُ مع القدرة على الانتقام أو المؤاخذة صاحبَه إلا قوةً وعزةً.

وما تواضع وتَذَلَّل أحدٌ لوجه الله، لا خوفًا من أحد، ولا مداراة له، ولا طلبًا لمنفعة منه، إلا كان جزاؤه العُلُوَّ والشرفَ.', 'الخير والفلاح في امتثال الشريعة وفعل الخير وإن ظن بعض الناس أنه بخلاف ذلك.', '---', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/5512', false),
(20603, 2, 201, 603, 'hadith', 'عن أنس رضي الله عنه أنه مر على صبيان فسلم عليهم وقال: كان النبي صلى الله عليه وسلم يفعله.', 'The Prophet (ﷺ) used to do the same..', 'أنس رضي الله عنه', 'Anas (May Allah be pleased with him) passed by some children and greeted them (by saying As-salamu ''alaikum to them). Then he said:', 'صحيح', 'رياض الصالحين 603', 'Riyad as-Salihin 603', 'ریاض الصالحین 603', 'متفق عليه', 'في الحديث الندب إلى التواضع وبذل السلام للناس كلهم، وبيان تواضعه صلى الله عليه وسلم ، ومنه أنه كان يسلم على الصبيان إذا مر عليهم، واقتدى به أصحابه رضي الله عنهم فعن أنس رضي الله عنه أنه كان يمر بالصبيان فيسلم عليهم، يمر بهم في السوق يلعبون فيسلم عليهم ويقول: إن النبي صلى الله عليه وسلم كان يفعله، أي يسلم على الصبيان إذا مر عليهم، وهذا من التواضع وحسن الخلق ومن التربية وحسن التعليم والإرشاد والتوجيه، لأن الصبيان إذا سلم الإنسان عليهم، فإنهم يعتادون ذلك ويكون ذلك كالغريزة في نفوسهم.', 'استحباب السلام على الصغار، وتدريبهم على آداب الشريعة.
اجتناب الكبر، والتواضع ولين الجانب.
حرص الصحابة  على متابعة الرسول –صلى الله عليه وسلم-.', null, 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/5659', false),
(20604, 2, 201, 604, 'hadith', 'عنه قال: إن كانت الأمة من إماء المدينة لتأخذ بيد النبي صلى الله عليه وسلم، فتنطلق به حيث شاءت.', 'A slave-girl of Al-Madinah would take hold of the hand of the Prophet (ﷺ) and take him wherever she desired..', null, 'Anas bin Malik (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 604', 'Riyad as-Salihin 604', 'ریاض الصالحین 604', 'رواه البخاري', 'في الحديث تواضع الرسول -عليه الصلاة والسلام- وهو أشرف الخلق، حيث كانت الأمة المملوكة من إماء المدينة تأتي إليه، وتأخذ بيده، وتذهب به حيث شاءت ليعينها في حاجتها، هذا وهو أشرف الخلق، ولا يقول أين تذهبين بي، أو يقول: اذهبي إلى غيري، بل كان يذهب معها ويقضي حاجتها، لكن مع هذا ما زاده الله عز وجل بذلك إلا عزاً ورفعة -صلوات الله وسلامه عليه-.
تنبيه:
ليس المقصود بأخذ اليد أن تكون مست يده –صلى الله عليه وسلم- يد الأمة، قال الحافظ: والمقصود من الأخذ باليد لازمه وهو الرفق والانقياد، وقد اشتمل على أنواع من المبالغة في التواضع لذكره المرأة دون الرجل، والأمة دون الحرة، وحيث عمم بلفظ الإماء أي أمة كانت.', 'شدة تواضعه –صلى الله عليه وسلم- بوقوفه مع المرأة والأمة وكل من احتاجه.
بذل العون لكل محتاج، وقضاء حاجات الناس، قرب مكانه أو بعد.
بروز النبي –صلى الله عليه وسلم- للناس وقربه منهم، حتى يأخذ كل أحدٍ ما يريد، ويُقتدى به في كل شيء.
عدم كسر نفس الصغير أو نهر السائل والفقير، والاستجابة لطلبه ما لم يكن إثماً.
حرصه –صلى الله عليه وسلم- على قضاء حاجات الناس.', 'الأمة : المرأة المملوكة خلاف الحرة.', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/5655', false),
(20605, 2, 201, 605, 'hadith', 'عن الأسود بن يزيد قال: سئلت عائشة رضي الله عنها: ما كان النبي صلى الله عليه وسلم يصنع فى بيته؟ قالت: كان يكون فى مهنة أهله -يعنى: خدمة أهله- فإذا حضرت الصلاة، خرج إلى الصلاة".', '''Aishah (May Allah be pleased with her) was asked: "What did Messenger of Allah (ﷺ) used to do inside his house?" She answered: "He used to keep himself busy helping members of his family, and when it was the time for Salat (the prayer), he would get up for prayer.".', 'الأسود بن يزيد قال: سئلت عائشة رضي الله عنها', 'Al-Aswad bin Yazid (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 605', 'Riyad as-Salihin 605', 'ریاض الصالحین 605', 'رواه البخاري', 'سُئلت أم المؤمنين عائشة رضي الله عنها عن حال النبي صلى الله عليه وسلم في بيته وكيف كان يصنع؟ 

فقالت: كان بشرًا من البشر، ويعمل ما يعمل الرجال في بيوتهم، فيكون في خدمة نفسه وأهله؛ يحلب شاته، ويرقع ثوبه، ويخصف نعله، ويرقع دلوه، وكان إذا حضرت إقامة الصلاة خرج إليها صلى الله عليه وسلم دون تأخير.', 'كمال تواضعه صلى الله عليه وسلم وبره بأهله.
الأعمال الدنيوية ينبغي أن لا تلهي العبد عن الصلاة.
محافظة النبي صلى الله عليه وسلم على الصلاة في أول أوقاتها.
قال ابن حجر: وفيه الترغيب في التواضع وترك التكبر وخدمة الرجل أهله.', null, 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/6220', false),
(20606, 2, 201, 606, 'hadith', 'عن أبي رفاعة تميم بن أسيد رضي الله عنه قال: انتهيت إلى رسول الله صلى الله عليه وسلم وهو يخطب، فقلت: يا رسول الله رجل غريب جاء يسأل عن دينه لا يدرى ما دينه؟ فأقبل علي رسول الله صلى الله عليه وسلم، وترك خطبته حتى انتهى إلى فأتى بكرسي، فقعد عليه وجعل يعلمني مما علمه الله ثم أتى خطبته فأتم آخرها".', 'I came to Messenger of Allah (ﷺ) while he was delivering a Khutbah and said: "O Messenger of Allah, a stranger (meaning himself) has come to inquire about his Deen. He is quite ignorant about his Deen." Messenger of Allah (ﷺ) interrupted his Khutbah and turned to me. Then a chair was brought for him and he sat on it. He started instructing me what Allah had taught him. Then he resumed his Khutbah and completed it..', 'أبي رفاعة تميم بن أسيد رضي الله عنه', 'Tamim bin Usaid (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 606', 'Riyad as-Salihin 606', 'ریاض الصالحین 606', 'رواه مسلم', 'من تواضع الرسول -عليه الصلاة والسلام- أنه جاءه رجل وهو يخطب الناس، فقال: رجل غريب جاء يسأل عن دينه فأقبل إليه النبي –صلى الله عليه وسلم- وقطع خطبته حتى انتهى إليه، ثم جيء إليه بكرسي، فجعل يعلم هذا الرجل، لأن هذا الرجل جاء مشفقاً محباً للعلم، يريد أن يعلم دينه حتى يعمل به فأقبل إليه النبي -عليه الصلاة والسلام- وقطع الخطبة وعلمه، ثم بعد ذلك أكمل خطبته.', 'كمال تواضعه -صلى الله عليه وسلم- ورفقه بالمسلمين، وكمال شفقته عليهم وخفض جناحه لهم.
حرص النبي -صلى الله عليه وسلم- على تعليم الناس أمور دينهم.
من جهل شيئاً من أمر دينه ينبغي عليه سؤال أهل العلم.
جواز قطع الخطبة إذا كان الداعي أولى من الاستمرار.
المبادرة إلى المستفتي، وتقديم أهم الأمور فأهمها.
جواز إعطاء الدروس وإلقاء المحاضرات وتعليم الناس على كرسي.
من قطع خطبته أتمها إذا عاد إليها، ولا يعيدها من أولها.', 'يخطب : خطبة الجمعة.
يسأل عن دينه : عما يلزمه من أحكام دينه.', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/5656', false),
(20607, 2, 201, 607, 'hadith', 'عن أنس رضي الله عنه أن رسول الله صلى الله عليه وسلم كان إذا أكل طعاماً لعق أصابعه الثلاث قال: وقال: "إذا سقطت لقمة أحدكم، فليمط عنها الأذى، وليأكلها، ولا يدعها للشيطان" وأمر أن تسلت القصعة قال: فإنكم لا تدرون فى أى طعامكم البركة".', 'When the Messenger of Allah (ﷺ) finished eating his food, he would lick his three fingers (i.e., the forefinger, the middle finger and the thumb). He (ﷺ) said, "If anyone of you drops a morsel, he should remove anything harmful from it and then eat it. He should not leave it for Shaitan." He commanded us to clean out the dish saying, "You do not know in what portion of your food the blessing lies.".', 'أنس رضي الله عنه', 'Anas (May Allah be pleased with him)', 'صحيحان', 'رياض الصالحين 607', 'Riyad as-Salihin 607', 'ریاض الصالحین 607', 'رواه مسلم', 'في الحديث التحذير من الشيطان، والتنبيه على ملازمته للإنسان في تصرفاته، فينبغي أن يتأهب ويحترز منه ولا يغتر بما يزينه له، والطعام الذي يحضره الإنسان فيه بركة، ولا يدرى أن تلك البركة فيما أكله أو فيما بقي على أصابعه أو في ما بقي في أسفل الصحن أو في اللقمة الساقطة، فينبغي أن يحافظ على هذا كله لتحصل البركة، وأصل البركة الزيادة وثبوت الخير والانتفاع به، والمراد هنا: ما يحصل به التغذية وتسلم عاقبته من أذى ويقوى على طاعة الله تعالى. و هنا فائدة ذكرها بعض الأطباء أن الأنامل تفرز عند الأكل شيئاً يعين على هضم الطعام.', 'استحباب لعق الأصابع بعد الأكل قبل غسلها.
السنة في تناول الطعام أخذه بثلاث أصابع.
حرص الإسلام على المحافظة على المال، وعدم ضياعه مهما كان قليلاً.
استحباب أكل اللقمة الساقطة كسراً لنفسه، وتواضعاً لربه، والتماساً للبركة.
الإسلام يدعو إلى النظافة، فإذا وقع الطعام فينبغي إزالة الأذى عنه قبل أكله.
الشيطان قد يشارك العبد في طعامه وشرابه إذا لم يحترز منه بالوسائل الشرعية.
بيان سمو الشريعة، وأنها شريعة مبنية على المصالح، فما من شيء أمر الله ورسوله -صلى الله عليه وسلم- إلا والمصلحة في وجوده.
زيادة اطمئنان النفس؛ لأن الإنسان بشر قد يكون عنده إيمان وتسليم بما حكم الله به ورسوله، لكن إذا ذكرت الحكمة ازداد إيماناً، وازداد يقيناً.
في الحديث رد على من كره لعق الأصابع استقذاراً، لكن يكون ذلك مستقذراً  لو فعله في اثناء الأكل لأنه يعيد أصابعه في الطعام وعليها أثر ريقه.
حسن تعليم الرسول عليه الصلاة والسلام، وأنه إذا ذكر الحكم ذكر الحكمة منه', 'لعق أصابعه : لحس أصابعه.
أصابعه الثلاث : الوسطى ثم السبابة ثم الإبهام.
فليمط : فليزل.
الأذى : الوسخ.
القصعة : وعاء يؤكل فيه.
البركة : الزيادة وثبوت الخير والانتفاع.', 'sunnah.com', null, false, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/5653', false),
(20608, 2, 201, 608, 'hadith', 'عن أبي هريرة رضي الله عنه عن النبي صلى الله عليه وسلم قال: "ما بعث الله نبياً إلا رعى الغنم" قال أصحابه: وأنت؟ فقال: نعم كنت أرعاها على قراريط لأهل مكة".', 'The Prophet (ﷺ) said, "Every Prophet has tended sheep." He was asked: "And did you?" He replied: "Yes, I tended them for a few carats for the Makkans.".', 'أبي هريرة رضي الله عنه', 'Abu Hurairah (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 608', 'Riyad as-Salihin 608', 'ریاض الصالحین 608', 'رواه البخاري', null, null, null, 'sunnah.com', null, false, null, false),
(20609, 2, 201, 609, 'hadith', 'وعنه عن النبي صلى الله عليه وسلم قال: لو دعيت إلى كراع أو ذراع لأجبت ولو أهدى إلى ذراع أو كراع لقبلت".', 'The Prophet (ﷺ) said: "If I am invited to a meal consisting of a sheep''s foot or shoulder, I would respond and I would accept as a gift a shoulder or a foot of a sheep.".', null, 'Abu Hurairah (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 609', 'Riyad as-Salihin 609', 'ریاض الصالحین 609', 'رواه البخاري', 'في هذا الحديث دليل على حسن خلقه صلى الله عليه وسلم وتواضعه وجبره لقلوب الناس، وعلى قبول الهدية وإن كانت قليلة، وإجابة من يدعو الرجل إلى منزله ولو علم أن الذي يدعوه إليه قليل؛ لأن القصد من قبول الهدية وإجابة الدعوة تأليف الداعي وإحكام التحابب، وبالرد وعدم الموافقة يحدث النفور والعداوة .
وخص الذراع والكراع بالذكر ليجمع بين الحقير والخطير؛ لأن الذراع كانت أحب إليه –صلى الله عليه وسلم- من غيرها، والكراع لا قيمة له.', 'إجابة الدعوة ولو إلى شيء يسير من الطعام.
شدة تواضعه –صلى الله عليه وسلم- وجبره لقلوب الناس.
قبول الهدية مهما قلّت، لما في ذلك من تأليف القلوب والمحبة بين المسلمين.
الحث على تعاطي ما يبعث التآلف، ويغرس الوداد.', 'كُرَاع : قوائم الدابة، أو ما دون الركبة إلى الكعب.
ذراع : لحم الذراع، وهو فوق الكراع في الدواب.', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/6216', false),
(20610, 2, 201, 610, 'hadith', 'عن أنس رضي الله عنه قال: كانت ناقة رسول الله صلى الله عليه وسلم: العضباء لا تسبق، أو لا تكاد تسبق فجاء أعرابي على قعود له، فسبقها، فشق ذلك على المسلمين حتى عرفه، النبي صلى الله عليه وسلم فقال: «حق على الله أن لا يرتفع شئ من الدنيا إلا وضعه».', 'Messenger of Allah (ﷺ) had a she-camel called Al-''Adba'' which would not allow any other camel to surpass her. A bedouin came riding his camel which outstripped it. The Muslims were much grieved at this. Messenger of Allah (ﷺ) perceived it and said, "It is Allah''s Way that he lowers whatever raises itself in the world.".', 'أنس رضي الله عنه', 'Anas bin Malik (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 610', 'Riyad as-Salihin 610', 'ریاض الصالحین 610', 'رواه البخاري', 'في الحديث أن ناقة النبي صلى الله عليه وسلم العضباء كان الصحابة رضي الله عنهم يرون أنها لا تسبق أو لا تكاد تسبق، فجاء هذا الأعرابي بقعوده فسبق العضباء، فكأن ذلك شق على الصحابة رضي الله عنهم ، فقال النبي صلى الله عليه وسلم لما عرف ما في نفوسهم: "حق على الله ألا يرتفع شيء من الدنيا إلا وضعه"، فكل ارتفاع يكون في الدنيا فإنه لابد أن يؤول إلى انخفاض، فإن صحب هذا الارتفاع ارتفاع في النفوس وتعاظم فإن الوضع إليه أسرع؛ لأن الوضع يكون عقوبة، أما إذا لم يصحبه شيء فإنه لابد أن يرجع ويوضع، وفي قوله عليه الصلاة والسلام: "من الدنيا" دليل على أن ما ارتفع من أمور الآخرة فإنه لا يضعه الله، فقوله: (يرفع الله الذين آمنوا منكم والذين أوتوا العلم درجات)، فهؤلاء لا يضعهم الله عز وجل ما داموا على وصف العلم والإيمان، فإنه لا يمكن أن يضعهم الله، بل يرفع لهم الذكر، ويرفع درجاتهم في الآخرة.', 'الحث على التواضع، وطرح رداء الكبرياء.
الإعلام بأن أمور الدنيا ناقصة غير كاملة.
بيان ما كان عليه الرسول –صلى الله عليه وسلم- من التواضع، وتطييب نفوس أصحابه.
جواز اتخاذ الإبل للركوب والمسابقة عليها.', 'العضباء : اسم ناقة رسول الله –صلى الله عليه وسلم-، والعضب شق الأذن، ولم تكن ناقة الرسول صلى الله عليه وسلم مشقوقة الأذن.
قعود : الفتيّ من الإبل الذي استحق أن يركب.
حتى عرفه : عرف أثر المشقة.
حق : واجب أوجبه الله على نفسه.
وضعه : خفضه وأسقطه.', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/6204', false),
(20611, 2, 201, 611, 'hadith', 'عن عبد الله بن مسعود رضي الله عنه عن النبى صلى الله عليه وسلم قال: "لا يدخل الجنة من كان في قلبه مثقال ذرة من كبر" فقال رجل" إن الرجل يحب أن يكون ثوبه حسناً ونعله حسناً؟ قال: "إن الله جميل يحب الجمال الكبر بطر الحق وغمط الناس".', 'The Prophet (ﷺ) said, "He who has, in his heart, an ant''s weight of arrogance will not enter Jannah." Someone said: "A man likes to wear beautiful clothes and shoes?" Messenger of Allah (ﷺ) said, "Allah is Beautiful, He loves beauty. Arrogance means ridiculing and rejecting the Truth and despising people.".', 'عبد الله بن مسعود رضي الله عنه', '''Abdullah bin Mas''ud (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 611', 'Riyad as-Salihin 611', 'ریاض الصالحین 611', 'رواه مسلم', 'عن ابن مسعود رضي الله عنه أن النبي صلى الله عليه وسلم قال: "لا يدخل الجنة من كان في قلبه مثقال ذرة من كبر"، وهذا الحديث من أحاديث الوعيد وتحتاج إلى تفصيل حسب الأدلة الشرعية، فالذي في قلبه كبر، إما أن يكون كبراً عن الحق وكراهة له، فهذا كافر مخلد في النار ولا يدخل الجنة، لقول الله تعالى : (ذلك بأنهم كرهوا ما أنزل الله، فأحبط أعمالهم) ، وأما إذا كان كبراً على الخلق وتعاظماً على الخلق، لكنه لم يستكبر عن عبادة الله فهذا جاء فيه هذا الوعيد فلا يدخل الجنة مع أول زمرة، ولما حدث النبي صلى الله عليه وسلم بهذا الحديث قال رجل يا رسول الله: الرجل يحب أن يكون ثوبه حسناً ونعله حسنة يعني فهل هذا من الكبر ؟ فقال النبي صلى الله عليه وسلم : "إن الله جميل يحب الجمال" جميل في ذاته جميل في أفعاله جميل في صفاته كل ما يصدر عن الله عز وجل فإنه جميل وليس بقبيح. 
وقوله: "يحب الجمال" أي يحب التجمل بمعنى أنه يحب أن يتجمل الإنسان في ثيابه وفي نعله وفي بدنه وفي جميع شؤونه؛ لأن التجمل يجذب القلوب إلى الإنسان ويحببه إلى الناس بخلاف التشوه الذي يكون فيه الإنسان قبيحاً في شعره أو في ثوبه أو في لباسه.', 'الكبر من الذنوب العظيمة التي تستحق عذاب الله في الدنيا والآخرة.
الجمال إذا لم يكن على وجه الفخر والخيلاء والمباهاة لا يدخل في الكبر.', 'مثقال : وزن.
ذرة : الجزء المتناهي في الصغر.
بطر الحق : رد الحق.
غمط الناس : احتقارهم وازدراؤهم.', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/6209', false),
(20612, 2, 201, 612, 'hadith', 'عن سلمه بن الأكوع رضي الله عنه أن رجلاً أكل عند رسول الله صلى الله عليه وسلم بشماله، فقال: "كل بيمينك" قال: لا أستطيع! قال: "لا اتسطعت" ما منعه إلا الكبر. قال: فما رفعه إلى فيه".', 'A man ate in the presence of Messenger of Allah (ﷺ) with his left hand. He (ﷺ) said, "Eat with your right hand." He said: "I cannot." Thereupon he (the Prophet (ﷺ)) said, "May you never be able to do that." It was arrogance that prevented him from doing it, and he could not raise it (the right hand) up to his mouth afterwards..', 'سلمه بن الأكوع رضي الله عنه', 'Salamah bin Al-Akwa'' (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 612', 'Riyad as-Salihin 612', 'ریاض الصالحین 612', 'رواه مسلم', 'رَأى النبيُّ صلى الله عليه وسلم رجلًا يَأكلُ بيدِه الشمال، فأَمَرَه أن يَأكلَ بيدِه اليمنى، 
فأجابه الرجل تَكَبُّرًا وكَذِبًا بأنه لا يستطيع! 
فدعا عليه النبيُّ صلى الله عليه وسلم أن يُحْرَمَ الأكلَ باليمين، 
فأجاب الله دعوةَ نبيِّه بأنْ شُلَّتْ يَمينُه، فلم يرفعْها إلى فمِهِ بعد ذلك بطعام أو شراب.', 'وجوب الأكل باليمين، وحرمة الأكل بالشمال.
الاستكبار عن تطبيق الأحكام الشرعية يستحق فاعلُه العقوبةَ.
إكرام الله لنبيه محمد صلى الله عليه وسلم بإجابة دعوته.
مشروعية الأمر بالمعروف والنهي عن المنكر على كل حالٍ حتى في حالِ الأكل.', null, 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/3372', false),
(20613, 2, 201, 613, 'hadith', 'عن حارثة بن وهب رضي الله عنه قال: سمعت رسول الله صلى الله عليه وسلم يقول: ألا أخبركم بأهل النار؟: كل عتل جواظ مستكبر" ((متفق عليه)). وتقدم شرحه في باب ضعفة المسلمين.', 'Messenger of Allah (ﷺ) said, "Shall I not inform you about the inmates of Hell? It is every violent, impertinent and proud person.".', 'حارثة بن وهب رضي الله عنه', 'Harithah bin Wahab (May Allah be pleased with him)', null, 'رياض الصالحين 613', 'Riyad as-Salihin 613', 'ریاض الصالحین 613', null, null, null, null, 'sunnah.com', null, false, null, false),
(20614, 2, 201, 614, 'hadith', 'عن أبى سعيد رضي الله عنه، عن النبى صلى الله عليه وسلم قال: «احتجت الجنة والنار، فقالت النار: في الجبارون والمتكبرون، وقالت الجنة: في ضعفاء الناس ومساكينهم. فقضى الله بينهما: إنك الجنة رحمتي، أرحم بك من أشاء، وإنك النار عذابي أعذب بك من أشاء ولكليكما علي ملؤها».', 'The Prophet (ﷺ) said, "There was a dispute between Hell and Jannah, and Hell said: ''The haughty and proud are in me.'' The Jannah said: ''In me are the weak and the humble.'' Thereupon Allah, the Exalted, judged between them saying: ''You the Jannah are My Mercy, and through you I shall show mercy to those whom I wish.'' (And addressing the Hell) He said: ''You are My punishment to punish whom I wish amongst My slaves, and each one of you will have its fill."''.', 'أبى سعيد رضي الله عنه', 'Abu Sa''id Al-Khudri (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 614', 'Riyad as-Salihin 614', 'ریاض الصالحین 614', 'رواه مسلم', 'معنى هذا الحديث: أن الجنة والنار تحاجتا فيما بينهما، كل واحدة تدلي بحجتها، وهذا من الأمور الغيبية التي يجب علينا أن نؤمن بها حتى وإن استبعدتها العقول 
فالجنة احتجت على النار، والنار احتجت على الجنة، النار احتجت بأن فيها الجبارين والمتكبرين، الجبارون أصحاب الغلظة والقسوة، والمتكبرون أصحاب الترفع والعلو، والذين يغمطون الناس ويردون الحق، كما قال النبي صلى الله عليه وسلم في الكبر: (إنه بطر الحق وغمط الناس).
فأهل الجبروت وأهل الكبرياء هم أهل النار والعياذ بالله، وربما يكون صاحب النار لين الجانب للناس، حسن الأخلاق، لكنه جبار بالنسبة للحق، مستكبر عن الحق، فلا ينفعه لينه وعطفه على الناس، بل هو موصوف بالجبروت والكبرياء ولو كان لين الجانب للناس؛ لأنه تجبر واستكبر عن الحق.
أما الجنة فقالت: إن فيها ضعفاء الناس وفقراء الناس. فهم في الغالب الذين يلينون للحق وينقادون له، وأما أهل الكبرياء والجبروت؛ ففي الغالب أنهم لا ينقادون.
فقضى الله عز وجل بينهما فقال للجنَّة : ( إنك الجنة رحمتي أرحم بك من أشاء ) وقال للنار: ( إنك النار عذابي أعذب بك من أشاء ) 
ثم قال عز وجل: ( ولكليكما عليَّ ملؤها ) تكفل عز وجل وأوجب على نفسه أن يملأ الجنة ويملأ النار، وفضل الله سبحانه وتعالى ورحمته أوسع من غضبه، فإنه إذا كان يوم القيامة ألقى من يلقى في النار، وهي تقول : هل من مزيد، يعني أعطوني. أعطوني. زيدوا. فيضع الله عليها رجله، وفي لفظ عليها : قدمه، فينزوي بعضها على بعض، ينضم بعضها إلى بعض من أثر وضع الرب عز وجل عليها قدمه، وتقول: قط قط، يعني: كفاية كفاية، وهذا ملؤها.
أما الجنة فإن الجنة واسعة، عرضها السَّمَوَاتِ والأرض يدخلها أهلها ويبقى فيها فضل زائد على أهلها، فينشئ الله تعالى لها أقواماً فيدخلهم الجنة بفضله ورحمته؛ لأن الله تكفل لها بملئها.', 'بشارة المؤمنين المستضعفين بالجنة، ووعيد المتكبرين والجبارين بالنار.
أن الله تعالى شاء أن يترك الناس أحراراً يختار كل واحد منهم العمل الذي يريده بعد أن يبين لهم طريق الحق من الباطل، وقد علم سبحانه أن فريقاً سيختار طريق الشر ويكون مصيره النار فيملؤها ، وأن فريقاً سيختار بإرادته طريق الخير فيكون مصيره الجنة فيملؤها .
هذا الحديث على ظاهره، فقد جعل الله في الجنة والنار تمييزاً تدركان به؛ فتحاجتا وكان لهما قولاً.
التواضع لله وخفض الجناح للمؤمنين سبب في رحمة الله ودخول الجنة.
الجنة دار رحمة الله يرحم بها من يشاء من أوليائه، والنار دار عذابه يعذب بها من يشاء من أعدائه.
جواز المناظرة، وأنها مشروعة لإظهار الحق وإزهاق الباطل.
أن الفقراء والضعفاء هم أهل الجنة؛ لأنهم في الغالب هم الذين ينقادون للحق، وأن الجبارين المتكبرين هم أهل النار والعياذ بالله؛ لأنهم مستكبرون على الحق .', 'احتجت : تخاصمت وأقامت كل واحدة منهما الحجة على الأخرى ، والمراد من الحوار حكاية ما اختص به كل منهما.
الجبارون : الذين يتجبرون على الناس ويقهرونهم على مرادهم.
ضعفاء الناس : المتواضعون،أو المستضعفون.
مساكينهم : المحتاجون.
قضى بينهم : أخبر عما أراده لها مما سبقت به إرادته.
لكليكما علي ملؤها : لكل من الجنة والنار ما يملؤها.', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/3261', false),
(20615, 2, 201, 615, 'hadith', 'عن أبى هريرة رضي الله عنه أن رسول الله صلى الله عليه وسلم قال: «لا ينظر الله يوم القيامة إلى من جر إزاره بطراً».', 'Messenger of Allah (ﷺ) said, "On the Day of Resurrection, Allah will not look at him who trails his lower garment out of pride.".', 'أبى هريرة رضي الله عنه', 'Abu Hurairah (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 615', 'Riyad as-Salihin 615', 'ریاض الصالحین 615', 'متفق عليه', null, null, null, 'sunnah.com', null, false, null, false),
(20616, 2, 201, 616, 'hadith', 'وعنه قال: قال رسول الله صلى الله عليه وسلم: «ثلاثة لا يكلمهم الله يوم القيامة، ولايزكيهم، ولا ينظر إليهم ، ولهم عذاب أليم: شيخ زان وملك كذاب، وعائل مستكبر».', 'Messenger of Allah (ﷺ) said, "There are three (types of) people to whom Allah will not speak on the Day of Resurrection, nor will He purify them, nor look at them, and they will have a painful punishment. These are: An aged man who commits Zina (illicit sexual act), a ruler who lies, and a proud poor person.".', null, 'Abu Hurairah (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 616', 'Riyad as-Salihin 616', 'ریاض الصالحین 616', 'رواه مسلم', null, null, null, 'sunnah.com', null, false, null, false),
(20617, 2, 201, 617, 'hadith', 'وعنه قال: قال رسول الله صلى الله عليه وسلم: «قال الله عز وجل: العز إزاري والكبرياء ردائي، فمن ينازعني في واحد منهما فقد عذبته».', 'Messenger of Allah (ﷺ) said, "Allah, the Exalted, says: ''Honour is My Izar and Pride is My Cloak. Whoever vies with Me regarding one of them, shall be tormented."''.', null, 'Abu Hurairah (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 617', 'Riyad as-Salihin 617', 'ریاض الصالحین 617', 'رواه مسلم', null, null, null, 'sunnah.com', null, false, null, false),
(20618, 2, 201, 618, 'hadith', 'وعنه أن رسول الله صلى الله عليه وسلم قال:«بينما رجل يمشى في حلة تعجبه نفسه، مرجل رأسه، يختال في مشيته، إذ خسف الله به، فهو يتجلجل في الأرض إلى يوم القيامة».', 'Messenger of Allah (ﷺ) said, "While a man was walking, dressed in clothes admiring himself, his hair combed, walking haughtily when Allah caused the earth to swallow him. Now he will continue to go down in it (as a punishment) until the Day of Resurrection.".', null, 'Abu Hurairah (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 618', 'Riyad as-Salihin 618', 'ریاض الصالحین 618', 'متفق عليه', 'أخبر النبي صلى الله عليه وسلم أن رجلاً كان يمشي متكبرًا وهو يلبس ثياباً حسنة، وممشط شعره، فخسف الله به الأرض، فانهارت به الأرض وانغمس فيها، واندفن فهو يتجلجل فيها إلى يوم القيامة؛ لأنه -والعياذ بالله- لما صار عنده هذا الكبرياء وهذا التيه وهذا الإعجاب خسف به.
وقوله: "يتجلجل في الأرض"، يحتمل أنه يتجلجل وهو حي حياة دنيوية، فيبقى هكذا معذباً إلى يوم القيامة، معذباً وهو في جوف الأرض وهو حي، فيتعذب كما يتعذب الأحياء، ويحتمل أنه لما اندفن مات كما هي سنة الله عز وجل، مات ولكن مع ذلك يتجلجل في الأرض وهو ميت فيكون تجلجله هذا تجلجلاً برزخياً لا نعلم كيفيته، والله أعلم المهم أن هذا جزاؤه والعياذ بالله.', 'حرمة الكبر والخيلاء، وسوء عاقبة من اتصف بهما.
المبالغة في الملبس والتأنق يدخل في نفس العبد الاختيال والعجب، ولكن التجمل دون مبالغة ودون عجب جائز.
إثبات عذاب القبر.', 'حُلة : إزار ورداء، ولا تسمى إلا إذا كانت ثوبين.
يختال : يتكبر.
خسف الله به : غيّبه في الأرض.
مرجل رأسه : أي: ممشطه.
يتجلجل : أي: يغوص وينزل.', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/5905', false),
(20619, 2, 201, 619, 'hadith', 'عن سلمه بن الأكوع رضي الله عنه قال: قال رسول الله صلى الله عليه وسلم: «لا يزال الرجل يذهب بنفسه حتى يكتب في الجبارين، فيصيبه ما أصابهم».', 'Messenger of Allah (ﷺ) said, "Man continues to display haughtiness and arrogance until he is recorded among the arrogant and will be therefore afflicted with what afflicts them.".', 'سلمه بن الأكوع رضي الله عنه', 'Salamah bin Al-Akwa'' (May Allah be pleased with him)', 'حسن', 'رياض الصالحين 619', 'Riyad as-Salihin 619', 'ریاض الصالحین 619', 'رواه الترمذي وقال: حديث حسن. (("يذهب بنفسه" أى: يرتفع ويتكبر', null, null, null, 'sunnah.com', null, false, null, false),
(20620, 2, 201, 620, 'hadith', 'عن أنس رضي الله عنه قال: كان رسول الله صلى الله عليه وسلم أحسن الناس خلقاً.', 'The Messenger of Allah (ﷺ) was the best of all the people in behaviour..', 'أنس رضي الله عنه', 'Anas (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 620', 'Riyad as-Salihin 620', 'ریاض الصالحین 620', 'متفق عليه', null, null, null, 'sunnah.com', null, false, null, false),
(20621, 2, 201, 621, 'hadith', 'وعنه قال: ما مسست ديباجاً ولاحريراً ألين من كف رسول الله صلى الله عليه وسلم، ولا شممت رائحة قط أطيب من رائحة رسول الله صلى الله عليه وسلم ولقد خدمت رسول الله صلى الله عليه وسلم عشر سنين، فما قال لي قط :أف، ولا قال لشئ فعلته: لم فعلته؟ ولا لشئ لم أفعله: ألا فعلت كذا؟.', 'I never felt any piece of velvet or silk softer than the palm of the Messenger of Allah (ﷺ), nor did I smell any fragrance more pleasant than the smell of Messenger of Allah (ﷺ). I served him for ten years, and he never said ''Uff'' (an expression of disgust) to me. He never said ''why did you do that?'' for something I had done, nor did he ever say ''why did you not do such and such'' for something I had not done..', null, 'Anas (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 621', 'Riyad as-Salihin 621', 'ریاض الصالحین 621', 'متفق عليه', 'كان أنس بن مالك قد خدم النبي صلى الله عليه وسلم عشر سنين، فكانت يده صلى الله عليه وسلم لينة، وكذلك أيضاً رائحته صلى الله عليه وسلم ما شم طيباً قط أحسن من رائحة النبي صلى الله عليه وسلم . ويقول: ولقد خدمت النبي صلى الله عليه وسلم عشر سنين، فما قال لي: أف قط، يعني: ما تضجر منه أبداً عشر سنوات يخدمه ما تضجر منه ولا قال لشيء فعلته: لم فعلت كذا؟، حتى الأشياء التي يفعلها أنس اجتهاداً منه ما كان الرسول صلى الله عليه وسلم يؤنبه أو يوبخه أو يقول لم فعلت كذا؟ مع أنه خادم، وكذلك ما قال لشيء لم أفعله: لِمَ لَم تفعل كذا وكذا؟، وهذا من حسن خلقه -عليه الصلاة والسلام-.', 'كمال أخلاق الرسول –صلى الله عليه وسلم- وحسن معاملته لخادمه وأصحابه.
الحث على الرفق بالخادم، وعدم التضجر من فعله.
الحث على التنظيف والتطيب، وهكذا كان فعله -صلى الله عليه وسلم-.', 'ديباجاً : ثوباً متخذاً من الحرير.
أفٍّ : كلمة تضجُّر وتكرُّه.', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/6221', false),
(20622, 2, 201, 622, 'hadith', 'عن الصعب بن جثامة رضي الله عنه قال: أهديت رسول الله صلى الله عليه وسلم حماراً وحشياً فرده علي، فلما رأى ما في وجهي قال: «إنا لم نرده عليك إلا لأنا حرم».', 'I presented a wild ass to Messenger of Allah (ﷺ) as a gift but he returned it to me. When he perceived signs of despair on my face, he said, "I have declined to accept it because I am in the state of Ihram.".', 'الصعب بن جثامة رضي الله عنه', 'Sa''b bin Jaththamah (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 622', 'Riyad as-Salihin 622', 'ریاض الصالحین 622', 'متفق عليه', 'من حسن خلقه صلى الله عليه وسلم أنه كان لا يداهن الناس في دين الله، ولا يفوته أن يطيب قلوبهم، فالصعب بن جثامة رضي الله عنه مر به النبي صلى الله عليه وسلم ، والنبي صلى الله عليه وسلم محرم وكان الصعب بن جثامة عداء راميًا، فلما مر به النبي صلى الله عليه وسلم صاد له حمارًا وحشيًّا، وجاء به إليه فرده النبي صلى الله عليه وسلم فثقل ذلك على الصعب، كيف يرد النبي صلى الله عليه وسلم هديته؟، فتغير وجهه فلما رأى ما في وجهه طيب قلبه، وأخبره أنه لم يرده عليه إلا لأنه محرم، والمحرم لا يأكل من الصيد الذي صِيد من أجله.', 'استحباب قبول الهدية، والأكل منها.
حسن خُلُق النبي –صلى الله عليه وسلم- حيث طيَّب نفس المهدي ببيان العلة وسبب الامتناع.
جواز رد الهدية لعلة.
جواز الحكم بالقرائن عند فقد الدلائل، لقول الصعب: فلما رأى ما في وجهي.', 'حُرُم : محرمون بالحج أو العمرة.
وحشيًّا : هو الحيوان البري غير المُرَوَّض.', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/5772', false),
(20623, 2, 201, 623, 'hadith', 'عن النواس بن سمعان رضي الله عنه قال: سألت رسول الله صلى الله عليه وسلم عن البر والإثم فقال: «البر حسن الخلق، والإثم: ما حاك في نفسك وكرهت أن يطلع عليه الناس».', 'I asked Messenger of Allah (ﷺ) about virtue and sin, and he said, "Virtue is noble behaviour, and sin is that which creates doubt and you do not like people to know about it.".', 'النواس بن سمعان رضي الله عنه', 'Nawwas bin Sam''an (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 623', 'Riyad as-Salihin 623', 'ریاض الصالحین 623', 'رواه مسلم', 'سُئِلَ النبيُّ صلى الله عليه وسلم عن البر والإثم، فقال: 

أعظم خِصَال البر حسن الخُلُق مع الله بالتقوى، ومع الخَلْق باحتمال الأذى، وقِلَّة الغَضب، وبسط الوجه، وطيب الكلام، والصلة والطاعة واللطف والمَبَرّة وحسن العشرة والصحبة. 

وأما الإثم فما تَحَرَّك في النفس مِن المشتبهات وتردَّد دون أنْ ينشرح الصدر له، وحصل في القلب منه الشك، والخوف من كونه ذنبًا، ولم تُرِد أن تُظْهِرَه لكونه قبيحًا لأعيان وأماثل الناس وكُمَّلِهم، وذلك لأن النفس بطبعها تحب اطلاع الناس على خيرها، فإذا كَرِهَت الاطلاع على بعض أفعالها فهو إثم لا خير فيه.', 'الحثُّ على مكارم الأخلاق؛ لأنّ حسن الخلق من أعظم خصال البر.
الحق والباطل لا يلتبس أمرُهما على المؤمن، بل يعرف الحق بالنور الذي في قلبه، وينفر عن الباطل فينكره.
من علامات الإثم  قلق القلب واضطرابه، وكراهة اطلاع الناس عليه.
قال السندي: هذا في المشتبهات من الأمور التي لا يعلم الناس فيها بتعيين أحد الطرفين؛ وإلا فالمأمور به في الشرع من غير ظهور دليل فيه على خلاف ذلك من البر، والمنهي عنه كذلك من الإثم، ولا حاجة فيهما إلى استفتاء القلب وطمأنينته.
المخاطَب في الحديث أصحاب الفطرة السليمة، لا أصحاب القلوب المنكوسة التي لا تعرف معروفًا ولا تنكر منكرًا إلا ما أُشرِبتْ من هواها.
قال الطيبي: قيل فُسِّرَ البر في الحديث بمعان شتى، ففسَّره في موضع بما اطمأنت إليه النفس واطمأن إليه القلب، وفسره في موضع بالإيمان، وفي موضع بما يقربك إلى الله، وهنا بحسن الخلق، وفسر حسن الخلق: باحتمال الأذى وقلة الغضب وبسط الوجه وطيب الكلام، وكلها متقاربة في المعنى.', null, 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/4308', false),
(20624, 2, 201, 624, 'hadith', 'عن عبد الله بن عمرو بن العاص رضي الله عنهما قال: لم يكن رسول الله صلى الله عليه وسلم فاحشاً ولا متفحشاً. وكان يقول: «إن من خياركم أحسنكم أخلاقاً».', 'Messenger of Allah (ﷺ) did not indulge in loose talk nor did he like to listen to it. He used to say, "The best of you is the best among you in conduct.".', 'عبد الله بن عمرو بن العاص رضي الله عنهما', '''Abdullah bin ''Amr bin Al-''as (May Allah be pleased with them)', 'صحيح', 'رياض الصالحين 624', 'Riyad as-Salihin 624', 'ریاض الصالحین 624', 'متفق عليه', 'لم يَكنْ مِن أخلاقِ النبيِّ صلى الله عليه وسلم الكلامُ القبيح، أو الفعلُ القبيح، ولم يكن يَقصدُه ولا يتعمدُه، فهو صلى الله عليه وسلم ذو خلق عظيم.

وكان صلى الله عليه وسلم يقول: إنَّ أفضلَكم عند الله أحسنُكم خُلُقًا، بِبَذْلِ المعروف، وطلاقةِ الوجه، وكَفِّ الأذى واحتماله، ومخالطة الناس بالجميل.', 'على المؤمن أن يبتعد عن الفُحْش من الكلام السيِّئ والفعل القبيح.
كمال خُلُق رسول الله صلى الله عليه وسلم، فلا يَصْدُرُ عنه إلا العمل الصالح والقول الطيب.
حسن الخلق مَيْدانٌ للتنافس، فمَن سَبَقَ كان من خيار المؤمنين وأكملِهم إيمانًا.', null, 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/5803', false),
(20625, 2, 201, 625, 'hadith', 'عن أبى الدرداء رضي الله عنه: أن النبى صلى الله عليه وسلم قال: «ما من شئ أثقل في ميزان المؤمن يوم القيامة من حسن الخلق، وإن الله يبغض الفاحش البذي» ((رواه الترمذي وقال: حديث حسن صحيح.', 'The Prophet (ﷺ) said, "Nothing will be heavier on the Day of Resurrection in the Scale of the believer than good manners. Allah hates one who utters foul or coarse language.".', 'أبى الدرداء رضي الله عنه', 'Abud-Darda (May Allah be pleased with him)', null, 'رياض الصالحين 625', 'Riyad as-Salihin 625', 'ریاض الصالحین 625', null, null, null, null, 'sunnah.com', null, false, null, false),
(20626, 2, 201, 626, 'hadith', 'عن أبى هريرة رضي الله عنه قال: سئل رسول الله صلى الله عليه وسلم عن أكثر ما يدخل الناس الجنة؟ قال: "تقوى الله وحسن الخلق" وسئل عن أكثر ما يدخل الناس النار، قال: "الفم والفرج".', 'Messenger of Allah (ﷺ) was asked about the deed which will be foremost to lead a man to Jannah. He replied, "Fear of Allah and the good conduct." Then he was asked about indulgence which will admit a man to Hell (Fire) and he answered, "The tongue and the genitals.".', 'أبى هريرة رضي الله عنه', 'Abu Hurairah (May Allah be pleased with him)', 'إسناده حسن', 'رياض الصالحين 626', 'Riyad as-Salihin 626', 'ریاض الصالحین 626', 'رواه الترمذي وقال: حديث حسن صحيح', 'أكثر الأسباب التي تدخل الجنة هي تقوى الله وحسن الخلق وتقوى الله تكون بالابتعاد عن المحرمات بجميع أنواعها، وحسن الخلق يكون مع الخلق وأقله ترك أذاهم وأعلاه بالإحسان إلى مَن أساء إليه.
وأكثر الأسباب التي تدخل النار هي الفم والفرج لأن الإنسان غالبًا ما يقع بسببهما في مخالفة الله سبحانه ومع الناس.', 'الحض على تقوى الله وحسن الخلق.
التحذير من اللسان وما يخرج منه لأنها تكب الناس في النار يوم القيامة.
التحذير من الزنا وأنه فاحشة سبيلها سوء العاقبة في الدنيا والآخرة.', 'الفم والفرج : المعاصي التي تكون بالفم كالكذب والنطق بالزور وأكل الحرام، والتي تكون بالفرج كالزنى واللواط والوطء في الدبر.', 'sunnah.com', null, false, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/5812', false),
(20627, 2, 201, 627, 'hadith', 'وعنه قال رسول الله صلى الله عليه وسلم: «أكمل المؤمنين إيماناً أحسنهم خلقاً وخياركم خياركم لنسائهم».', 'Messenger of Allah (ﷺ) said, "The most perfect man in his faith among the believers is the one whose behaviour is most excellent; and the best of you are those who are the best to their wives.".', null, 'Abu Hurairah (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 627', 'Riyad as-Salihin 627', 'ریاض الصالحین 627', 'رواه الترمذي وقال: حديث حسن صحيح', null, null, null, 'sunnah.com', null, false, null, false),
(20628, 2, 201, 628, 'hadith', 'عن عائشة رضي الله عنها، قالت: سمعت رسول الله صلى الله عليه وسلم يقول: « إن المؤمن ليدرك بحسن خلقه درجة الصائم القائم».', 'I heard Messenger of Allah (ﷺ) saying: "A believer will attain by his good behaviour the rank of one who prays during the night and observes fasting during the day.".', 'عائشة رضي الله عنها', '''Aishah (May Allah be pleased with her)', 'صحيح بشواهده', 'رياض الصالحين 628', 'Riyad as-Salihin 628', 'ریاض الصالحین 628', 'رواه أبو داود', 'بَيَّنَ النبيُّ صلى الله عليه وسلم أنَّ حُسْنَ الخُلُقِ يَبْلُغُ بصاحبِهِ مَنزلةَ المُداومِ على صيامِ النهارِ وقيامِ الليل، وجِمَاعُ حُسْنِ الخلق: بذْلُ المعروف، وحُسْن الكلام، وطلاقة الوجه، وكف الأذى واحتماله من الناس.', 'عِظَمُ عناية الإسلام بتهذيب الأخلاق وكمالها.
فضل حسن الخلق، حتى يبلغ العبدُ به درجةَ الصائم الذي لا يُفطر والقائم الذي لا يَتعب. 
صيام النهار وقيام الليل عملان عظيمان فيهما مشقة على النفوس، بَلَغَ درجتَهما صاحبُ حُسْنِ الخُلُق لمجاهدتِه نفسَه بحُسْن المعاملة.', null, 'sunnah.com', null, false, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/5799', false),
(20629, 2, 201, 629, 'hadith', 'عن أبى أمامه الباهلى رضي الله عنه قال: قال رسول الله صلى الله عليه وسلم: «أنا زعيم ببيت في ربض الجنة لمن ترك المراء، وإن كان محقاً، وببيت في وسط الجنة لمن ترك الكذب، وإن كان مازحاً، وببيت في أعلى الجنة لمن حسن خلقه».', 'Messenger of Allah (ﷺ) said, "I guarantee a house in Jannah for one who gives up arguing, even if he is in the right; and I guarantee a home in the middle of Jannah for one who abandons lying even for the sake of fun; and I guarantee a house in the highest part of Jannah for one who has good manners.".', 'أبى أمامه الباهلى رضي الله عنه', 'Abu Umamah Al-Bahili (May Allah be pleased with him)', 'حسن', 'رياض الصالحين 629', 'Riyad as-Salihin 629', 'ریاض الصالحین 629', 'حديث صحيح رواه أبو داود بإسناد صحيح', 'أخبر النبي صلى الله عليه وسلم أنه ضامن لبيت حول الجنة خارجاً عنها أو في أطرافها لمن ترك المجادلة وإن كان محقاً فيه لأنه مضيعة للوقت وسبب للبغضاء، وكذلك ضامن لبيت في وسط الجنة لمن ترك الكذب والإخبار بخلاف الواقع ولو كان مزاحاً، وببيت في أعلى الجنة لمن حسن خلقه ولو بمزاولة للنفس ورياضة لها.', 'جواز الضمان تشجيعاً على العمل لأن قوله صلى الله عليه وسلم: (زعيم) بمعنى ضامن ومتكفل.
الترغيب في ترك المراء لأنه يفضي إلى الاختلاف والشقاق.
الجنة درجات ومنازل الناس تكون في الجنة بحسب أعمالهم.
حرمة الكذب ولو كان مزاحاً إلا ما استثني، وهو قوله -صلى الله عليه وسلم-: «ليس الكذاب الذي يصلح بين الناس، ويقول خيرًا وينمي خيرًا» قال ابن شهاب: ولم أسمع يرخص في شيء مما يقول الناس كذب إلا في ثلاث: الحرب، والإصلاح بين الناس، وحديث الرجل امرأته وحديث المرأة زوجها. رواه مسلم.', 'زعيم : الضامن.
ربض الجنة : أدناها, وربض المدينة ما حولها.
المراء : المجادلة في القول والعمل بقصد الباطل.
محقًّا : بضم الميم وتشديد القاف، أي على حق.', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/5804', false),
(20630, 2, 201, 630, 'hadith', 'عن جابر رضي الله عنه أن رسول الله صلى الله عليه وسلم قال: "إن من أحبكم إلي، وأقربكم منى مجلساً يوم القيامة أحاسنكم أخلاقاً، وإن أبغضكم إلي وأبعدكم مني يوم القيامة، الثرثارون والمتشدقون والمتفيهقون" قالوا: يا رسول الله قد علمنا "الثرثارون والمتشدون" فما المتفيهقون؟ قال: "المتكبرون" ((رواه الترمذي وقال: حديث حسن)). "الثرثار": هو كثير الكلام تكلفاً. "والمتشدق": المتطاول على الناس بكلامه، ويتكلم بملء فيه تصافحاً وتعظيماً لكلامه؛ "والمتفيهق" :أصله من الفهق، وهو الامتلاء، وهو الذى يملأ فمه بالكلام، ويتوسع فيه ويغرب به تكبراً واتفاعاً، وإظهاراً للفضيلة على غيره. وروى الترمذي عن عبد الله بن المبارك رحمه الله في تفسير حسن الخلق قال: هو طلاقة الوجه، وبذل المعروف، وكف الأذى.', 'The Messenger of Allah (ﷺ) said, "The dearest and nearest among you to me on the Day of Resurrection will be one who is the best of you in manners; and the most abhorrent among you to me and the farthest of you from me will be the pompous, the garrulous, and Al-Mutafaihiqun." The Companions asked him: "O Messenger of Allah! We know about the pompous and the garrulous, but we do not know who Al-Mutafaihiqun are." He replied: "The arrogant people.".', 'جابر رضي الله عنه', 'Jabir (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 630', 'Riyad as-Salihin 630', 'ریاض الصالحین 630', null, 'أخبرَ النبيُّ صلى الله عليه وسلم أن مِن أحبكم إليه في الدنيا، وأقربكم منه مجلسًا يوم القيامة أحاسنكم أخلاقًا، وأنّ من أبغضكم إليه في الدنيا، وأبعدكم منه مجلسًا يوم القيامة سَيِّئيكم أخلاقًا؛ (الثرثارون) المكثرون الكلام تكلُّفًا وخروجًا عن الحق، (والمتشدقون) المتوسعون في الكلام تفاصحًا وتعظيمًا لكلامهم من غير احتياط واحتراز، (والمتفيهقون)، قالوا: يا رسول الله، قد علمنا الثرثارون والمتشدقون، فما المتفيهقون؟ قال: المتكبرون المستهزئون بالناس الذين يتوسعون في الكلام ويفتحون به أفواههم.', 'حسن الخلق من أسباب محبة رسول الله صلى الله عليه وسلم والقرب منه يوم القيامة، وسوء الخلق بعكس ذلك.
حسن الخلق من أسباب محبة الناس بعضهم لبعض، وسوء الخلق بعكس ذلك.
الحثّ على إحسان الخلق والتواضع وعدم الغلظة والتَّكلّف.
التحذير من الكلام على جهة التكثير والتكبر والتعاظم والتكلّف.', null, 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/5802', false),
(20631, 2, 201, 631, 'hadith', 'عن ابن عباس رضي الله عنهما قال: قال رسول الله صلى الله عليه وسلم لأشج عبد القيس: «إن فيك خصلتين يحبهما الله: الحلم والأناة».', 'Messenger of Allah (ﷺ) said to Ashaj Abdul-Qais (May Allah be pleased with him), "You possess two qualities that Allah loves. These are clemency and tolerance.".', 'ابن عباس رضي الله عنهما', 'Ibn ''Abbas (May Allah be pleased with them)', 'صحيح', 'رياض الصالحين 631', 'Riyad as-Salihin 631', 'ریاض الصالحین 631', 'رواه مسلم', null, null, null, 'sunnah.com', null, false, null, false),
(20632, 2, 201, 632, 'hadith', 'عن عائشة رضي الله عنها قالت: قال رسول الله صلى الله عليه وسلم: « إن الله رفيق يحب الرفق في الأمر كله».', 'The Messenger of Allah (ﷺ) said, "Allah is Forbearer and loves forbearance in all matters.".', 'عائشة رضي الله عنها', '''Aishah (May Allah be pleased with her)', 'صحيح', 'رياض الصالحين 632', 'Riyad as-Salihin 632', 'ریاض الصالحین 632', 'متفق عليه', null, null, null, 'sunnah.com', null, false, null, false),
(20633, 2, 201, 633, 'hadith', 'وعنها أن النبى صلى الله عليه وسلم قال: « إن الله رفيق يحب الرفق، ويعطى على الرفق ما لا يعطى على العنف ومالا يعطى على ما سواه».', 'The Prophet (ﷺ) said, "Allah is Forbearer and He loves forbearance, and rewards for forbearance while He does not reward severity, and does not give for any thing besides it (forbearance)."', null, '''Aishah (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 633', 'Riyad as-Salihin 633', 'ریاض الصالحین 633', 'رواه مسلم', null, null, null, 'sunnah.com', null, false, null, false),
(20634, 2, 201, 634, 'hadith', 'وعنها أن النبى صلى الله عليه وسلم قال: «إن الرفق لا يكون في شئ إلا زانه، ولا ينزع من شئ إلا شانه».', 'The Prophet (ﷺ) said, "Whenever forbearance is added to something, it adorns it; and whenever it is withdrawn from something, it leaves it defective.".', null, '''Aishah (May Allah be pleased with her)', 'صحيح', 'رياض الصالحين 634', 'Riyad as-Salihin 634', 'ریاض الصالحین 634', 'رواه مسلم', null, null, null, 'sunnah.com', null, false, null, false),
(20635, 2, 201, 635, 'hadith', 'عن أبى هريرة رضي الله عنه قال: بال أعرابى في المسجد فقام الناس إليه ليقعوا فيه، فقال النبى صلى الله عليه وسلم: «دعوه وأريقوا على بوله سجلاً من ماء، أو ذنوباً من ماء، فإنما بعثتم ميسرين ولم تبعثوا معسرين».', 'A bedouin urinated in the mosque and some people rushed to beat him up. The Prophet (ﷺ) said: "Leave him alone and pour a bucket of water over it. You have been sent to make things easy and not to make them difficult.".', 'أبى هريرة رضي الله عنه', 'Abu Hurairah (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 635', 'Riyad as-Salihin 635', 'ریاض الصالحین 635', 'رواه البخارى', 'قام أعرابي وشرع في البول في المسجد النبوي، فتناوله الناس بألسنتهم لا بأيديهم، أي: صاحوا به، فقال لهم النبي صلى الله عليه وسلم : دعوه فلما انتهى من بوله أمرهم أن يصبوا على المكان الذي بال فيه دلواً من ماء، وبين لهم أنهم دعاة للتيسير وليس للتنفير وإبعاد الناس عن الهدى.', 'جهل الأعرابي بأحكام الشريعة.
الاحتراز من النجاسة كان مقرراً في نفوس الصحابة.
تغيير المنكر يجب في حال القدرة عليه ولا يجوز تأخيره.
تغيير المنكر لابد أن تراعى فيه الحكمة والنظر في العواقب.
ينبغي للداعي أن يقدم المصلحة الراجحة في إنكاره للمنكر.
ينبغي الرفق بالجاهل وأخذه باليسر.
ينبغي تعظيم المساجد وتنزيهها عن الأقذار.
بيان حرص النبي صلى الله عليه وسلم على تعليم الناس الخير وشفقته على أمته.', 'أعرابي : هو نزيل البادية من العرب.
ليقعوا فيه : ليلوموه ويعنفوه.
أريقوا : صبوا.
سَجْلا : وهو الدلو الممتلئة ماء.
الذنوب : وهو الدلو الكبير الممتلئة ماء كذلك.
معسرين : مشددين ومنفرين.
مسجد : المسجد شرعًا: كل موضع يصلح للصلاة من الأرض، وخصصه العرف بالمكان المهيأ للصلوات الخمس.', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/5806', false),
(20636, 2, 201, 636, 'hadith', 'عن أنس رضي الله عنه عن النبى صلى الله عليه وسلم قال: "يسروا ولا تعسروا وبشروا ولا تنفروا.', 'The Prophet (ﷺ) said, "Make things easy and do not make them difficult, cheer the people up by conveying glad tidings to them and do not repulse (them).".', 'أنس رضي الله عنه', 'Anas (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 636', 'Riyad as-Salihin 636', 'ریاض الصالحین 636', 'متفق عليه', 'يَأمُرُ النبيُّ صلى الله عليه وسلم بالتخفيف والتيسير على الناس وعدم التَّعْسِيْر عليهم في جميع أمور الدين والدنيا، وذلك في حدود ما أباح الله وشرع.

ويَحُثُّ على تَبْشِيرِهم بالخير، وعدم تَنْفِيرِهم منه.', 'واجب المؤمن أن يحبب الناس بالله ويُرغِّبهم في الخير.
ينبغي على الداعي إلى الله أن ينظر بحكمة إلى كيفية تبليغ دعوة الإسلام إلى الناس.
التبشير يُولِّدُ السرورَ والإقبالَ والاطمئنانَ للداعي ولِمَا يَعرِضه على الناس.
التعسير يولِّدُ النفورَ والإدبارَ والتشكيكَ في كلام الداعي.
سعة رحمة الله بعباده وأنه رضي لهم دينًا سمحًا وشريعة ميسرة.
التيسير المأمور به هو ما جاءت به الشريعة.', null, 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/5866', false),
(20637, 2, 201, 637, 'hadith', 'عن جرير بن عبد الله رضي الله عنه قال: سمعت رسول الله صلى الله عليه وسلم يقول: «من يحرم الرفق يحرم الخير كله».', 'Messenger of Allah (ﷺ) said, "He who is deprived of forbearance and gentleness is, in fact, deprived of all good.".', 'جرير بن عبد الله رضي الله عنه', 'Jarir bin ''Abdullah (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 637', 'Riyad as-Salihin 637', 'ریاض الصالحین 637', 'رواه مسلم', null, null, null, 'sunnah.com', null, false, null, false),
(20638, 2, 201, 638, 'hadith', 'عن أبى هريرة رضي الله عنه أن رجلاً قال للنبى صلى الله عليه وسلم: أوصنى قال: "لا تغضب" فردد مراراً، قال: "لا تغضب".', 'A man asked the Prophet (ﷺ) to give him advice, and he (ﷺ) said, "Do not get angry." The man repeated that several times and he (ﷺ) replied (every time), "Do not get angry.".', 'أبى هريرة رضي الله عنه', 'Abu Hurairah (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 638', 'Riyad as-Salihin 638', 'ریاض الصالحین 638', 'رواه البخارى', 'طَلبَ أحدُ الصحابة رضوان الله عليهم من النبي صلى الله عليه وسلم أن يَدُلَّه على شيء ينفعه، فأمره ألّا يغضب، ومعنى ذلك أن يَجتنبَ الأسبابَ التي تحمله على الغضب، وأن يَضبطَ نفسَه إذا حَصَل له الغضب، فلا يَتَمادى مع غضبه بالقتل أوالضرب أوالسب ونحو ذلك. 

وردَّدَ الرجلُ طَلَبَ الوصيةِ مَرَّات، فلم يَزِدْه صلى الله عليه وسلم في الوصية على "لا تغضب".', 'التحذير من الغضب وأسبابه، فإنه جِماعُ الشر، والتحرُّزُ منه جماعُ الخير.
الغضب لله كالغضب عند انتهاك محارم الله من الغضب المحمود.
تَكرار الكلام عند الحاجة حتى يَعِيَه السامعُ ويُدرك أهميتَه.
فضيلة طلب الوصية من العالِم.', '---', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/4709', false),
(20639, 2, 201, 639, 'hadith', 'عن أبى يعلى شداد بن أوس رضي الله عنه، عن رسول الله صلى الله عليه وسلم قال: «إن الله كتب الإحسان على كل شئ، فإذا قتلتم فأحسنوا القتلة وإذا ذبحتم فأحسنوا الذبحة، وليحد أحدكم شفرته وليرح ذبيحته».', 'Messenger of Allah (ﷺ) said, "Verily Allah has prescribed Ihsan (kindness) for everything. So when you kill, you must make the killing in the best manner; when you slaughter, make your slaughter in the best manner. Let one of you sharpen his knife and give ease to his animal (in order to reduce his pain).".', 'أبى يعلى شداد بن أوس رضي الله عنه', 'Abu Ya''la Shaddad bin ''Aus (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 639', 'Riyad as-Salihin 639', 'ریاض الصالحین 639', 'رواه مسلم', 'يُخبرُ النبيُّ صلى الله عليه وسلم أن الله تعالى أوجبَ علينا الإحسانَ في كل الأشياء، والإحسان: هو مراقبة الله على الدوام، في عبادته وفي بذل الخير وكف الأذى عن المخلوقين، ومن ذلك الإحسان في القتل والذبح.
فالإحسان في القتل عند القصاص: بأن يختار أسهلَ الطُّرُق وأخَفَّها وأسرعَها زهوقًا للمقتول.
والإحسان في الذبح عند الذكاة: بأن يرفق بالبهيمة بإحداد الآلة، وألّا تُحَدَّ أمام الذبيحة وهي تنظر إليها، وألَّا تُذبح وهناك من الماشية ما ينظر إليها.', 'رحمة الله عزّ وجل ولطفه بالخلق.
إحسان القتل والذبح بأن يكون على الوجه المشروع.
كمال الشريعة واشتمالها على كل خير، ومن ذلك رحمة الحيوان والرفق به.
النهي عن المُثْلة بالإنسان بعد قتله.
تحريم كل ما فيه تعذيب للحيوان.', null, 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/66521', false),
(20640, 2, 201, 640, 'hadith', 'عن عائشة رضي الله عنها قالت: ما خير رسول الله صلى الله عليه وسلم بين أمرين قط إلا أخذ أيسرهما، ما لم يكن إثماً، فإن كان إثماً، كان أبعد الناس منه، وما انتقم رسول الله صلى الله عليه وسلم لنفسه في شئ قط، إلا أن تنتهك حرمة الله، فينتقم لله تعالى.', 'Whenever the Prophet (ﷺ) was given a choice between two matters, he would (always) choose the easier as long as it was not sinful to do so; but if it was sinful he was most strict in avoiding it. He never took revenge upon anybody for his own sake; but when Allah''s Legal Bindings were outraged, he would take revenge for Allah''s sake..', 'عائشة رضي الله عنها', '''Aishah (May Allah be pleased with her)', 'صحيح', 'رياض الصالحين 640', 'Riyad as-Salihin 640', 'ریاض الصالحین 640', 'متفق عليه', 'أَخْبَرَتْ أمُّ المؤمنين عائشةُ رضي الله عنها عن بعض أخلاق النبي صلى الله عليه وسلم، ومما ذَكَرَتْ: أنه صلى الله عليه وسلم ما خُيّر بين أمرين إلا أَخَذَ أَسْهَلْهُما ما لم يكن الأسهل مُقتضيًا للإثم، فإنه يكون أبعد الناس عنه ويختار حينئذ الأشدّ.


وما انتقم صلى الله عليه وسلم لنفسه خاصة بل كان يَسْمَحُ ويَعفو عن حقِّه إلا أنْ تُنْتَهَك حُرُمات الله فيكون لله ينتقم، وكان أشد الناس غضبًا لله.', 'استحباب الأخذ بالأَيْسر في الأمور ما لم يكن فيه معصية.
يُسْر الإسلام.
مشروعية الغضب لله تعالى.
ما كان عليه صلى الله عليه وسلم من الحِلْم والصبر والقيام بالحق في إقامة حدود الله تعالى.
قال ابن حجر: وفيه ترك الأخذ بالشيء العَسِر، والاقتناع باليُسْر، وترك الإلحاح فيما لا يضطر إليه.
الحث على العفو إلا في حقوق الله تعالى.', null, 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/6389', false)
